INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C1','soc',6,1,'u2',1,'선거의 의미와 필요성 — 나라를 운영하려면 결정할 중요한 일이 많지만 모든 국민이 직접 참여해 나랏일을 결정하고 살림을 운영하기는 어려워 대표를 뽑아 일을 맡김 · 국민이 자신들을 대표할 사람을 투표로 뽑는 일이 선거 · 유권자는 선거에서 대표를 뽑을 권리를 가진 사람 · 선거로 뽑는 대표: 대통령·시장·군수·구청장·도지사·교육감 등 · 민주주의는 국민이 나라의 주인으로서 권리를 갖고 자유롭고 평등하게 행사하는 정치 형태 · 선거는 국민이 정치에 참여하고 주인으로서 권리를 행사하는 가장 기본적인 방법이라 민주주의의 꽃이라 부름',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C2','soc',6,1,'u2',2,'선거가 중요한 까닭 — 선거로 뽑힌 대표는 국민의 행복한 삶과 미래를 위해 나라의 중요한 일을 결정하고 헌법과 법률에 따라 일함 · 대표를 잘못 뽑으면 나라 경제나 국민의 삶이 어려워지고 민주주의가 위기를 맞을 수 있음 · 뽑아야 할 사람: 국민을 위해 열심히 일할 사람, 더 살기 좋은 환경을 위해 노력하는 사람, 도덕적으로 올바르고 공정한 사람 · 대표가 지역 발전을 위해 열심히 일하면 지역이 변화해 더 살기 좋은 환경이 됨',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C3','soc',6,1,'u2',2,'선거 참여와 국민 주권 — 국민 주권은 나라의 중요한 일을 결정하는 최고의 권력인 주권이 국민에게 있음 · 선거는 국민 주권을 실현하는 가장 기본적이고 중요한 방법이라 소중한 한 표를 행사해야 함 · 한 표 차이로 결과가 달라질 수 있고, 국민의 참여로 대표와 정치, 사회가 달라질 수 있음 · 재검표는 개표 결과에 잘못이나 실수가 있는지 확인하려고 다시 검사하는 일로, 결과를 바꾸는 일이 아니라 확인하는 일',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C4','soc',6,1,'u2',3,'선거 과정 — 선거는 법에 정해진 절차에 따라 공정하게 치름 · 선거인 명부 작성(선거 관리 위원회가 투표할 수 있는 사람의 명단을 만듦) → 후보자 등록 → 선거 운동(선거 공보·후보자 토론회·거리 유세 등) → 투표(신분 확인 → 투표용지 받기 → 투표하기 → 투표함에 넣기) → 개표(선거 관리 위원회가 투표함을 열어 결과 확인) → 당선자 결정 및 당선증 발급 · 앞 걸음이 만든 것이 뒤 걸음의 재료가 됨 · 선거 공보는 후보자의 기호·이름·사진·공약 등을 실은 문서 · 투표소를 두는 까닭은 누구나 같은 조건에서 공정하게 투표하고 결과를 조작하지 못하게 하려는 것',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C5','soc',6,1,'u2',3,'선거 원칙과 다양한 투표 방법 — 보통 선거(18세 이상이면 누구나), 평등 선거(모든 사람이 한 표씩), 직접 선거(투표권을 가진 사람이 직접), 비밀 선거(누구에게 투표했는지 알 수 없게) · 원칙을 정한 까닭: 공정하고 민주적인 선거, 모든 사람에게 동등한 권리 · 국민 누구나 원칙을 지켜야 하며 상황에 따라 바꾸지 않음 · 거소 투표(투표소에 가기 어려운 유권자가 머무는 곳에서), 선상 투표(배에 탄 선원이 배에서) — 모든 사람이 평등하게 참여하도록 선거권을 보장 · 선거 관리 위원회는 선거와 투표가 공정하게 이루어지도록 관리하는 국가기관',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C6','soc',6,1,'u2',4,'모의 선거와 공약 평가 — 후보자 정하기 → 공약 정하기 → 선거 운동(벽보·연설·토론회) → 공약 평가 → 투표 → 개표 → 당선자 발표 · 선거 벽보는 공약을 알려 유권자가 투표할 때 참고하게 함 · 공약을 재는 잣대: 구체적인가, 실천할 수 있는가, 국민의 요구를 반영하는가 — 후보자의 목소리·말솜씨, 상대 깎아내리기, 우리 모둠의 공약인지는 잣대가 될 수 없음 · 투표할 때: 공약을 꼼꼼히 살펴 한 후보자에게만, 누구를 뽑았는지 말하지 않음, 스스로 정함 · 선거 운동은 양보와 타협의 자세로 공정하고 정정당당하게',ARRAY['[6사08-01] 민주주의에서 선거의 역할과 중요성을 이해하고, 선거 과정과 원칙에 따라 선거에 참여하는 태도를 기른다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C7','soc',6,1,'u2',5,'국가기관의 뜻과 있는 까닭 — 나랏일을 맡아 하는 곳이 국가기관 · 나라의 다양한 문제를 해결하려고 중요한 일을 결정하고 국민의 안전과 행복을 위해 일함 · 하는 일에 따라 국회(법을 만듦)·행정부(법에 따라 나라 살림을 맡음)·법원(법에 따라 판결)으로 나뉨 · 기관이 없으면 일상생활이 불편해지고 안전을 위협받으며 법을 지키지 않는 사람이 생길 수 있음 · 국가기관은 국민의 자유와 권리를 보장하기 위해 일함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C8','soc',6,1,'u2',6,'국회와 법이 만들어지는 과정 — 국회는 국민의 뜻에 따라 나라 운영의 근거가 되는 법을 만들고 나랏일이 잘 운영되는지 감시하고 견제하는 국가기관 · 국회의원은 국민을 대신해 중요한 일을 결정하는 국민의 대표 · 국민의 요구 → 국회의원이 법률안 제출 → 국회에서 심의하고 투표하여 결정 → 대통령이 서명하여 널리 알리고 시행 · 법률안은 법률이 될 사항을 정리해 국회에 내는 문서 · 대통령은 의견이 다르면 거부권을 행사해 국회에서 다시 심의하게 할 수 있음(법을 만드는 자리와 마지막 서명 자리가 나뉨)',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C9','soc',6,1,'u2',6,'국회가 하는 다른 일 — 국정 감사(행정부가 법에 따라 나라를 잘 운영하는지 확인·감독하고 잘못을 바로잡도록 요구), 예산안 심의(한 해 나라 살림에 쓸 돈의 계획을 살펴 정하고 잘 썼는지 살핌), 인사 청문회(일을 맡을 사람이 알맞은 능력을 갖췄는지 살핌) · 모두 국민을 대표해서 하는 일',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C10','soc',6,1,'u2',7,'행정부의 구성 — 행정부는 국회에서 만든 법에 따라 나라의 살림을 맡아 하는 국가기관으로 국민의 안전하고 편리한 삶을 위해 일함 · 대통령(국민이 선출, 행정부의 최고 책임자이자 우리나라의 대표), 국무총리(대통령을 보좌하고 행정 각부를 관리하며 대통령이 임무를 수행할 수 없을 때 대신함), 행정 각부 · 자리가 비어도 대통령의 일은 사라지지 않고 국무총리가 대신 맡음(나라의 살림은 멈출 수 없음), 대신 맡는 동안에도 국무총리의 본래 몫은 그대로',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C11','soc',6,1,'u2',7,'행정 각부와 국무 회의 — 행정 각부는 경제·교육·외교·국방·환경 등의 업무를 나눠 맡아 다양한 일을 함(한 곳이 모든 일을 도맡지 않음) · 카드 뉴스 같은 홍보로 하는 일을 알림 · 국무 회의에서 대통령·국무총리·행정 각부의 장 등 국무 위원이 나라의 중요한 일이나 정책을 함께 의논함 · 행정부 조직은 새로 만들어지거나 이름이 바뀌기도 함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C12','soc',6,1,'u2',8,'법원이 하는 일 — 사람들 사이에 다툼이 생기거나 범죄가 일어났을 때 재판을 통해 옳고 그름을 가리는 국가기관 · ① 개인 사이의 다툼 해결(층간 소음 피해 보상) ② 법을 어긴 사람을 처벌해 사회 질서 유지 ③ 개인과 국가·지방 자치 단체 사이의 갈등 해결(공사 피해 보상) · 피고인은 법을 어겼다고 판단해 재판에 세운 사람 · 법원이 없으면 다툼과 갈등의 옳고 그름을 가려 줄 곳이 없음',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C13','soc',6,1,'u2',8,'공정한 재판을 위한 제도 — 국민의 자유와 권리를 보장하려면 재판이 공정해야 함 · 법원의 독립과 법관의 신분 보장(외부 간섭 없이 판결) · 삼심 제도(하나의 사건에 원칙적으로 세 번까지 재판 — 잘못된 판결로 억울한 일을 막음, 1심 지방 법원 → 2심 고등 법원 → 3심 대법원, 판정이 달라질 수 있고 세 번이 상한) · 재판의 과정과 결과 공개(특별한 경우 제외) · 변호사는 법률 상담을 하고 의뢰인을 도와 변호함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C14','soc',6,1,'u2',9,'권력 분립과 견제 — 권력이 한곳에 모이면 마음대로 쓰거나 잘못된 결정을 내려 국민의 자유와 권리가 침해받을 수 있음 · 권력 분립은 국가 권력을 국회·행정부·법원이 나눠 맡도록 헌법으로 정한 것 · 한 기관이 중요한 일을 마음대로 처리하지 못하도록 서로 견제하고 균형을 이룸 → 국민의 자유와 권리 보장 · 견제 사례: 국회 → 행정부(국정 감사), 대통령(행정부) → 국회(법률안 거부권), 법원 → 행정부(헌법에 어긋난 명령 취소) · 견제는 누가 나빠서가 아니라 서로 바로잡으려는 일 · 국민도 시민 단체 활동, 누리집 게시판 의견, 주민 투표로 대표를 물러나게 하는 제도 등으로 견제함',ARRAY['[6사08-02] 국회·행정부·법원이 하는 일을 알아보고, 국가기관의 권력을 나누는 까닭을 탐구한다(차시 머리 주석 기준)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C15','soc',6,1,'u2',10,'미디어의 뜻과 종류 — 미디어는 사람들이 정보를 주고받으며 의사소통하기 위해 사용하는 수단 · 겉모습(옛날 것인지, 종이인지, 걸어 두는지)이 아니라 정보를 주고받는 수단인지로 정함(옛 선거 공고문과 선거 안내 누리집은 둘 다 미디어) · 옛사람의 미디어: 벽화, 말을 타고 소식 전하기, 새 다리에 편지 묶기 등 · 오늘날: 전화·책·신문·방송·사회 관계망 서비스 등 · 신문(글과 사진으로 새로운 정보), 방송(영상과 소리로 다양한 정보) — 많은 사람에게 신속하게, 사회 관계망 서비스(글·음성·영상 등 다양한 형태로 주고받으며 의사소통)',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C16','soc',6,1,'u2',11,'민주주의에서 미디어의 역할 — 사람들이 함께 정할 때 필요한 정보를 얻게 하고 많은 사람에게 같은 정보를 한꺼번에 전함 · ① 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전함 ② 사회에서 중요하게 여기는 가치나 규범을 보여 주어 존중하는 태도를 기르게 함 ③ 사회문제를 지목하고 원인·영향·해결 방안을 제시해 여러 관점에서 이해하게 함 · 주고받는 정보와 생각이 의사 결정에 영향을 미쳐 중요 · 1인 미디어로 누구나 정보의 생산자가 되어 생각을 더 활발하게 나눔 · 안내소·파수꾼에 빗댈 수 있음',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C17','soc',6,1,'u2',12,'허위 조작 정보와 비판적 분석 — 허위 조작 정보는 사실과 다른 내용을 진짜처럼 꾸며 전하는 정보, 가짜 뉴스는 뉴스처럼 보이지만 거짓이거나 사실을 잘못 해석한 정보 · 생기는 까닭: 사실을 정확히 확인하지 않아서, 관심을 끌려고, 지지하는 쪽의 당선을 도우려고 · 사실과 다른 정보는 사람들의 권리를 침해하거나 사회 질서를 무너뜨릴 수 있음 · 여론은 많은 사람이 갖고 있는 공통된 의견 · 잘못된 여론은 합리적인 의사 결정을 방해해 민주주의를 위협 · 사실이 아니라고 밝혀져도 그 정보를 믿고 이미 정한 일은 되돌아오지 않음 → 미디어의 내용을 비판적으로 분석하여 이용',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C18','soc',6,1,'u2',13,'미디어를 올바르게 이용하는 태도 — 오보(사실 확인이 부족해 사실과 다른 정보를 전함)도 있어 보도라고 무조건 믿지 않고 다른 자료로 확인 · 같은 대상도 관점에 따라 다르게 전하므로 다양한 관점을 균형 있게 살핌 · 맞춤형 정보만 보면 관점이 다른 정보를 접하지 않아 편견이 강해짐 · 뉴스 형식을 흉내 낸 제목, 믿을 만한 사람이 전한 정보, 이름 검색 결과도 확인 · 검토 기준 넷: 뉴스 형식 흉내, 만든 사람과 날짜, 믿을 만한 출처, 타당한 근거 — 하나라도 걸리면 따져 봄(작성자와 날짜가 또렷해도 허위일 수 있음) · 이용 습관 점검·개선, 확인되지 않은 정보 공유하지 않기 · 미디어 비평가는 정확한 사실·균형·대안을 점검',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO6-1-u2-C19','soc',6,1,'u2',14,'뉴스 기사 쓰기와 검토 — 주제 고르기 → 조사하고 정리하기 → 기사 쓰기 → 기준에 따라 검토하기 · 기사가 될 만한 일: 최근에 생기거나 밝혀진 일, 영향을 받는 사람이 많은 일, 평범하거나 쉽게 겪을 수 없는 일(날마다 되풀이되는 일은 아님) · 설문지·인터넷 검색·면담으로 조사하고 출처를 함께 적으며 사실과 다르거나 왜곡된 내용은 적지 않음 · 기사 제목·작성일·작성자를 적음 · 검토 기준: 사실인가, 과장·왜곡이 있는가, 출처가 있는가, 같은 주제인데 다른 점이 있는가 · 무엇을 실을지는 사람마다 달라 같은 일도 기사가 달라짐 · 출처를 밝혀야 신뢰를 줌',ARRAY['[6사08-03] 민주주의에서 미디어의 역할을 이해하고, 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다(차시 머리 주석 기준)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X01','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'우리나라에서는 모든 국민이 정치에 직접 참여해 나라의 일을 결정한다고 여겨 대표를 뽑는 까닭을 놓친다','모두 직접은 어려워 대표에게 맡겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X02','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'선거의 뜻이나 유권자의 뜻을 잘못 안다(대표를 추첨·임명으로 정한다고, 후보자를 유권자라고 여기는 등)','국민이 투표로 대표를 뽑아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X03','soc',6,'u2',ARRAY['SO6-1-u2-C1']::text[],'민주주의의 뜻이나 선거를 민주주의의 꽃이라 부르는 까닭을 잘못 안다','국민이 주인 · 권리를 행사하는 기본 방법') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X04','soc',6,'u2',ARRAY['SO6-1-u2-C2']::text[],'선거로 뽑힌 대표는 마음대로 일해도 되고 누가 뽑히든 나라와 지역에 달라질 것이 없다고 여긴다','헌법과 법률에 따라 · 잘못 뽑으면 어려워져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X05','soc',6,'u2',ARRAY['SO6-1-u2-C2','SO6-1-u2-C6']::text[],'대표를 고르는 기준을 인기·말솜씨·겉모습처럼 공약이나 됨됨이와 관계없는 것에 둔다','국민을 위해 일할 사람 · 공정한 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X06','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'내 한 표로는 선거 결과가 달라지지 않는다고 여겨 참여의 중요성을 놓친다','한 표 차이로 달라질 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X07','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'국민 주권의 뜻을 잘못 안다(주권이 대표나 정부에게 있다고 여기는 등)','주권은 국민에게 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X08','soc',6,'u2',ARRAY['SO6-1-u2-C3']::text[],'재검표를 결과를 바꾸거나 다시 투표하는 일로 여긴다','잘못이 없는지 확인하는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X09','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거 과정의 차례를 뒤바꾼다(개표가 투표보다 먼저라고, 후보자 등록이 명부 작성보다 앞선다고 여기는 등)','명부 → 등록 → 운동 → 투표 → 개표 → 당선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X10','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거 과정의 걸음과 그 걸음에서 하는 일·하는 사람을 잘못 짝짓는다(개표를 후보자가 한다고 여기는 등)','선거 관리 위원회 · 후보자 · 유권자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X11','soc',6,'u2',ARRAY['SO6-1-u2-C4']::text[],'선거를 정해진 절차 없이 형편에 따라 치러도 된다고 여겨 법에 정해진 절차의 까닭(공정)을 놓친다','절차가 있어야 공정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X12','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'네 선거 원칙(보통·평등·직접·비밀)의 이름과 뜻을 바꾸어 짝짓는다','누구나 · 한 표씩 · 직접 · 비밀') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X13','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'선거 원칙을 상황에 따라 바꿀 수 있다고 여기거나 원칙을 둔 까닭(공정·동등한 권리)을 놓친다','누구나 늘 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X14','soc',6,'u2',ARRAY['SO6-1-u2-C5']::text[],'투표소에 가기 어렵거나 배에 탄 유권자는 투표할 수 없다고 여겨 다양한 투표 방법을 놓친다','거소 투표 · 선상 투표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X15','soc',6,'u2',ARRAY['SO6-1-u2-C6']::text[],'공약을 재는 잣대가 아닌 것(후보자의 목소리·상대 깎아내리기·우리 모둠의 공약인지)을 잣대로 삼는다','구체적 · 실천 가능 · 국민의 요구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X16','soc',6,'u2',ARRAY['SO6-1-u2-C6','SO6-1-u2-C5']::text[],'투표할 때 지킬 점을 놓친다(친구와 함께 정해 똑같이 찍기, 여러 후보자에게 표시하기, 누구를 뽑았는지 말하기 등)','스스로 · 한 후보자에게만 · 비밀') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X17','soc',6,'u2',ARRAY['SO6-1-u2-C7']::text[],'국가기관의 뜻이나 국가기관이 있는 까닭을 잘못 안다(일하는 사람 수·건물에 따라 나뉜다고, 기관이 없어도 일이 저절로 처리된다고 여기는 등)','하는 일에 따라 · 국민의 자유와 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X18','soc',6,'u2',ARRAY['SO6-1-u2-C7','SO6-1-u2-C8','SO6-1-u2-C10','SO6-1-u2-C12']::text[],'국회·행정부·법원이 하는 일을 서로 바꾸어 안다','법을 만듦 · 살림을 맡음 · 판결함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X19','soc',6,'u2',ARRAY['SO6-1-u2-C8']::text[],'법이 만들어지는 과정의 차례나 자리를 잘못 안다(대통령이 법을 만든다고, 국민의 요구 없이 시작된다고 여기는 등)','요구 → 법률안 → 심의·투표 → 서명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X20','soc',6,'u2',ARRAY['SO6-1-u2-C8']::text[],'대통령이 법률안에 서명하거나 되돌려 보내는 까닭을 잘못 안다(대통령이 법을 대신 만든다고, 되돌려 보내면 법이 사라진다고 여기는 등)','국회가 마음대로 못 하게 · 다시 심의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X21','soc',6,'u2',ARRAY['SO6-1-u2-C9']::text[],'국정 감사·예산안 심의·인사 청문회 같은 국회의 다른 일과 그 대상을 잘못 짝짓는다','살림 확인 · 나라 돈 계획 · 능력 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X22','soc',6,'u2',ARRAY['SO6-1-u2-C10']::text[],'대통령·국무총리·행정 각부의 역할을 바꾸어 알거나, 대통령 자리가 비면 그 일이 멈춘다고 여긴다','국무총리가 보좌하고 대신해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X23','soc',6,'u2',ARRAY['SO6-1-u2-C11']::text[],'행정 각부와 국무 회의를 잘못 안다(한 부가 모든 업무를 도맡는다고, 각 부가 중요한 일을 따로 정한다고 여기는 등)','업무를 나눠 맡고 함께 의논해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X24','soc',6,'u2',ARRAY['SO6-1-u2-C12']::text[],'법원이 하는 일을 장면과 잘못 짝짓거나, 재판의 목적(옳고 그름을 가려 질서 유지)을 놓친다','다툼 해결 · 처벌 · 국가와의 갈등') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X25','soc',6,'u2',ARRAY['SO6-1-u2-C13']::text[],'공정한 재판을 위한 제도를 잘못 안다(재판을 모두 비공개로 한다고, 법원이 다른 기관과 협의해 판결한다고 여기는 등)','독립 · 세 번까지 · 공개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X26','soc',6,'u2',ARRAY['SO6-1-u2-C13']::text[],'삼심 제도를 잘못 안다(첫 판결로 끝난다고, 원하는 만큼 계속 재판받을 수 있다고, 다시 물어도 판결이 바뀌지 않는다고 여기는 등)','원칙적으로 세 번까지 · 바뀔 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X27','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'권력이 한곳에 모일 때의 문제를 놓치거나 권력 분립의 뜻을 잘못 안다','마음대로 쓰면 자유와 권리가 침해돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X28','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'견제 사례에서 누가 누구를 견제하는지 바꾸어 안다','국정 감사 · 거부권 · 명령 취소') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X29','soc',6,'u2',ARRAY['SO6-1-u2-C14']::text[],'권력을 나누는 까닭을 잘못 알거나(일을 빨리 하려고, 한 기관을 키우려고), 견제를 서로 미워하는 일로 여기거나, 국민도 견제할 수 있음을 놓친다','견제와 균형 · 국민의 자유와 권리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X30','soc',6,'u2',ARRAY['SO6-1-u2-C15']::text[],'미디어를 겉모습(종이인지·최신 기계인지·걸어 두는지)으로 정해, 정보를 주고받는 수단이라는 뜻을 놓친다','정보를 주고받는 수단인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X31','soc',6,'u2',ARRAY['SO6-1-u2-C15']::text[],'신문·방송·사회 관계망 서비스 같은 미디어의 종류와 특징을 바꾸어 짝짓는다','글과 사진 · 영상과 소리 · 주고받기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X32','soc',6,'u2',ARRAY['SO6-1-u2-C16']::text[],'민주주의에서 미디어의 세 역할(새로운 사실·가치나 규범·사회문제와 해결 방안)을 사례와 잘못 짝짓는다','사실 · 가치 · 문제와 해결') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X33','soc',6,'u2',ARRAY['SO6-1-u2-C16']::text[],'미디어가 사람들의 의사 결정에 영향을 미친다는 점이나, 1인 미디어로 누구나 정보를 만들 수 있다는 점을 놓친다','정보와 생각이 결정에 영향 · 누구나 생산자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X34','soc',6,'u2',ARRAY['SO6-1-u2-C17']::text[],'허위 조작 정보·가짜 뉴스·여론의 뜻을 잘못 안다','꾸민 정보 · 뉴스 흉내 · 공통된 의견') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X35','soc',6,'u2',ARRAY['SO6-1-u2-C17']::text[],'사실이 아니라고 밝혀지면 그 정보로 생긴 피해도 모두 저절로 되돌아온다고 여겨, 미리 따져 봐야 하는 까닭을 놓친다','이미 정한 일은 남아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X36','soc',6,'u2',ARRAY['SO6-1-u2-C17','SO6-1-u2-C18']::text[],'허위 조작 정보가 있으니 미디어를 아예 쓰지 말자거나 미디어가 전하는 정보는 모두 거짓이라고 여긴다','따져 보고 이용해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X37','soc',6,'u2',ARRAY['SO6-1-u2-C18']::text[],'신문·방송에 보도된 것, 믿을 만한 사람이 전한 것, 작성자와 날짜가 적힌 것은 확인 없이 그대로 믿어도 된다고 여긴다','다른 자료로 확인 · 하나라도 걸리면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X38','soc',6,'u2',ARRAY['SO6-1-u2-C18']::text[],'맞춤형 정보나 내 관점에 맞는 정보만 보거나, 믿고 싶지 않은 정보를 확인 없이 거짓이라 정한다','다양한 관점을 균형 있게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X39','soc',6,'u2',ARRAY['SO6-1-u2-C19']::text[],'뉴스 기사가 될 만한 일의 조건을 잘못 알거나(날마다 되풀이되는 일), 같은 일은 누가 써도 기사가 같다고 여긴다','최근 · 영향 · 쉽게 겪을 수 없는 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO6-1-u2-X40','soc',6,'u2',ARRAY['SO6-1-u2-C19']::text[],'기사를 쓰며 출처를 빼거나 사실을 부풀리고, 기준에 따른 검토를 놓친다','출처 · 사실 · 과장 없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#1','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'mc','auto','국민이 자신들을 대표할 사람을 투표로 뽑는 일을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"mc","stem":"국민이 자신들을 대표할 사람을 투표로 뽑는 일을 무엇이라고 하나요?","options":[{"t":"선거","correct":true},{"t":"추첨","mis":"SO6-1-u2-X02"},{"t":"임명","mis":"SO6-1-u2-X02"},{"t":"회식","mis":"SO6-1-u2-X01"}],"explanation":["투표로 뽑아요.","대표를 뽑는 일이에요.","선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#2','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'sa','auto','선거에서 대표를 뽑을 수 있는 권리를 가진 사람을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"sa","stem":"선거에서 대표를 뽑을 수 있는 권리를 가진 사람을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["유권자"],"explanation":["권리를 가진 사람이에요.","유◯자예요.","유권자예요."],"mis":"SO6-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#3','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'ox','auto','우리나라에서는 모든 국민이 정치에 직접 참여하여 나라의 일을 모두 결정해요.',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"ox","stem":"우리나라에서는 모든 국민이 정치에 직접 참여하여 나라의 일을 모두 결정해요.","answer":"X","reason_options":[{"t":"모든 국민이 직접 나랏일을 결정하기 어려워 대표를 뽑아 맡기기 때문에","correct":true},{"t":"나랏일은 국민 모두가 날마다 모여 정하기 때문에","mis":"SO6-1-u2-X01"}],"mis":"SO6-1-u2-X01","explanation":["모두 직접 하기는 어려워요.","대표를 뽑아 맡겨요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#4','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',1,'mc','auto','선거로 뽑는 우리나라의 대표로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"mc","stem":"선거로 뽑는 우리나라의 대표로 알맞은 것은 어느 것인가요?","options":[{"t":"교육감","correct":true},{"t":"은행원","mis":"SO6-1-u2-X02"},{"t":"기자","mis":"SO6-1-u2-X02"},{"t":"운동선수","mis":"SO6-1-u2-X02"}],"explanation":["선거로 뽑는 자리예요.","지역의 교육을 맡는 대표예요.","교육감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#5','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','메모의 ㉠~㉢을 이어 읽을 때 대표를 뽑는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X01','SO6-1-u2-X02']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"메모의 ㉠~㉢을 이어 읽을 때 대표를 뽑는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결정할 일은 많은데 모든 국민이 직접 정하기 어렵기 때문에","correct":true},{"t":"나랏일이 적어 몇 사람만 있으면 되기 때문에","mis":"SO6-1-u2-X01"},{"t":"국민은 나랏일에 관심을 두면 안 되기 때문에","mis":"SO6-1-u2-X01"},{"t":"대표가 국민보다 언제나 더 많이 알기 때문에","mis":"SO6-1-u2-X02"}],"explanation":["㉠은 일이 많다는 거예요.","㉡은 모두 직접은 어렵다는 거예요.","그래서 대표를 뽑아요."],"asset":{"type":"passage","lines":["㉠ 나라를 운영하려면 결정해야 할 중요한 일이 아주 많다.","㉡ 모든 국민이 한자리에 모여 나랏일을 모두 직접 정하기는 어렵다.","㉢ 그래서 국민은 자신을 대신할 대표를 뽑아 나랏일을 맡긴다."],"title":"대표를 뽑는 까닭 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#6','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'blank','auto','민주주의란 국민이 국가의 (    )으로서 권리를 갖고, 그 권리를 자유롭고 평등하게 행사하는 정치 형태예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"blank","stem":"민주주의란 국민이 국가의 (    )으로서 권리를 갖고, 그 권리를 자유롭고 평등하게 행사하는 정치 형태예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"주인","correct":true},{"t":"손님","mis":"SO6-1-u2-X03"},{"t":"구경꾼","mis":"SO6-1-u2-X03"},{"t":"심부름꾼","mis":"SO6-1-u2-X03"}],"explanation":["나라의 주인은 누구일까요?","국민이 권리를 가져요.","주인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#7','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','세 친구가 말한 경험의 공통점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"세 친구가 말한 경험의 공통점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모두 대표를 뽑는 일과 관련 있다","correct":true},{"t":"모두 법을 만드는 일과 관련 있다","mis":"SO6-1-u2-X02"},{"t":"모두 물건을 사고파는 일과 관련 있다","mis":"SO6-1-u2-X02"},{"t":"모두 대표를 추첨으로 정한 경험이다","mis":"SO6-1-u2-X02"}],"explanation":["학급 회장, 투표소, 연설이에요.","모두 대표를 뽑는 장면이에요.","선거와 관련 있어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"학급 회장 선거에서 투표해 본 적이 있어."},{"who":"친구 나","text":"부모님을 따라 투표소에 가 본 적이 있어."},{"who":"친구 다","text":"거리에서 후보자가 연설하는 모습을 본 적이 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#8','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"선거","r":"국민이 대표할 사람을 투표로 뽑는 일"},{"l":"유권자","r":"대표를 뽑을 수 있는 권리를 가진 사람"},{"l":"민주주의","r":"국민이 주인으로서 권리를 갖고 행사하는 정치 형태"},{"l":"대표","r":"국민을 대신해 나랏일을 맡는 사람"}],"mis":"SO6-1-u2-X02","explanation":["뽑는 일 · 뽑는 사람이에요.","주인으로서 권리를 행사해요.","대표는 맡는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#9','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',2,'mc','auto','마을 게시판에 이런 행사 안내를 붙인 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"마을 게시판에 이런 행사 안내를 붙인 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 선거에 참여하도록 북돋우려고","correct":true},{"t":"사진을 많이 모으려고","mis":"SO6-1-u2-X03"},{"t":"음료를 팔려고","mis":"SO6-1-u2-X03"},{"t":"투표하러 가지 않게 하려고","mis":"SO6-1-u2-X01"}],"explanation":["투표를 마치고 찍은 사진이에요.","투표는 국민의 권리예요.","참여를 북돋우려는 거예요."],"asset":{"type":"passage","lines":["「투표를 마치고 투표소 밖에서 찍은 사진을 올려 주세요.」","「참여해 주신 분 가운데 몇 분께 음료를 드립니다.」","「투표는 국민의 권리입니다.」"],"title":"어느 마을 게시판에 붙은 행사 안내"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_basic#10','soc',6,1,'u2','L01','g6_1_soc_u2_L01_basic','lesson_basic','SO6-1-u2-C1',3,'error','auto','선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"error","stem":"선거를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「대표는 나라에서 아무나 골라 정해 주는 거야.」","correct":true,"mis_target":"SO6-1-u2-X02"},{"t":"친구 가 — 「국민이 투표로 대표를 뽑는 일이 선거야.」","mis":"SO6-1-u2-X02"},{"t":"친구 나 — 「뽑은 대표에게 나랏일을 맡기는 거야.」","mis":"SO6-1-u2-X01"}],"explanation":["대표는 누가 뽑을까요?","국민이 투표로 뽑아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#1','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',2,'sa','auto','선거는 국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이라 「민주주의의 ○」이라고 불려요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"sa","stem":"선거는 국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이라 「민주주의의 ○」이라고 불려요. ○에 알맞은 한 글자를 쓰세요.","answer":["꽃"],"explanation":["가장 빛나는 부분이에요.","봄에 피어요.","꽃이에요."],"mis":"SO6-1-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#2','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',2,'ox','auto','오늘날 대부분의 민주주의 국가는 자신들을 대신할 대표를 뽑아 나라의 중요한 일을 맡기고 있어요.',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"ox","stem":"오늘날 대부분의 민주주의 국가는 자신들을 대신할 대표를 뽑아 나라의 중요한 일을 맡기고 있어요.","answer":"O","reason_options":[{"t":"모든 국민이 직접 나랏일을 결정하고 살림을 운영하기 어렵기 때문에","correct":true},{"t":"민주주의 국가에서는 국민이 나랏일에 참여할 수 없기 때문에","mis":"SO6-1-u2-X01"}],"mis":"SO6-1-u2-X01","explanation":["대표에게 맡겨요.","모두 직접은 어려워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#3','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','반 친구 모두가 한꺼번에 전교 회의에 갈 수 없어 학급 대표를 뽑아 보내는 것과 가장 비슷한 까닭은 메모의 어느 것인가요?',ARRAY['SO6-1-u2-X01']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"반 친구 모두가 한꺼번에 전교 회의에 갈 수 없어 학급 대표를 뽑아 보내는 것과 가장 비슷한 까닭은 메모의 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SO6-1-u2-X01"},{"t":"㉢","mis":"SO6-1-u2-X01"},{"t":"㉠과 ㉢","mis":"SO6-1-u2-X01"}],"explanation":["모두 갈 수 없어요.","모두 직접 정하기 어려운 것과 같아요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 나라를 운영하려면 결정해야 할 중요한 일이 아주 많다.","㉡ 모든 국민이 한자리에 모여 나랏일을 모두 직접 정하기는 어렵다.","㉢ 그래서 국민은 자신을 대신할 대표를 뽑아 나랏일을 맡긴다."],"title":"대표를 뽑는 까닭 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#4','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','민주주의에서 선거가 갖는 뜻을 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"민주주의에서 선거가 갖는 뜻을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"유권자의 뜻이 선거 결과에 반영되어 나랏일을 정하는 데 영향을 미친다","correct":true},{"t":"선거 결과는 유권자의 뜻과 관계없이 정해진다","mis":"SO6-1-u2-X03"},{"t":"선거가 끝나면 국민은 나랏일과 상관이 없어진다","mis":"SO6-1-u2-X03"},{"t":"선거는 대표끼리 서로를 뽑는 일이다","mis":"SO6-1-u2-X02"}],"explanation":["유권자의 뜻이 담겨요.","결과에 반영돼요.","나랏일에 영향을 미쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#5','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'mc','auto','「민주주의의 꽃」이라는 말에 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「민주주의의 꽃」이라는 말에 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 주인으로서 권리를 행사하는 가장 기본적인 방법이 선거라는 뜻","correct":true},{"t":"선거 날에는 꽃을 나누어 준다는 뜻","mis":"SO6-1-u2-X03"},{"t":"선거는 보기에만 좋고 쓸모는 없다는 뜻","mis":"SO6-1-u2-X03"},{"t":"선거가 끝나면 국민의 권리도 끝난다는 뜻","mis":"SO6-1-u2-X03"}],"explanation":["꽃은 가장 빛나는 부분이에요.","권리를 행사하는 방법이에요.","가장 기본적인 방법이라는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#6','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'ox','auto','학급 회장 선거도 구성원이 대표를 투표로 뽑는다는 점에서 나라의 선거와 같은 뜻을 지녀요.',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"ox","stem":"학급 회장 선거도 구성원이 대표를 투표로 뽑는다는 점에서 나라의 선거와 같은 뜻을 지녀요.","answer":"O","reason_options":[{"t":"구성원이 자신을 대신할 사람을 투표로 뽑아 일을 맡기기 때문에","correct":true},{"t":"학급 회장은 선생님이 정해 주기 때문에","mis":"SO6-1-u2-X02"}],"mis":"SO6-1-u2-X02","explanation":["구성원이 뽑아요.","대신할 사람에게 맡겨요.","같은 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#7','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',3,'error','auto','민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"error","stem":"민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「민주주의에서는 대표가 주인이고 국민은 따르기만 해.」","correct":true,"mis_target":"SO6-1-u2-X03"},{"t":"친구 가 — 「국민이 나라의 주인으로서 권리를 가져.」","mis":"SO6-1-u2-X03"},{"t":"친구 다 — 「그 권리를 자유롭고 평등하게 행사해.」","mis":"SO6-1-u2-X03"}],"explanation":["주인은 누구일까요?","국민이 주인이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#8','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'mc','auto','선거로 뽑는 대표 카드를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X02','SO6-1-u2-X01']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"선거로 뽑는 대표 카드를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라 전체의 대표뿐 아니라 지역과 교육을 맡을 대표도 선거로 뽑는다","correct":true},{"t":"나라 전체의 대표 한 사람만 선거로 뽑는다","mis":"SO6-1-u2-X02"},{"t":"지역의 대표는 나라에서 정해 준다","mis":"SO6-1-u2-X02"},{"t":"선거로 뽑는 대표는 모두 같은 일을 한다","mis":"SO6-1-u2-X01"}],"explanation":["대통령이 있어요.","시장·군수도 있어요.","교육감도 있어요."],"asset":{"type":"passage","lines":["대통령 · 도지사 · 시장","군수 · 구청장 · 교육감"],"title":"선거로 뽑는 대표 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#9','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'mc','auto','대표를 뽑아 일을 맡긴 뒤에도 국민이 나라의 주인이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"대표를 뽑아 일을 맡긴 뒤에도 국민이 나라의 주인이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 스스로 뽑아 뜻을 맡긴 것이고, 다음 선거에서 다시 뜻을 나타낼 수 있기 때문에","correct":true},{"t":"대표를 뽑으면 국민의 권리는 사라지기 때문에","mis":"SO6-1-u2-X03"},{"t":"대표가 국민 대신 주인이 되기 때문에","mis":"SO6-1-u2-X03"},{"t":"국민은 아무 일도 하지 않아도 되기 때문에","mis":"SO6-1-u2-X01"}],"explanation":["누가 뽑았나요?","뜻을 맡긴 거예요.","다시 뜻을 나타낼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L01_challenge#10','soc',6,1,'u2','L01','g6_1_soc_u2_L01_challenge','lesson_challenge','SO6-1-u2-C1',4,'essay','teacher','모든 국민이 직접 나랏일을 정하지 않고 선거로 대표를 뽑아 맡기는 까닭을 쓰고, 그런데도 선거를 「민주주의의 꽃」이라 부르는 까닭을 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"essay","stem":"모든 국민이 직접 나랏일을 정하지 않고 선거로 대표를 뽑아 맡기는 까닭을 쓰고, 그런데도 선거를 「민주주의의 꽃」이라 부르는 까닭을 이어 쓰세요.","answer_guide":{"answer":"예: 나라를 운영하려면 정할 일이 많은데 모든 국민이 직접 참여해 나랏일을 모두 정하기는 어렵기 때문에 대표를 뽑아 일을 맡긴다. 그래도 그 대표를 국민이 직접 투표로 뽑고 그 뜻이 결과에 반영되므로, 선거는 국민이 나라의 주인으로서 권리를 행사하는 가장 기본적인 방법이라 민주주의의 꽃이라고 부른다.","scoring_points":["대표를 뽑는 까닭을 썼는가","선거에서 국민이 권리를 행사함을 썼는가","민주주의의 꽃이라 부르는 까닭과 이었는가"]},"explanation":["모두 직접은 어려워요.","국민이 뽑아요.","주인의 권리를 행사해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#1','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C2',1,'mc','auto','선거로 뽑힌 대표는 무엇에 따라 일하나요?',ARRAY['SO6-1-u2-X04']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C2","difficulty":1,"kind":"mc","stem":"선거로 뽑힌 대표는 무엇에 따라 일하나요?","options":[{"t":"헌법과 법률","correct":true},{"t":"자기 마음","mis":"SO6-1-u2-X04"},{"t":"가장 친한 사람의 말","mis":"SO6-1-u2-X04"},{"t":"그날의 기분","mis":"SO6-1-u2-X04"}],"explanation":["정해진 기준이 있어요.","나라의 법이에요.","헌법과 법률이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#2','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C3',1,'sa','auto','나라의 중요한 일을 결정하는 최고의 권력인 주권이 국민에게 있다는 뜻의 말은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C3","difficulty":1,"kind":"sa","stem":"나라의 중요한 일을 결정하는 최고의 권력인 주권이 국민에게 있다는 뜻의 말은 무엇인가요? 네 글자로 쓰세요.","answer":["국민주권","국민 주권"],"explanation":["주권이 누구에게 있나요?","국민◯◯이에요.","국민 주권이에요."],"mis":"SO6-1-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#3','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C3',1,'ox','auto','재검표는 개표 결과에 잘못이나 실수가 있는지 확인하려고 다시 검사하는 일이에요.',ARRAY['SO6-1-u2-X08']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C3","difficulty":1,"kind":"ox","stem":"재검표는 개표 결과에 잘못이나 실수가 있는지 확인하려고 다시 검사하는 일이에요.","answer":"O","reason_options":[{"t":"결과를 바꾸려는 것이 아니라 확인하려는 일이기 때문에","correct":true},{"t":"재검표를 하면 반드시 결과가 바뀌기 때문에","mis":"SO6-1-u2-X08"}],"mis":"SO6-1-u2-X08","explanation":["다시 검사해요.","실수를 확인해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#4','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C2',1,'mc','auto','선거에서 어떤 사람을 대표로 뽑아야 할까요?',ARRAY['SO6-1-u2-X05']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C2","difficulty":1,"kind":"mc","stem":"선거에서 어떤 사람을 대표로 뽑아야 할까요?","options":[{"t":"국민을 위해 열심히 일할 사람","correct":true},{"t":"목소리가 가장 큰 사람","mis":"SO6-1-u2-X05"},{"t":"사진이 가장 멋진 사람","mis":"SO6-1-u2-X05"},{"t":"나와 가장 친한 사람","mis":"SO6-1-u2-X05"}],"explanation":["대표는 국민을 위해 일해요.","열심히 일할 사람이에요.","국민을 위해 일할 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#5','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C3',2,'mc','auto','자료에서 같던 결과를 갈라 놓은 것은 무엇인가요?',ARRAY['SO6-1-u2-X08','SO6-1-u2-X06']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"mc","stem":"자료에서 같던 결과를 갈라 놓은 것은 무엇인가요?","options":[{"t":"아직 투표하지 않았던 사람의 한 표","correct":true},{"t":"표를 다시 센 일","mis":"SO6-1-u2-X08"},{"t":"표를 다시 센 횟수","mis":"SO6-1-u2-X08"},{"t":"결과를 발표한 사람","mis":"SO6-1-u2-X06"}],"explanation":["다시 세어도 그대로였어요.","새로 들어온 것이 있어요.","한 사람의 한 표예요."],"asset":{"type":"passage","lines":["① 투표를 마치고 세어 보니 ㉮ 쪽과 ㉯ 쪽의 표가 똑같았다.","② 혹시 실수가 있었는지 표를 다시 세어 보았지만 결과는 그대로였다.","③ 늦게 도착한, 아직 투표하지 않았던 한 사람이 표를 냈다.","④ 그 한 표로 결과가 한쪽으로 갈렸다."],"title":"어느 모둠의 투표 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#6','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C3',2,'blank','auto','선거는 민주주의 국가에서 (    )을 실현하는 가장 기본적이고 중요한 방법이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X07','SO6-1-u2-X05']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"blank","stem":"선거는 민주주의 국가에서 (    )을 실현하는 가장 기본적이고 중요한 방법이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"국민 주권","correct":true},{"t":"대표의 권력","mis":"SO6-1-u2-X07"},{"t":"정부의 명령","mis":"SO6-1-u2-X07"},{"t":"후보자의 인기","mis":"SO6-1-u2-X05"}],"explanation":["주권은 누구에게 있나요?","국민에게 있어요.","국민 주권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#7','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C2',2,'mc','auto','대표를 뽑는 선거가 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X04']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C2","difficulty":2,"kind":"mc","stem":"대표를 뽑는 선거가 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"대표가 나라의 중요한 일을 결정하기 때문에","correct":true},{"t":"대표는 아무 일도 결정하지 않기 때문에","mis":"SO6-1-u2-X04"},{"t":"선거 날이 쉬는 날이기 때문에","mis":"SO6-1-u2-X04"},{"t":"누가 뽑혀도 똑같기 때문에","mis":"SO6-1-u2-X04"}],"explanation":["대표가 무엇을 하나요?","중요한 일을 정해요.","그래서 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#8','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C2',2,'mc','auto','자료처럼 동네가 달라진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X06','SO6-1-u2-X04','SO6-1-u2-X08']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C2","difficulty":2,"kind":"mc","stem":"자료처럼 동네가 달라진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"선거로 뽑힌 대표가 지역 발전을 위해 열심히 일했기 때문에","correct":true},{"t":"주민들이 선거에 관심을 끊었기 때문에","mis":"SO6-1-u2-X06"},{"t":"대표가 누구든 저절로 바뀌기 때문에","mis":"SO6-1-u2-X04"},{"t":"표를 여러 번 다시 세었기 때문에","mis":"SO6-1-u2-X08"}],"explanation":["대표가 힘썼어요.","주민의 의견을 들었어요.","지역이 달라졌어요."],"asset":{"type":"passage","lines":["㉠ 어두웠던 골목에 가로등이 새로 생겼다.","㉡ 어린이 도서관이 문을 열었다.","㉢ 통학길 건널목에 안전 시설이 늘었다.","이 일은 지역의 대표가 주민의 의견을 듣고 힘쓴 결과이다."],"title":"어느 동네의 달라진 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#9','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C3',2,'ox','auto','나 한 사람의 표로는 선거 결과가 절대 달라지지 않아요.',ARRAY['SO6-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"ox","stem":"나 한 사람의 표로는 선거 결과가 절대 달라지지 않아요.","answer":"X","reason_options":[{"t":"한 표 차이로 결과가 달라질 수 있고 참여가 모이면 대표와 정치가 바뀔 수 있기 때문에","correct":true},{"t":"선거 결과는 처음부터 정해져 있기 때문에","mis":"SO6-1-u2-X06"}],"mis":"SO6-1-u2-X06","explanation":["한 표 차이로도 갈려요.","참여가 모이면 바뀌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_basic#10','soc',6,1,'u2','L02','g6_1_soc_u2_L02_basic','lesson_basic','SO6-1-u2-C2',3,'error','auto','선거를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X04','SO6-1-u2-X07']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C2","difficulty":3,"kind":"error","stem":"선거를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「누가 대표가 되든 우리 생활은 아무것도 달라지지 않아.」","correct":true,"mis_target":"SO6-1-u2-X04"},{"t":"친구 나 — 「대표를 잘못 뽑으면 국민의 삶이 어려워질 수 있어.」","mis":"SO6-1-u2-X04"},{"t":"친구 다 — 「주권은 국민에게 있어.」","mis":"SO6-1-u2-X07"}],"explanation":["대표가 중요한 일을 정해요.","누가 뽑히느냐가 중요해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#1','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',2,'sa','auto','개표 결과에 잘못이나 실수가 있는지 확인하려고 개표한 것을 직접 다시 검사하는 일을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"sa","stem":"개표 결과에 잘못이나 실수가 있는지 확인하려고 개표한 것을 직접 다시 검사하는 일을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["재검표"],"explanation":["다시 검사해요.","재◯◯예요.","재검표예요."],"mis":"SO6-1-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#2','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C2',2,'ox','auto','선거에서는 도덕적으로 올바르고 공정한 사람을 대표로 뽑는 것이 좋아요.',ARRAY['SO6-1-u2-X05']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C2","difficulty":2,"kind":"ox","stem":"선거에서는 도덕적으로 올바르고 공정한 사람을 대표로 뽑는 것이 좋아요.","answer":"O","reason_options":[{"t":"대표는 국민을 위해 나라의 중요한 일을 결정하기 때문에","correct":true},{"t":"대표는 말솜씨만 좋으면 되기 때문에","mis":"SO6-1-u2-X05"}],"mis":"SO6-1-u2-X05","explanation":["대표가 중요한 일을 정해요.","올바르고 공정해야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#3','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',3,'mc','auto','자료에서 표를 다시 세어도 결과가 그대로였던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X08','SO6-1-u2-X06']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C3","difficulty":3,"kind":"mc","stem":"자료에서 표를 다시 세어도 결과가 그대로였던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"재검표는 이미 낸 표를 확인하는 일이지 새 표를 더하는 일이 아니기 때문에","correct":true},{"t":"다시 셀 때마다 표가 줄어들기 때문에","mis":"SO6-1-u2-X08"},{"t":"다시 세면 결과가 반드시 바뀌어야 하기 때문에","mis":"SO6-1-u2-X08"},{"t":"투표하지 않은 사람의 표까지 함께 세기 때문에","mis":"SO6-1-u2-X06"}],"explanation":["다시 세는 것은 확인이에요.","새 표가 생기지 않아요.","그래서 그대로였어요."],"asset":{"type":"passage","lines":["① 투표를 마치고 세어 보니 ㉮ 쪽과 ㉯ 쪽의 표가 똑같았다.","② 혹시 실수가 있었는지 표를 다시 세어 보았지만 결과는 그대로였다.","③ 늦게 도착한, 아직 투표하지 않았던 한 사람이 표를 냈다.","④ 그 한 표로 결과가 한쪽으로 갈렸다."],"title":"어느 모둠의 투표 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#4','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',3,'mc','auto','국민이 선거에 참여하는 것이 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X06','SO6-1-u2-X07']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C3","difficulty":3,"kind":"mc","stem":"국민이 선거에 참여하는 것이 중요한 까닭으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"참여하는 사람이 많아도 정치는 달라지지 않기 때문에","correct":true},{"t":"한 표 차이로 결과가 달라질 수 있기 때문에","mis":"SO6-1-u2-X06"},{"t":"국민의 참여로 대표가 바뀔 수 있기 때문에","mis":"SO6-1-u2-X06"},{"t":"국민 주권을 실현하는 기본 방법이기 때문에","mis":"SO6-1-u2-X07"}],"explanation":["참여하면 무엇이 달라질까요?","결과와 정치가 달라져요.","알맞지 않은 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#5','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C2',3,'mc','auto','대표를 잘못 뽑았을 때 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X04','SO6-1-u2-X05']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C2","difficulty":3,"kind":"mc","stem":"대표를 잘못 뽑았을 때 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라 경제나 국민의 삶이 어려워지고 민주주의가 위기를 맞을 수 있다","correct":true},{"t":"아무 일도 생기지 않는다","mis":"SO6-1-u2-X04"},{"t":"다음 날 저절로 새 대표가 뽑힌다","mis":"SO6-1-u2-X04"},{"t":"대표의 인기가 저절로 높아진다","mis":"SO6-1-u2-X05"}],"explanation":["대표가 중요한 일을 정해요.","잘못 정하면 어려워져요.","민주주의도 위기를 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#6','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',3,'error','auto','선거와 주권을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X07','SO6-1-u2-X03']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C3","difficulty":3,"kind":"error","stem":"선거와 주권을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「대표를 뽑고 나면 주권은 대표에게 넘어가.」","correct":true,"mis_target":"SO6-1-u2-X07"},{"t":"친구 가 — 「주권은 언제나 국민에게 있어.」","mis":"SO6-1-u2-X07"},{"t":"친구 다 — 「선거는 주권을 실현하는 방법이야.」","mis":"SO6-1-u2-X03"}],"explanation":["주권은 누구에게 있나요?","언제나 국민에게 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#7','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C2',3,'mc','auto','대표를 뽑을 때 먼저 살펴볼 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X05']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C2","difficulty":3,"kind":"mc","stem":"대표를 뽑을 때 먼저 살펴볼 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 더 살기 좋은 환경에서 생활하도록 노력할 사람인지","correct":true},{"t":"얼굴이 널리 알려진 사람인지","mis":"SO6-1-u2-X05"},{"t":"옷을 멋지게 입는 사람인지","mis":"SO6-1-u2-X05"},{"t":"우리 집과 가까운 곳에 사는지","mis":"SO6-1-u2-X05"}],"explanation":["대표는 국민을 위해 일해요.","살기 좋은 환경을 만들어요.","노력할 사람인지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#8','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',4,'mc','auto','자료를 보고 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X08','SO6-1-u2-X06']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C3","difficulty":4,"kind":"mc","stem":"자료를 보고 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결과를 바꾸는 것은 다시 세는 일이 아니라 참여하는 한 사람 한 사람의 표이다","correct":true},{"t":"표를 여러 번 다시 셀수록 결과가 바뀐다","mis":"SO6-1-u2-X08"},{"t":"투표하지 않아도 결과에는 영향이 없다","mis":"SO6-1-u2-X06"},{"t":"표가 같게 나오면 대표를 뽑을 수 없다","mis":"SO6-1-u2-X06"}],"explanation":["다시 세어도 그대로였어요.","한 표가 결과를 갈랐어요.","참여가 결과를 정해요."],"asset":{"type":"passage","lines":["① 투표를 마치고 세어 보니 ㉮ 쪽과 ㉯ 쪽의 표가 똑같았다.","② 혹시 실수가 있었는지 표를 다시 세어 보았지만 결과는 그대로였다.","③ 늦게 도착한, 아직 투표하지 않았던 한 사람이 표를 냈다.","④ 그 한 표로 결과가 한쪽으로 갈렸다."],"title":"어느 모둠의 투표 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#9','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C2',4,'mc','auto','자료와 선거를 함께 생각할 때 가장 알맞은 결론은 어느 것인가요?',ARRAY['SO6-1-u2-X04','SO6-1-u2-X05']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C2","difficulty":4,"kind":"mc","stem":"자료와 선거를 함께 생각할 때 가장 알맞은 결론은 어느 것인가요?","options":[{"t":"지역의 대표를 잘 뽑으면 지역이 변화해 더 살기 좋은 환경에서 생활할 수 있다","correct":true},{"t":"지역의 변화는 대표와 관계없다","mis":"SO6-1-u2-X04"},{"t":"대표는 나라 전체의 일만 하고 지역 일은 하지 않는다","mis":"SO6-1-u2-X04"},{"t":"지역 대표는 인기가 많을수록 일을 잘한다","mis":"SO6-1-u2-X05"}],"explanation":["대표가 힘썼어요.","동네가 달라졌어요.","잘 뽑는 것이 중요해요."],"asset":{"type":"passage","lines":["㉠ 어두웠던 골목에 가로등이 새로 생겼다.","㉡ 어린이 도서관이 문을 열었다.","㉢ 통학길 건널목에 안전 시설이 늘었다.","이 일은 지역의 대표가 주민의 의견을 듣고 힘쓴 결과이다."],"title":"어느 동네의 달라진 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L02_challenge#10','soc',6,1,'u2','L02','g6_1_soc_u2_L02_challenge','lesson_challenge','SO6-1-u2-C3',4,'essay','teacher','국민이 선거에 참여하는 것이 중요한 까닭을 「국민 주권」과 「한 표」라는 말을 넣어 쓰고, 지역의 대표를 잘 뽑았을 때 생길 변화를 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C3","difficulty":4,"kind":"essay","stem":"국민이 선거에 참여하는 것이 중요한 까닭을 「국민 주권」과 「한 표」라는 말을 넣어 쓰고, 지역의 대표를 잘 뽑았을 때 생길 변화를 한 가지 쓰세요.","answer_guide":{"answer":"예: 선거는 국민 주권을 실현하는 가장 기본적이고 중요한 방법이고, 한 표 차이로도 결과가 달라질 수 있어 국민의 참여로 대표와 정치가 바뀔 수 있다. 지역의 대표를 잘 뽑으면 통학길 안전 시설이 늘어나는 것처럼 사람들이 더 살기 좋은 환경에서 생활할 수 있다.","scoring_points":["국민 주권을 넣어 썼는가","한 표의 힘을 썼는가","대표를 잘 뽑았을 때의 변화를 썼는가"]},"explanation":["주권은 국민에게 있어요.","한 표 차이로 갈려요.","지역이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#1','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',1,'mc','auto','선거 과정에서 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO6-1-u2-X09']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C4","difficulty":1,"kind":"mc","stem":"선거 과정에서 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"선거인 명부 작성","correct":true},{"t":"개표","mis":"SO6-1-u2-X09"},{"t":"투표","mis":"SO6-1-u2-X09"},{"t":"당선증 발급","mis":"SO6-1-u2-X09"}],"explanation":["투표할 사람이 정해져야 해요.","명단을 먼저 만들어요.","선거인 명부 작성이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#2','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',1,'sa','auto','후보자의 기호, 이름, 사진, 공약 등을 실어 유권자에게 나눠 주는 문서를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C4","difficulty":1,"kind":"sa","stem":"후보자의 기호, 이름, 사진, 공약 등을 실어 유권자에게 나눠 주는 문서를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["선거공보","선거 공보"],"explanation":["유권자에게 나눠 줘요.","선거 ◯◯예요.","선거 공보예요."],"mis":"SO6-1-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#3','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C5',1,'ox','auto','평등 선거는 모든 사람이 한 표씩 투표하는 원칙이에요.',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C5","difficulty":1,"kind":"ox","stem":"평등 선거는 모든 사람이 한 표씩 투표하는 원칙이에요.","answer":"O","reason_options":[{"t":"누구의 표든 같은 무게를 지니게 하기 때문에","correct":true},{"t":"공부를 많이 한 사람은 표를 더 받기 때문에","mis":"SO6-1-u2-X12"}],"mis":"SO6-1-u2-X12","explanation":["한 표씩이에요.","모두 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#4','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C5',1,'mc','auto','어느 후보자에게 투표했는지 알 수 없도록 비밀을 보장하는 선거 원칙은 무엇인가요?',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C5","difficulty":1,"kind":"mc","stem":"어느 후보자에게 투표했는지 알 수 없도록 비밀을 보장하는 선거 원칙은 무엇인가요?","options":[{"t":"비밀 선거","correct":true},{"t":"보통 선거","mis":"SO6-1-u2-X12"},{"t":"평등 선거","mis":"SO6-1-u2-X12"},{"t":"직접 선거","mis":"SO6-1-u2-X12"}],"explanation":["알 수 없게 해요.","비밀을 지켜요.","비밀 선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#5','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',2,'mc','auto','뒤섞인 선거 과정 카드를 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X09']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C4","difficulty":2,"kind":"mc","stem":"뒤섞인 선거 과정 카드를 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉢ → ㉡ → ㉥ → ㉤ → ㉠ → ㉣","correct":true},{"t":"㉡ → ㉢ → ㉥ → ㉤ → ㉠ → ㉣","mis":"SO6-1-u2-X09"},{"t":"㉢ → ㉡ → ㉥ → ㉠ → ㉤ → ㉣","mis":"SO6-1-u2-X09"},{"t":"㉢ → ㉥ → ㉡ → ㉤ → ㉠ → ㉣","mis":"SO6-1-u2-X09"}],"explanation":["명부가 먼저예요.","등록해야 운동할 수 있어요.","투표 뒤에 개표해요."],"asset":{"type":"passage","lines":["㉠ 개표","㉡ 후보자 등록","㉢ 선거인 명부 작성","㉣ 당선자 결정 및 당선증 발급","㉤ 투표","㉥ 선거 운동"],"title":"뒤섞인 선거 과정 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#6','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C5',2,'match','auto','선거 원칙과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"match","stem":"선거 원칙과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"보통 선거","r":"18세 이상이면 누구나 투표해요"},{"l":"평등 선거","r":"모든 사람이 한 표씩 투표해요"},{"l":"직접 선거","r":"투표권을 가진 사람이 직접 투표해요"},{"l":"비밀 선거","r":"누구에게 투표했는지 알 수 없게 해요"}],"mis":"SO6-1-u2-X12","explanation":["누구나 · 한 표씩이에요.","직접 · 비밀이에요.","이름에 뜻이 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#7','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',2,'mc','auto','선거 관리 위원회가 투표함을 열어 투표 결과를 확인하는 걸음은 무엇인가요?',ARRAY['SO6-1-u2-X10']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C4","difficulty":2,"kind":"mc","stem":"선거 관리 위원회가 투표함을 열어 투표 결과를 확인하는 걸음은 무엇인가요?","options":[{"t":"개표","correct":true},{"t":"후보자 등록","mis":"SO6-1-u2-X10"},{"t":"선거 운동","mis":"SO6-1-u2-X10"},{"t":"선거인 명부 작성","mis":"SO6-1-u2-X10"}],"explanation":["투표함을 열어요.","결과를 확인해요.","개표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#8','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',2,'blank','auto','투표는 신분 확인하기 → 투표용지 받기 → (    ) → 투표함에 투표용지 넣기의 과정을 거쳐요. 빈칸에 알맞은 것은 무엇인가요?',ARRAY['SO6-1-u2-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C4","difficulty":2,"kind":"blank","stem":"투표는 신분 확인하기 → 투표용지 받기 → (    ) → 투표함에 투표용지 넣기의 과정을 거쳐요. 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"투표하기","correct":true},{"t":"개표하기","mis":"SO6-1-u2-X09"},{"t":"후보자 등록하기","mis":"SO6-1-u2-X09"},{"t":"당선증 받기","mis":"SO6-1-u2-X09"}],"explanation":["투표용지를 받았어요.","이제 표시해요.","투표하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#9','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C5',2,'mc','auto','안내문처럼 투표소에 가기 어려운 유권자도 투표할 수 있게 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X14','SO6-1-u2-X12','SO6-1-u2-X13']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"mc","stem":"안내문처럼 투표소에 가기 어려운 유권자도 투표할 수 있게 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모든 사람이 평등하게 선거에 참여하도록 선거권을 보장하려고","correct":true},{"t":"투표하는 사람 수를 줄이려고","mis":"SO6-1-u2-X14"},{"t":"배에 탄 사람에게만 표를 더 주려고","mis":"SO6-1-u2-X12"},{"t":"선거 원칙을 상황에 따라 바꾸려고","mis":"SO6-1-u2-X13"}],"explanation":["투표소에 못 와도 돼요.","누구나 참여할 수 있어요.","선거권을 보장해요."],"asset":{"type":"passage","lines":["몸이 불편해 투표소까지 가기 어려운 유권자는 미리 신고하면","자신이 머무는 곳에서 투표할 수 있다.","먼바다를 항해하는 배에 탄 선원은 배에서 투표할 수 있다."],"title":"「누구나 투표할 수 있어요」 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_basic#10','soc',6,1,'u2','L03','g6_1_soc_u2_L03_basic','lesson_basic','SO6-1-u2-C4',3,'error','auto','선거 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C4","difficulty":3,"kind":"error","stem":"선거 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「개표는 후보자들이 직접 투표함을 열어서 해.」","correct":true,"mis_target":"SO6-1-u2-X10"},{"t":"친구 가 — 「선거인 명부는 선거 관리 위원회가 만들어.」","mis":"SO6-1-u2-X10"},{"t":"친구 다 — 「후보자는 토론회나 거리 유세로 선거 운동을 해.」","mis":"SO6-1-u2-X10"}],"explanation":["개표는 누가 할까요?","선거 관리 위원회예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#1','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',2,'sa','auto','선거일에 투표소에서 투표할 수 없는 선원이 배에서 하는 투표를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"sa","stem":"선거일에 투표소에서 투표할 수 없는 선원이 배에서 하는 투표를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["선상투표","선상 투표"],"explanation":["배 위에서 해요.","선◯ 투표예요.","선상 투표예요."],"mis":"SO6-1-u2-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#2','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',2,'ox','auto','우리나라에서는 공정한 선거를 위해 선거 원칙을 상황에 따라 바꿔요.',ARRAY['SO6-1-u2-X13']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"ox","stem":"우리나라에서는 공정한 선거를 위해 선거 원칙을 상황에 따라 바꿔요.","answer":"X","reason_options":[{"t":"공정하고 민주적인 선거를 위해 국민 누구나 늘 선거 원칙을 지켜야 하기 때문에","correct":true},{"t":"선거 원칙은 선거마다 새로 정하기 때문에","mis":"SO6-1-u2-X13"}],"mis":"SO6-1-u2-X13","explanation":["원칙은 늘 지켜요.","바꾸지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#3','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',3,'mc','auto','자료의 ㉮ 심부름 나라는 우리나라의 어느 선거 원칙과 다른가요?',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C5","difficulty":3,"kind":"mc","stem":"자료의 ㉮ 심부름 나라는 우리나라의 어느 선거 원칙과 다른가요?","options":[{"t":"직접 선거","correct":true},{"t":"보통 선거","mis":"SO6-1-u2-X12"},{"t":"평등 선거","mis":"SO6-1-u2-X12"},{"t":"비밀 선거","mis":"SO6-1-u2-X12"}],"explanation":["대신 투표해요.","본인이 해야 해요.","직접 선거와 달라요."],"asset":{"type":"passage","lines":["㉮ 심부름 나라 — 다른 사람이 대신 투표해 줄 수 있다.","㉯ 어린이 나라 — 초등학교에 다니는 어린이만 투표할 수 있다.","㉰ 왁자지껄 나라 — 투표소에서 지지하는 후보자 이름을 크게 말한다.","㉱ 박사 나라 — 박사 학위가 있는 사람은 여러 표를 낼 수 있다.","(모두 교과서가 지어낸 이야기 나라예요.)"],"title":"이야기 나라 네 곳의 선거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#4','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',3,'mc','auto','자료의 나라와 그 나라가 지키지 않은 우리나라 선거 원칙을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C5","difficulty":3,"kind":"mc","stem":"자료의 나라와 그 나라가 지키지 않은 우리나라 선거 원칙을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉯ — 보통 선거 · ㉰ — 비밀 선거 · ㉱ — 평등 선거","correct":true},{"t":"㉯ — 평등 선거 · ㉰ — 직접 선거 · ㉱ — 보통 선거","mis":"SO6-1-u2-X12"},{"t":"㉯ — 비밀 선거 · ㉰ — 보통 선거 · ㉱ — 직접 선거","mis":"SO6-1-u2-X12"},{"t":"㉯ — 직접 선거 · ㉰ — 평등 선거 · ㉱ — 비밀 선거","mis":"SO6-1-u2-X12"}],"explanation":["㉯는 어린이만이에요.","㉰는 이름을 말해요.","㉱는 여러 표예요."],"asset":{"type":"passage","lines":["㉮ 심부름 나라 — 다른 사람이 대신 투표해 줄 수 있다.","㉯ 어린이 나라 — 초등학교에 다니는 어린이만 투표할 수 있다.","㉰ 왁자지껄 나라 — 투표소에서 지지하는 후보자 이름을 크게 말한다.","㉱ 박사 나라 — 박사 학위가 있는 사람은 여러 표를 낼 수 있다.","(모두 교과서가 지어낸 이야기 나라예요.)"],"title":"이야기 나라 네 곳의 선거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#5','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C4',3,'mc','auto','선거가 법에 정해진 절차에 따라 이루어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X11']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C4","difficulty":3,"kind":"mc","stem":"선거가 법에 정해진 절차에 따라 이루어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"선거를 공정하게 치르기 위해서","correct":true},{"t":"선거를 하루 만에 끝내기 위해서","mis":"SO6-1-u2-X11"},{"t":"후보자가 절차를 마음대로 정하게 하려고","mis":"SO6-1-u2-X11"},{"t":"절차를 그때그때 바꾸기 위해서","mis":"SO6-1-u2-X11"}],"explanation":["정해진 절차가 있어요.","누구에게나 같아요.","공정하게 치르려고요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#6','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C4',3,'mc','auto','선거 과정에서 개표가 투표보다 먼저 올 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X09','SO6-1-u2-X10']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C4","difficulty":3,"kind":"mc","stem":"선거 과정에서 개표가 투표보다 먼저 올 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"투표가 끝나야 셀 표가 생기기 때문에","correct":true},{"t":"개표는 아무 때나 해도 되기 때문에","mis":"SO6-1-u2-X09"},{"t":"개표는 후보자 등록 전에 하기 때문에","mis":"SO6-1-u2-X09"},{"t":"투표와 개표는 같은 일이기 때문에","mis":"SO6-1-u2-X10"}],"explanation":["개표는 표를 세는 일이에요.","셀 표가 있어야 해요.","투표가 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#7','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',3,'error','auto','선거 원칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C5","difficulty":3,"kind":"error","stem":"선거 원칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「가족끼리는 서로 대신 투표해 줘도 괜찮아.」","correct":true,"mis_target":"SO6-1-u2-X12"},{"t":"친구 가 — 「누구에게 투표했는지는 말하지 않아도 돼.」","mis":"SO6-1-u2-X12"},{"t":"친구 나 — 「18세 이상이면 누구나 투표할 수 있어.」","mis":"SO6-1-u2-X12"}],"explanation":["대신 투표해도 될까요?","투표권을 가진 사람이 직접 해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#8','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',4,'mc','auto','선거 원칙을 정해 놓은 까닭을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X13','SO6-1-u2-X12','SO6-1-u2-X11']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C5","difficulty":4,"kind":"mc","stem":"선거 원칙을 정해 놓은 까닭을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"공정하고 민주적인 선거가 이루어지고 모든 사람에게 동등한 권리를 주기 위해서","correct":true},{"t":"투표하는 사람을 줄이기 위해서","mis":"SO6-1-u2-X13"},{"t":"공부를 많이 한 사람의 뜻을 더 크게 반영하려고","mis":"SO6-1-u2-X12"},{"t":"선거 결과를 미리 정해 두려고","mis":"SO6-1-u2-X11"}],"explanation":["공정해야 해요.","모두에게 같은 권리예요.","그래서 원칙을 정했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#9','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C4',4,'mc','auto','선거 과정 카드 가운데 후보자가 하는 걸음끼리 바르게 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X10']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C4","difficulty":4,"kind":"mc","stem":"선거 과정 카드 가운데 후보자가 하는 걸음끼리 바르게 묶은 것은 어느 것인가요?","options":[{"t":"㉡, ㉥","correct":true},{"t":"㉢, ㉠","mis":"SO6-1-u2-X10"},{"t":"㉠, ㉣","mis":"SO6-1-u2-X10"},{"t":"㉤, ㉢","mis":"SO6-1-u2-X10"}],"explanation":["후보자가 이름을 올려요.","후보자가 알려요.","등록과 운동이에요."],"asset":{"type":"passage","lines":["㉠ 개표","㉡ 후보자 등록","㉢ 선거인 명부 작성","㉣ 당선자 결정 및 당선증 발급","㉤ 투표","㉥ 선거 운동"],"title":"뒤섞인 선거 과정 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L03_challenge#10','soc',6,1,'u2','L03','g6_1_soc_u2_L03_challenge','lesson_challenge','SO6-1-u2-C5',4,'essay','teacher','자료의 이야기 나라 가운데 두 곳을 골라 우리나라의 어느 선거 원칙과 다른지 쓰고, 우리나라가 그 원칙을 지키는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C5","difficulty":4,"kind":"essay","stem":"자료의 이야기 나라 가운데 두 곳을 골라 우리나라의 어느 선거 원칙과 다른지 쓰고, 우리나라가 그 원칙을 지키는 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉮ 심부름 나라는 다른 사람이 대신 투표해 주므로 투표권을 가진 사람이 직접 투표하는 직접 선거와 다르다. ㉱ 박사 나라는 박사 학위가 있는 사람이 여러 표를 내므로 모든 사람이 한 표씩 투표하는 평등 선거와 다르다. 우리나라는 공정하고 민주적인 선거를 하고 모든 사람에게 동등한 권리를 주려고 이 원칙을 지킨다.","scoring_points":["두 나라를 골랐는가","다른 원칙을 바르게 짝지었는가","원칙을 지키는 까닭을 썼는가"]},"explanation":["두 곳을 골라요.","어느 원칙과 다른지 써요.","지키는 까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 심부름 나라 — 다른 사람이 대신 투표해 줄 수 있다.","㉯ 어린이 나라 — 초등학교에 다니는 어린이만 투표할 수 있다.","㉰ 왁자지껄 나라 — 투표소에서 지지하는 후보자 이름을 크게 말한다.","㉱ 박사 나라 — 박사 학위가 있는 사람은 여러 표를 낼 수 있다.","(모두 교과서가 지어낸 이야기 나라예요.)"],"title":"이야기 나라 네 곳의 선거"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#1','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',1,'mc','auto','선거 벽보를 만들어 여러 사람이 보는 곳에 붙이는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X05','SO6-1-u2-X15','SO6-1-u2-X16']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"mc","stem":"선거 벽보를 만들어 여러 사람이 보는 곳에 붙이는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"후보자의 공약을 알려 유권자가 투표할 때 참고하게 하려고","correct":true},{"t":"후보자의 얼굴을 예쁘게 꾸미려고","mis":"SO6-1-u2-X05"},{"t":"상대 후보자의 잘못을 알리려고","mis":"SO6-1-u2-X15"},{"t":"투표하는 사람을 줄이려고","mis":"SO6-1-u2-X16"}],"explanation":["벽보에 공약이 있어요.","유권자가 봐요.","투표할 때 참고해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#2','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',1,'sa','auto','후보자가 당선되면 하겠다고 유권자에게 내놓는 약속을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"sa","stem":"후보자가 당선되면 하겠다고 유권자에게 내놓는 약속을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["공약"],"explanation":["약속이에요.","◯약이에요.","공약이에요."],"mis":"SO6-1-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#3','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',1,'ox','auto','투표할 때 마음에 드는 후보자가 여럿이면 여러 후보자에게 표시해도 돼요.',ARRAY['SO6-1-u2-X16']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"ox","stem":"투표할 때 마음에 드는 후보자가 여럿이면 여러 후보자에게 표시해도 돼요.","answer":"X","reason_options":[{"t":"여러 후보자에게 표시하면 그 표는 무효가 되므로 한 후보자에게만 투표하기 때문에","correct":true},{"t":"여러 후보자를 뽑을수록 공정하기 때문에","mis":"SO6-1-u2-X16"}],"mis":"SO6-1-u2-X16","explanation":["한 후보자에게만이에요.","여럿이면 무효예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#4','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',1,'mc','auto','공약을 평가하는 잣대로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"mc","stem":"공약을 평가하는 잣대로 알맞은 것은 어느 것인가요?","options":[{"t":"실천할 수 있는 공약인가","correct":true},{"t":"후보자의 목소리가 큰가","mis":"SO6-1-u2-X15"},{"t":"상대 후보자를 세게 깎아내리는가","mis":"SO6-1-u2-X15"},{"t":"우리 모둠이 낸 공약인가","mis":"SO6-1-u2-X15"}],"explanation":["공약이 어떤지 재요.","지킬 수 있어야 해요.","실천할 수 있는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#5','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',2,'mc','auto','공약 카드 가운데 「공약이 구체적인가」라는 잣대에 걸리는 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"공약 카드 가운데 「공약이 구체적인가」라는 잣대에 걸리는 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SO6-1-u2-X15"},{"t":"㉡","mis":"SO6-1-u2-X15"},{"t":"㉢","mis":"SO6-1-u2-X15"}],"explanation":["무엇을 어떻게 할지가 있나요?","힘쓰겠다고만 했어요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 근무 시간을 자유롭게 하고 육아 휴직을 넓혀 저출산 문제를 풀겠습니다.","㉡ 태양 에너지를 쓰고 일회용품 관련 법을 고쳐 기후 위기에 대처하겠습니다.","㉢ 사이버 범죄를 막고 예방을 강화해 안전한 나라를 만들겠습니다.","㉣ 환경 보호를 위해 힘쓰겠습니다.","㉤ 모든 국민에게 똑같이 큰돈을 나누어 주겠습니다.","㉥ 집값을 올려 드리겠습니다."],"title":"모의 선거 공약 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#6','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',2,'mc','auto','공약 카드 ㉤이 걸리는 잣대와 그 까닭을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"공약 카드 ㉤이 걸리는 잣대와 그 까닭을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"실천할 수 있는가 — 나라에서 걷을 수 있는 세금은 한정되어 있어서","correct":true},{"t":"구체적인가 — 글자 수가 너무 많아서","mis":"SO6-1-u2-X15"},{"t":"국민의 요구를 반영하는가 — 모든 국민이 원해서","mis":"SO6-1-u2-X15"},{"t":"후보자의 말솜씨 — 말을 잘 못해서","mis":"SO6-1-u2-X15"}],"explanation":["큰돈을 똑같이 줘요.","나라의 돈은 한정돼요.","실천하기 어려워요."],"asset":{"type":"passage","lines":["㉠ 근무 시간을 자유롭게 하고 육아 휴직을 넓혀 저출산 문제를 풀겠습니다.","㉡ 태양 에너지를 쓰고 일회용품 관련 법을 고쳐 기후 위기에 대처하겠습니다.","㉢ 사이버 범죄를 막고 예방을 강화해 안전한 나라를 만들겠습니다.","㉣ 환경 보호를 위해 힘쓰겠습니다.","㉤ 모든 국민에게 똑같이 큰돈을 나누어 주겠습니다.","㉥ 집값을 올려 드리겠습니다."],"title":"모의 선거 공약 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#7','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',2,'blank','auto','선거 운동은 양보와 (    )의 자세로 공정하고 정정당당하게 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"blank","stem":"선거 운동은 양보와 (    )의 자세로 공정하고 정정당당하게 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"타협","correct":true},{"t":"고집","mis":"SO6-1-u2-X15"},{"t":"비방","mis":"SO6-1-u2-X15"},{"t":"명령","mis":"SO6-1-u2-X15"}],"explanation":["서로 한 걸음씩 물러나요.","의견을 맞춰 가요.","타협이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#8','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',2,'mc','auto','모의 선거의 차례에서 「공약 평가하기」 바로 다음에 하는 일은 무엇인가요?',ARRAY['SO6-1-u2-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"모의 선거의 차례에서 「공약 평가하기」 바로 다음에 하는 일은 무엇인가요?","options":[{"t":"투표하기","correct":true},{"t":"후보자 정하기","mis":"SO6-1-u2-X09"},{"t":"공약 정하기","mis":"SO6-1-u2-X09"},{"t":"당선자 발표","mis":"SO6-1-u2-X09"}],"explanation":["공약을 살폈어요.","이제 고를 차례예요.","투표하기예요."],"asset":{"type":"passage","lines":["후보자 정하기 → 공약 정하기 → 선거 운동하기 → 공약 평가하기","→ 투표하기 → 개표하기 → 당선자 발표 → 당선 소감"],"title":"우리 반 모의 선거의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#9','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',2,'match','auto','투표할 때 지킬 점과 그 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"match","stem":"투표할 때 지킬 점과 그 까닭을 알맞게 이으세요.","pairs":[{"l":"한 후보자에게만 표시해요","r":"그래야 내 표가 무효가 되지 않아요"},{"l":"누구를 뽑았는지 말하지 않아요","r":"투표의 비밀이 지켜져요"},{"l":"공약을 꼼꼼히 살펴요","r":"알맞은 대표를 고를 수 있어요"},{"l":"스스로 정해요","r":"내 뜻이 담긴 한 표가 돼요"}],"mis":"SO6-1-u2-X16","explanation":["무효가 되지 않게 해요.","비밀을 지켜요.","스스로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_basic#10','soc',6,1,'u2','L04','g6_1_soc_u2_L04_basic','lesson_basic','SO6-1-u2-C6',3,'error','auto','모의 선거를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X16','SO6-1-u2-X15']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"error","stem":"모의 선거를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「누구를 뽑을지 모둠이 함께 정해서 똑같이 투표하자.」","correct":true,"mis_target":"SO6-1-u2-X16"},{"t":"친구 나 — 「공약을 실천할 수 있는지 먼저 살펴보자.」","mis":"SO6-1-u2-X15"},{"t":"친구 다 — 「누구에게 투표했는지는 말하지 말자.」","mis":"SO6-1-u2-X16"}],"explanation":["투표는 누가 정하나요?","스스로 정해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#1','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',2,'sa','auto','모의 선거에서 후보자가 벽보를 붙이고 연설하며 토론회를 여는 걸음을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"sa","stem":"모의 선거에서 후보자가 벽보를 붙이고 연설하며 토론회를 여는 걸음을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["선거운동","선거 운동"],"explanation":["공약을 알리는 걸음이에요.","선거 ◯◯이에요.","선거 운동이에요."],"mis":"SO6-1-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#2','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',2,'ox','auto','공약 카드 ㉥은 모든 국민이 원하는 일이라 국민의 요구를 반영한 공약이에요.',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"ox","stem":"공약 카드 ㉥은 모든 국민이 원하는 일이라 국민의 요구를 반영한 공약이에요.","answer":"X","reason_options":[{"t":"모든 국민이 집값이 오르기를 원하는 것은 아니기 때문에","correct":true},{"t":"후보자가 약속한 것은 모두 국민이 원하는 것이기 때문에","mis":"SO6-1-u2-X15"}],"mis":"SO6-1-u2-X15","explanation":["모두가 원할까요?","원하지 않는 사람도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 근무 시간을 자유롭게 하고 육아 휴직을 넓혀 저출산 문제를 풀겠습니다.","㉡ 태양 에너지를 쓰고 일회용품 관련 법을 고쳐 기후 위기에 대처하겠습니다.","㉢ 사이버 범죄를 막고 예방을 강화해 안전한 나라를 만들겠습니다.","㉣ 환경 보호를 위해 힘쓰겠습니다.","㉤ 모든 국민에게 똑같이 큰돈을 나누어 주겠습니다.","㉥ 집값을 올려 드리겠습니다."],"title":"모의 선거 공약 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#3','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',3,'mc','auto','세 잣대(구체적인가·실천할 수 있는가·국민의 요구를 반영하는가)를 모두 세웠을 때 걸러지지 않고 남는 공약끼리 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"mc","stem":"세 잣대(구체적인가·실천할 수 있는가·국민의 요구를 반영하는가)를 모두 세웠을 때 걸러지지 않고 남는 공약끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉠, ㉡, ㉢","correct":true},{"t":"㉣, ㉤, ㉥","mis":"SO6-1-u2-X15"},{"t":"㉠, ㉣, ㉤","mis":"SO6-1-u2-X15"},{"t":"㉡, ㉢, ㉥","mis":"SO6-1-u2-X15"}],"explanation":["㉣은 구체적이지 않아요.","㉤은 실천하기 어려워요.","㉥은 요구와 달라요."],"asset":{"type":"passage","lines":["㉠ 근무 시간을 자유롭게 하고 육아 휴직을 넓혀 저출산 문제를 풀겠습니다.","㉡ 태양 에너지를 쓰고 일회용품 관련 법을 고쳐 기후 위기에 대처하겠습니다.","㉢ 사이버 범죄를 막고 예방을 강화해 안전한 나라를 만들겠습니다.","㉣ 환경 보호를 위해 힘쓰겠습니다.","㉤ 모든 국민에게 똑같이 큰돈을 나누어 주겠습니다.","㉥ 집값을 올려 드리겠습니다."],"title":"모의 선거 공약 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#4','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',3,'mc','auto','「후보자가 목소리가 크고 말을 잘한다」가 공약을 재는 잣대가 될 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X05','SO6-1-u2-X15']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"mc","stem":"「후보자가 목소리가 크고 말을 잘한다」가 공약을 재는 잣대가 될 수 없는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잣대는 후보자가 어떤지가 아니라 공약이 어떤지를 재야 하기 때문에","correct":true},{"t":"목소리가 큰 후보자가 늘 공약을 잘 지키기 때문에","mis":"SO6-1-u2-X05"},{"t":"말을 잘하면 공약이 저절로 구체적이 되기 때문에","mis":"SO6-1-u2-X15"},{"t":"목소리는 눈으로 볼 수 없기 때문에","mis":"SO6-1-u2-X15"}],"explanation":["무엇을 재는 잣대인가요?","공약을 재요.","후보자의 말솜씨가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#5','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',3,'ox','auto','모의 선거에서 상대 후보자를 세게 깎아내리는 후보자일수록 좋은 공약을 낸 거예요.',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"ox","stem":"모의 선거에서 상대 후보자를 세게 깎아내리는 후보자일수록 좋은 공약을 낸 거예요.","answer":"X","reason_options":[{"t":"선거 운동에서는 상대를 비방하지 않고, 깎아내리는 것은 공약을 재는 잣대가 아니기 때문에","correct":true},{"t":"상대를 깎아내리면 공약이 구체적이 되기 때문에","mis":"SO6-1-u2-X15"}],"mis":"SO6-1-u2-X15","explanation":["비방하지 않아요.","공약을 봐야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#6','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',3,'error','auto','선거 공약 채점표를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"error","stem":"선거 공약 채점표를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우리 모둠이 낸 공약에는 점수를 더 주자.」","correct":true,"mis_target":"SO6-1-u2-X15"},{"t":"친구 가 — 「공약이 구체적인지 보자.」","mis":"SO6-1-u2-X15"},{"t":"친구 나 — 「국민의 요구를 반영했는지도 보자.」","mis":"SO6-1-u2-X15"}],"explanation":["같은 잣대로 재야 해요.","누가 냈는지는 잣대가 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#7','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',3,'mc','auto','모의 선거에서 「나의 한 표」를 정할 때의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X16','SO6-1-u2-X15']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"mc","stem":"모의 선거에서 「나의 한 표」를 정할 때의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잣대로 공약을 살핀 뒤 내가 스스로 한 후보자를 고른다","correct":true},{"t":"친구가 고른 후보자를 그대로 따라 고른다","mis":"SO6-1-u2-X16"},{"t":"잣대에 걸린 공약을 낸 후보자를 고른다","mis":"SO6-1-u2-X15"},{"t":"마음에 드는 후보자 모두에게 표시한다","mis":"SO6-1-u2-X16"}],"explanation":["공약을 살펴요.","스스로 정해요.","한 후보자에게만이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#8','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',4,'mc','auto','모의 선거의 차례를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X11','SO6-1-u2-X09']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C6","difficulty":4,"kind":"mc","stem":"모의 선거의 차례를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모의 선거도 정해진 차례에 따라 공정하게 치러야 한다","correct":true},{"t":"모의 선거는 아무 차례로나 해도 된다","mis":"SO6-1-u2-X11"},{"t":"모의 선거에서는 투표를 빼도 된다","mis":"SO6-1-u2-X11"},{"t":"공약 평가는 투표가 끝난 뒤에 한다","mis":"SO6-1-u2-X09"}],"explanation":["차례가 정해져 있어요.","공약을 보고 투표해요.","공정하게 치러요."],"asset":{"type":"passage","lines":["후보자 정하기 → 공약 정하기 → 선거 운동하기 → 공약 평가하기","→ 투표하기 → 개표하기 → 당선자 발표 → 당선 소감"],"title":"우리 반 모의 선거의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#9','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',4,'mc','auto','좋은 대표를 뽑기 위해 유권자가 할 일을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X05','SO6-1-u2-X16','SO6-1-u2-X15']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C6","difficulty":4,"kind":"mc","stem":"좋은 대표를 뽑기 위해 유권자가 할 일을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"공약이 구체적이고 실천할 수 있으며 국민의 요구를 반영하는지 따져 보고 스스로 투표한다","correct":true},{"t":"가장 유명한 후보자를 고른다","mis":"SO6-1-u2-X05"},{"t":"다른 사람에게 누구를 뽑을지 물어 똑같이 한다","mis":"SO6-1-u2-X16"},{"t":"공약은 보지 않고 벽보 그림만 본다","mis":"SO6-1-u2-X15"}],"explanation":["세 잣대예요.","따져 봐요.","스스로 투표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L04_challenge#10','soc',6,1,'u2','L04','g6_1_soc_u2_L04_challenge','lesson_challenge','SO6-1-u2-C6',4,'essay','teacher','공약 카드 가운데 걸러지는 공약 하나와 걸러지지 않는 공약 하나를 골라, 각각 어떤 잣대로 판단했는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C6","difficulty":4,"kind":"essay","stem":"공약 카드 가운데 걸러지는 공약 하나와 걸러지지 않는 공약 하나를 골라, 각각 어떤 잣대로 판단했는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ㉣ 「환경 보호를 위해 힘쓰겠습니다」는 무엇을 언제까지 어떻게 할지가 없어 「공약이 구체적인가」라는 잣대에 걸린다. ㉡은 태양 에너지를 쓰고 일회용품 관련 법을 고치겠다고 방법을 밝혔고 실천할 수 있으며 기후 위기에 대처하자는 국민의 요구를 반영해 걸러지지 않는다.","scoring_points":["걸러지는 공약과 잣대를 썼는가","걸러지지 않는 공약과 까닭을 썼는가","공약 자체를 재는 잣대를 썼는가"]},"explanation":["걸리는 것을 골라요.","어느 잣대인지 써요.","남는 공약의 까닭도 써요."],"asset":{"type":"passage","lines":["㉠ 근무 시간을 자유롭게 하고 육아 휴직을 넓혀 저출산 문제를 풀겠습니다.","㉡ 태양 에너지를 쓰고 일회용품 관련 법을 고쳐 기후 위기에 대처하겠습니다.","㉢ 사이버 범죄를 막고 예방을 강화해 안전한 나라를 만들겠습니다.","㉣ 환경 보호를 위해 힘쓰겠습니다.","㉤ 모든 국민에게 똑같이 큰돈을 나누어 주겠습니다.","㉥ 집값을 올려 드리겠습니다."],"title":"모의 선거 공약 카드 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#1','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',1,'mc','auto','나랏일을 맡아 하는 곳을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C7","difficulty":1,"kind":"mc","stem":"나랏일을 맡아 하는 곳을 무엇이라고 하나요?","options":[{"t":"국가기관","correct":true},{"t":"시민 단체","mis":"SO6-1-u2-X17"},{"t":"회사","mis":"SO6-1-u2-X17"},{"t":"동아리","mis":"SO6-1-u2-X17"}],"explanation":["나랏일을 맡아요.","나라의 기관이에요.","국가기관이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#2','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',1,'sa','auto','법을 만드는 국가기관은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C7","difficulty":1,"kind":"sa","stem":"법을 만드는 국가기관은 어디인가요? 두 글자로 쓰세요.","answer":["국회"],"explanation":["법을 만드는 곳이에요.","국◯예요.","국회예요."],"mis":"SO6-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#3','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',1,'ox','auto','국가기관은 일하는 사람의 수에 따라 나눠져 있어요.',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C7","difficulty":1,"kind":"ox","stem":"국가기관은 일하는 사람의 수에 따라 나눠져 있어요.","answer":"X","reason_options":[{"t":"국가기관은 하는 일에 따라 나눠져 있기 때문에","correct":true},{"t":"사람이 많은 곳일수록 중요한 기관이기 때문에","mis":"SO6-1-u2-X17"}],"mis":"SO6-1-u2-X17","explanation":["무엇에 따라 나뉠까요?","하는 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#4','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',1,'mc','auto','법에 따라 판결을 내리는 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C7","difficulty":1,"kind":"mc","stem":"법에 따라 판결을 내리는 국가기관은 어디인가요?","options":[{"t":"법원","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"행정부","mis":"SO6-1-u2-X18"},{"t":"학교","mis":"SO6-1-u2-X17"}],"explanation":["판결을 내려요.","재판을 해요.","법원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#5','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',2,'match','auto','자료의 장면과 그 일을 맡은 국가기관을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"match","stem":"자료의 장면과 그 일을 맡은 국가기관을 알맞게 이으세요.","pairs":[{"l":"급식과 관련한 법을 만들었다","r":"국회"},{"l":"사람들을 대피시키고 피해를 복구했다","r":"행정부"},{"l":"층간 소음 다툼을 재판으로 가렸다","r":"법원"}],"mis":"SO6-1-u2-X18","explanation":["법을 만들어요.","살림을 맡아요.","재판을 해요."],"asset":{"type":"passage","lines":["㉠ 학생들이 안전하고 영양이 풍부한 급식을 먹도록 급식과 관련한 법을 만들었다.","㉡ 홍수가 나자 사람들을 안전하게 대피시키고 피해를 복구했다.","㉢ 층간 소음으로 다툼이 생기자 재판을 하여 피해 보상을 하게 했다."],"title":"나랏일 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#6','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',2,'mc','auto','국가기관이 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"mc","stem":"국가기관이 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라의 다양한 문제를 해결하려고 중요한 일을 결정하고 나랏일을 맡아 한다","correct":true},{"t":"나랏일을 국민 저마다 알아서 하도록 둔다","mis":"SO6-1-u2-X17"},{"t":"국민 한 사람이 나랏일을 모두 맡게 한다","mis":"SO6-1-u2-X17"},{"t":"다른 나라의 일을 대신 결정해 준다","mis":"SO6-1-u2-X17"}],"explanation":["나랏일을 맡아요.","중요한 일을 정해요.","문제를 해결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#7','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',2,'blank','auto','국가기관은 국민의 자유와 (    )를 보장하기 위해 일해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"blank","stem":"국가기관은 국민의 자유와 (    )를 보장하기 위해 일해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"권리","correct":true},{"t":"인기","mis":"SO6-1-u2-X17"},{"t":"재산만","mis":"SO6-1-u2-X17"},{"t":"의무만","mis":"SO6-1-u2-X17"}],"explanation":["국민이 누려야 할 것이에요.","자유와 함께 써요.","권리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#8','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',2,'mc','auto','나랏일을 맡아 하는 기관이 없다면 생길 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"mc","stem":"나랏일을 맡아 하는 기관이 없다면 생길 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일상생활이 불편해지고 국민의 안전을 위협받는 일이 생길 수 있다","correct":true},{"t":"모든 일이 저절로 해결된다","mis":"SO6-1-u2-X17"},{"t":"법을 지키지 않는 사람이 사라진다","mis":"SO6-1-u2-X17"},{"t":"국민의 생활이 더 편리해진다","mis":"SO6-1-u2-X17"}],"explanation":["맡을 곳이 없어요.","일이 그대로 쌓여요.","불편하고 위험해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#9','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',2,'mc','auto','홍수가 났을 때 사람들을 대피시키고 피해를 복구하는 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"mc","stem":"홍수가 났을 때 사람들을 대피시키고 피해를 복구하는 국가기관은 어디인가요?","options":[{"t":"행정부","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"법원","mis":"SO6-1-u2-X18"},{"t":"국민","mis":"SO6-1-u2-X17"}],"explanation":["나라 살림을 맡아요.","법에 따라 일을 해요.","행정부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_basic#10','soc',6,1,'u2','L05','g6_1_soc_u2_L05_basic','lesson_basic','SO6-1-u2-C7',3,'error','auto','어린이 보호 구역 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"error","stem":"어린이 보호 구역 이야기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉡처럼 카메라를 설치하라고 지시한 곳은 법원이야.」","correct":true,"mis_target":"SO6-1-u2-X18"},{"t":"친구 가 — 「㉠처럼 법을 고친 곳은 국회야.」","mis":"SO6-1-u2-X18"},{"t":"친구 다 — 「㉢처럼 재판한 곳은 법원이야.」","mis":"SO6-1-u2-X18"}],"explanation":["카메라 설치 지시는 어디일까요?","나라 살림을 맡은 곳이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["어린이 보호 구역의 교통안전 문제가 커지자 국가기관들이 저마다 할 일을 했다.","㉠ 보호 구역 교통안전과 관련한 법을 고쳤다.","㉡ 보호 구역에 과속 단속 카메라를 설치하라고 지시했다.","㉢ 규칙을 어긴 운전자를 재판하여 책임을 물었다."],"title":"어린이 보호 구역 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#1','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',2,'sa','auto','국회에서 만든 법에 따라 나라의 살림을 맡아 하는 국가기관은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"sa","stem":"국회에서 만든 법에 따라 나라의 살림을 맡아 하는 국가기관은 어디인가요? 세 글자로 쓰세요.","answer":["행정부"],"explanation":["나라 살림을 맡아요.","행◯◯예요.","행정부예요."],"mis":"SO6-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#2','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',2,'ox','auto','나랏일을 맡을 곳이 없으면 해결해야 할 일이 사라지지 않고 그대로 쌓여요.',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C7","difficulty":2,"kind":"ox","stem":"나랏일을 맡을 곳이 없으면 해결해야 할 일이 사라지지 않고 그대로 쌓여요.","answer":"O","reason_options":[{"t":"일을 맡아 처리할 곳이 있어야 일이 처리되기 때문에","correct":true},{"t":"맡을 곳이 없으면 일도 저절로 없어지기 때문에","mis":"SO6-1-u2-X17"}],"mis":"SO6-1-u2-X17","explanation":["일은 사라지지 않아요.","맡을 곳이 있어야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#3','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',3,'mc','auto','자료의 ㉠~㉢을 한 국가기관이 모두 맡지 않고 나눠 한 것에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17','SO6-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"mc","stem":"자료의 ㉠~㉢을 한 국가기관이 모두 맡지 않고 나눠 한 것에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국가기관은 하는 일에 따라 나눠져 있다","correct":true},{"t":"국가기관은 건물 크기에 따라 나뉜다","mis":"SO6-1-u2-X17"},{"t":"한 기관이 모든 일을 맡는 것이 원칙이다","mis":"SO6-1-u2-X17"},{"t":"세 기관이 하는 일은 모두 같다","mis":"SO6-1-u2-X18"}],"explanation":["법·지시·재판이에요.","하는 일이 달라요.","하는 일에 따라 나뉘어요."],"asset":{"type":"passage","lines":["어린이 보호 구역의 교통안전 문제가 커지자 국가기관들이 저마다 할 일을 했다.","㉠ 보호 구역 교통안전과 관련한 법을 고쳤다.","㉡ 보호 구역에 과속 단속 카메라를 설치하라고 지시했다.","㉢ 규칙을 어긴 운전자를 재판하여 책임을 물었다."],"title":"어린이 보호 구역 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#4','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',3,'mc','auto','자료의 ㉡을 한 국가기관이 맡는 다른 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"mc","stem":"자료의 ㉡을 한 국가기관이 맡는 다른 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"홍수 피해를 입은 곳을 복구하는 일","correct":true},{"t":"층간 소음 다툼의 옳고 그름을 가리는 일","mis":"SO6-1-u2-X18"},{"t":"급식과 관련한 법을 만드는 일","mis":"SO6-1-u2-X18"},{"t":"학교 시간표를 정해 주는 일","mis":"SO6-1-u2-X17"}],"explanation":["㉡은 행정부가 했어요.","행정부는 살림을 맡아요.","복구하는 일이에요."],"asset":{"type":"passage","lines":["어린이 보호 구역의 교통안전 문제가 커지자 국가기관들이 저마다 할 일을 했다.","㉠ 보호 구역 교통안전과 관련한 법을 고쳤다.","㉡ 보호 구역에 과속 단속 카메라를 설치하라고 지시했다.","㉢ 규칙을 어긴 운전자를 재판하여 책임을 물었다."],"title":"어린이 보호 구역 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#5','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',3,'mc','auto','우리나라에 국가기관이 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"mc","stem":"우리나라에 국가기관이 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 자유와 권리를 보장하기 위해서","correct":true},{"t":"나랏일을 맡을 사람을 더 많이 뽑으려고","mis":"SO6-1-u2-X17"},{"t":"기관마다 다른 건물을 짓기 위해서","mis":"SO6-1-u2-X17"},{"t":"국민이 나랏일을 몰라도 되게 하려고","mis":"SO6-1-u2-X17"}],"explanation":["누구를 위해 일하나요?","국민을 위해 일해요.","자유와 권리를 보장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#6','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',3,'error','auto','국가기관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"error","stem":"국가기관을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「국가기관이 없어도 나랏일은 저절로 처리돼.」","correct":true,"mis_target":"SO6-1-u2-X17"},{"t":"친구 나 — 「국가기관은 하는 일에 따라 나뉘어.」","mis":"SO6-1-u2-X17"},{"t":"친구 다 — 「국민의 안전과 행복을 위해 일해.」","mis":"SO6-1-u2-X17"}],"explanation":["저절로 처리될까요?","맡을 곳이 있어야 해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#7','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',3,'ox','auto','층간 소음 다툼에서 옳고 그름을 가리고 피해 보상을 하도록 하는 일은 법원이 맡아요.',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"ox","stem":"층간 소음 다툼에서 옳고 그름을 가리고 피해 보상을 하도록 하는 일은 법원이 맡아요.","answer":"O","reason_options":[{"t":"법원은 법에 따라 판결을 내려 다툼을 해결하기 때문에","correct":true},{"t":"다툼은 법을 만드는 국회가 직접 가리기 때문에","mis":"SO6-1-u2-X18"}],"mis":"SO6-1-u2-X18","explanation":["다툼을 가려요.","판결을 내려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#8','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',4,'mc','auto','자료의 세 장면 속 일이 모두 처리될 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17','SO6-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C7","difficulty":4,"kind":"mc","stem":"자료의 세 장면 속 일이 모두 처리될 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"일마다 맡아 하는 국가기관이 있었기 때문에","correct":true},{"t":"일이 저절로 사라졌기 때문에","mis":"SO6-1-u2-X17"},{"t":"국민 한 사람이 세 일을 모두 했기 때문에","mis":"SO6-1-u2-X17"},{"t":"세 일이 모두 법을 만드는 일이었기 때문에","mis":"SO6-1-u2-X18"}],"explanation":["맡을 곳이 있었어요.","하는 일이 달랐어요.","기관이 저마다 처리했어요."],"asset":{"type":"passage","lines":["㉠ 학생들이 안전하고 영양이 풍부한 급식을 먹도록 급식과 관련한 법을 만들었다.","㉡ 홍수가 나자 사람들을 안전하게 대피시키고 피해를 복구했다.","㉢ 층간 소음으로 다툼이 생기자 재판을 하여 피해 보상을 하게 했다."],"title":"나랏일 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#9','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',4,'mc','auto','「국가기관은 국민의 안전과 행복을 위해 일한다」는 말과 가장 잘 어울리는 모습은 어느 것인가요?',ARRAY['SO6-1-u2-X17','SO6-1-u2-X18']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C7","difficulty":4,"kind":"mc","stem":"「국가기관은 국민의 안전과 행복을 위해 일한다」는 말과 가장 잘 어울리는 모습은 어느 것인가요?","options":[{"t":"어린이 보호 구역의 교통안전 대책을 마련한다","correct":true},{"t":"기관끼리 더 큰 건물을 짓는 데 힘쓴다","mis":"SO6-1-u2-X17"},{"t":"국민의 의견과 관계없이 일을 쌓아 둔다","mis":"SO6-1-u2-X17"},{"t":"한 기관이 다른 기관의 일을 모두 가져간다","mis":"SO6-1-u2-X18"}],"explanation":["국민을 위한 일이에요.","안전과 관련 있어요.","교통안전 대책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L05_challenge#10','soc',6,1,'u2','L05','g6_1_soc_u2_L05_challenge','lesson_challenge','SO6-1-u2-C7',4,'essay','teacher','자료의 세 장면을 각각 어느 국가기관이 맡았는지 쓰고, 나랏일을 맡아 하는 국가기관이 없다면 우리 생활에 어떤 일이 생길지 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C7","difficulty":4,"kind":"essay","stem":"자료의 세 장면을 각각 어느 국가기관이 맡았는지 쓰고, 나랏일을 맡아 하는 국가기관이 없다면 우리 생활에 어떤 일이 생길지 한 가지 쓰세요.","answer_guide":{"answer":"예: 급식과 관련한 법을 만든 곳은 국회, 홍수 때 사람들을 대피시키고 피해를 복구한 곳은 행정부, 층간 소음 다툼을 재판으로 가린 곳은 법원이다. 국가기관이 없다면 홍수가 나도 대피와 복구를 맡을 곳이 없어 국민의 안전을 위협받는 일이 생길 수 있다.","scoring_points":["세 장면의 기관을 바르게 썼는가","기관이 없을 때 생길 일을 썼는가","하는 일에 따라 나뉨이 드러났는가"]},"explanation":["법·살림·재판이에요.","세 기관을 써요.","없으면 어떻게 될지 써요."],"asset":{"type":"passage","lines":["㉠ 학생들이 안전하고 영양이 풍부한 급식을 먹도록 급식과 관련한 법을 만들었다.","㉡ 홍수가 나자 사람들을 안전하게 대피시키고 피해를 복구했다.","㉢ 층간 소음으로 다툼이 생기자 재판을 하여 피해 보상을 하게 했다."],"title":"나랏일 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#1','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',1,'sa','auto','국회에서 국민을 대신해 나라의 중요한 일을 결정하는 국민의 대표를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C8","difficulty":1,"kind":"sa","stem":"국회에서 국민을 대신해 나라의 중요한 일을 결정하는 국민의 대표를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["국회의원"],"explanation":["국회를 이루는 사람이에요.","국회◯◯이에요.","국회의원이에요."],"mis":"SO6-1-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#2','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',1,'mc','auto','법률이 될 사항을 정리해 국회에 제출하는 문서를 무엇이라고 하나요?',ARRAY['SO6-1-u2-X21','SO6-1-u2-X19','SO6-1-u2-X18']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C8","difficulty":1,"kind":"mc","stem":"법률이 될 사항을 정리해 국회에 제출하는 문서를 무엇이라고 하나요?","options":[{"t":"법률안","correct":true},{"t":"예산안","mis":"SO6-1-u2-X21"},{"t":"당선증","mis":"SO6-1-u2-X19"},{"t":"판결문","mis":"SO6-1-u2-X18"}],"explanation":["아직 법이 되기 전이에요.","국회에 내는 문서예요.","법률안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#3','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',1,'ox','auto','법률안의 내용을 심의하고 투표하여 결정하는 곳은 국회예요.',ARRAY['SO6-1-u2-X19']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C8","difficulty":1,"kind":"ox","stem":"법률안의 내용을 심의하고 투표하여 결정하는 곳은 국회예요.","answer":"O","reason_options":[{"t":"국회는 법을 만드는 국가기관이기 때문에","correct":true},{"t":"법률안은 대통령 혼자 결정하기 때문에","mis":"SO6-1-u2-X19"}],"mis":"SO6-1-u2-X19","explanation":["법을 만드는 곳이에요.","국회의원들이 모여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#4','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C9',1,'mc','auto','한 해 동안 나라 살림에 쓸 돈의 계획을 살펴보고 정하는 국회의 일은 어느 것인가요?',ARRAY['SO6-1-u2-X21','SO6-1-u2-X20']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C9","difficulty":1,"kind":"mc","stem":"한 해 동안 나라 살림에 쓸 돈의 계획을 살펴보고 정하는 국회의 일은 어느 것인가요?","options":[{"t":"예산안 심의","correct":true},{"t":"인사 청문회","mis":"SO6-1-u2-X21"},{"t":"국정 감사","mis":"SO6-1-u2-X21"},{"t":"법률안 서명","mis":"SO6-1-u2-X20"}],"explanation":["나라 살림에 쓸 돈이에요.","계획을 살펴요.","예산안 심의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#5','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',2,'mc','auto','뒤섞인 카드를 법이 만들어지는 차례대로 늘어놓은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"mc","stem":"뒤섞인 카드를 법이 만들어지는 차례대로 늘어놓은 것은 어느 것인가요?","options":[{"t":"㉢ → ㉡ → ㉣ → ㉠","correct":true},{"t":"㉡ → ㉢ → ㉣ → ㉠","mis":"SO6-1-u2-X19"},{"t":"㉢ → ㉣ → ㉡ → ㉠","mis":"SO6-1-u2-X19"},{"t":"㉢ → ㉡ → ㉠ → ㉣","mis":"SO6-1-u2-X19"}],"explanation":["국민의 요구가 먼저예요.","법률안을 내고 심의해요.","마지막은 서명이에요."],"asset":{"type":"passage","lines":["㉠ 대통령이 서명하여 새 법률을 널리 알리고 시행한다.","㉡ 국회의원이 통학길 안전과 관련한 법률안을 국회에 낸다.","㉢ 통학길을 안전하게 해 달라는 국민의 요구가 늘어난다.","㉣ 국회에서 법률안의 내용을 심의하고 투표하여 결정한다."],"title":"뒤섞인 법 만들기 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#6','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C9',2,'match','auto','국회가 하는 일과 그 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C9","difficulty":2,"kind":"match","stem":"국회가 하는 일과 그 내용을 알맞게 이으세요.","pairs":[{"l":"국정 감사","r":"나라를 잘 운영하는지 확인하고 바로잡도록 요구해요"},{"l":"예산안 심의","r":"나라 살림에 쓸 돈의 계획을 살펴 정해요"},{"l":"인사 청문회","r":"일을 맡을 사람의 능력을 살펴봐요"}],"mis":"SO6-1-u2-X21","explanation":["운영을 확인해요.","돈의 계획이에요.","사람을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#7','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',2,'mc','auto','대통령이 새로운 법에 관한 의견이 다를 때 법률안을 국회로 되돌려 보낼 수 있는 권한을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X20','SO6-1-u2-X21','SO6-1-u2-X18']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"mc","stem":"대통령이 새로운 법에 관한 의견이 다를 때 법률안을 국회로 되돌려 보낼 수 있는 권한을 무엇이라고 하나요?","options":[{"t":"거부권","correct":true},{"t":"서명권","mis":"SO6-1-u2-X20"},{"t":"감사권","mis":"SO6-1-u2-X21"},{"t":"재판권","mis":"SO6-1-u2-X18"}],"explanation":["받아들이지 않을 수 있어요.","되돌려 보내요.","거부권이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#8','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',2,'blank','auto','국회는 법을 만들고, 나랏일이 잘 운영되는지 감시하고 (    )하는 국가기관이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"blank","stem":"국회는 법을 만들고, 나랏일이 잘 운영되는지 감시하고 (    )하는 국가기관이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"견제","correct":true},{"t":"판결","mis":"SO6-1-u2-X18"},{"t":"집행","mis":"SO6-1-u2-X18"},{"t":"홍보","mis":"SO6-1-u2-X18"}],"explanation":["지나치지 않게 살펴요.","감시와 함께 써요.","견제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#9','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',2,'ox','auto','대통령이 법률안을 되돌려 보내면 그 법률안은 그 자리에서 영원히 사라져요.',ARRAY['SO6-1-u2-X20']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"ox","stem":"대통령이 법률안을 되돌려 보내면 그 법률안은 그 자리에서 영원히 사라져요.","answer":"X","reason_options":[{"t":"되돌려 보낸 법률안은 국회로 돌아가 다시 심의하기 때문에","correct":true},{"t":"되돌려 보내는 것은 법을 없애는 일이기 때문에","mis":"SO6-1-u2-X20"}],"mis":"SO6-1-u2-X20","explanation":["국회로 돌아가요.","다시 심의해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_basic#10','soc',6,1,'u2','L06','g6_1_soc_u2_L06_basic','lesson_basic','SO6-1-u2-C8',3,'error','auto','법이 만들어지는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X19','SO6-1-u2-X20']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C8","difficulty":3,"kind":"error","stem":"법이 만들어지는 과정을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「새 법은 대통령이 직접 만들어서 국회에 알려 줘.」","correct":true,"mis_target":"SO6-1-u2-X19"},{"t":"친구 나 — 「국민의 요구가 법을 만드는 출발이 되기도 해.」","mis":"SO6-1-u2-X19"},{"t":"친구 다 — 「마지막에는 대통령이 서명해서 시행해.」","mis":"SO6-1-u2-X20"}],"explanation":["법은 누가 만드나요?","국회가 만들어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#1','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C9',2,'sa','auto','국회가 행정부가 법에 따라 나라를 잘 운영하는지 확인하고 감독하는 일을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C9","difficulty":2,"kind":"sa","stem":"국회가 행정부가 법에 따라 나라를 잘 운영하는지 확인하고 감독하는 일을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["국정감사","국정 감사"],"explanation":["나랏일을 살펴요.","국정 ◯◯예요.","국정 감사예요."],"mis":"SO6-1-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#2','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C9',2,'ox','auto','국회가 국정 감사, 예산안 심의, 인사 청문회를 하는 것은 국회가 국민을 대표하는 기관이기 때문이에요.',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C9","difficulty":2,"kind":"ox","stem":"국회가 국정 감사, 예산안 심의, 인사 청문회를 하는 것은 국회가 국민을 대표하는 기관이기 때문이에요.","answer":"O","reason_options":[{"t":"국민을 대신해 나랏일을 살피고 정하는 일이기 때문에","correct":true},{"t":"국회가 나라 살림을 직접 맡아 하기 때문에","mis":"SO6-1-u2-X18"}],"mis":"SO6-1-u2-X18","explanation":["국민의 대표예요.","국민을 대신해 살펴요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#3','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C8',3,'mc','auto','법을 만드는 걸음은 국회가 하고 마지막 서명은 대통령이 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X20','SO6-1-u2-X19']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C8","difficulty":3,"kind":"mc","stem":"법을 만드는 걸음은 국회가 하고 마지막 서명은 대통령이 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국회에서 마음대로 법을 만들지 못하게 하기 위해서","correct":true},{"t":"법을 만드는 일을 대통령이 대신 하기 위해서","mis":"SO6-1-u2-X20"},{"t":"법률안을 더 빨리 시행하기 위해서","mis":"SO6-1-u2-X20"},{"t":"국회의원이 서명하는 방법을 몰라서","mis":"SO6-1-u2-X19"}],"explanation":["두 자리가 나눠 맡아요.","한 자리가 다 하지 않아요.","마음대로 만들지 못하게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#4','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C8',3,'mc','auto','자료에서 대통령이 ㉠ 대신 법률안을 되돌려 보낸다면 다음에 일어날 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X20','SO6-1-u2-X19','SO6-1-u2-X18']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C8","difficulty":3,"kind":"mc","stem":"자료에서 대통령이 ㉠ 대신 법률안을 되돌려 보낸다면 다음에 일어날 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법률안이 국회로 돌아가 ㉣을 다시 한다","correct":true},{"t":"법률안이 그대로 시행된다","mis":"SO6-1-u2-X20"},{"t":"국민이 ㉢부터 다시 요구해야만 한다","mis":"SO6-1-u2-X19"},{"t":"법률안이 법원으로 넘어간다","mis":"SO6-1-u2-X18"}],"explanation":["되돌려 보내요.","국회로 돌아가요.","다시 심의해요."],"asset":{"type":"passage","lines":["㉠ 대통령이 서명하여 새 법률을 널리 알리고 시행한다.","㉡ 국회의원이 통학길 안전과 관련한 법률안을 국회에 낸다.","㉢ 통학길을 안전하게 해 달라는 국민의 요구가 늘어난다.","㉣ 국회에서 법률안의 내용을 심의하고 투표하여 결정한다."],"title":"뒤섞인 법 만들기 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#5','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C9',3,'mc','auto','자료의 ㉰는 국회가 하는 어떤 일인가요?',ARRAY['SO6-1-u2-X21','SO6-1-u2-X19']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C9","difficulty":3,"kind":"mc","stem":"자료의 ㉰는 국회가 하는 어떤 일인가요?","options":[{"t":"인사 청문회","correct":true},{"t":"국정 감사","mis":"SO6-1-u2-X21"},{"t":"예산안 심의","mis":"SO6-1-u2-X21"},{"t":"법률안 제출","mis":"SO6-1-u2-X19"}],"explanation":["사람을 살펴요.","능력을 확인해요.","인사 청문회예요."],"asset":{"type":"passage","lines":["㉮ 나라를 잘 운영하는지 확인하고 감독하며, 잘못이 있으면 바로잡도록 요구한다.","㉯ 한 해 나라 살림에 쓸 돈의 계획을 살펴 정하고, 잘 썼는지 살핀다.","㉰ 일을 맡을 사람이 그 일에 알맞은 능력을 갖췄는지 살펴본다."],"title":"국회가 하는 다른 일 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#6','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C9',3,'error','auto','국회가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X21']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C9","difficulty":3,"kind":"error","stem":"국회가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「국정 감사는 국회가 다툼을 재판으로 가리는 일이야.」","correct":true,"mis_target":"SO6-1-u2-X21"},{"t":"친구 가 — 「예산안은 나라 살림에 쓸 돈의 계획이야.」","mis":"SO6-1-u2-X21"},{"t":"친구 나 — 「국정 감사로 잘못된 일을 바로잡도록 요구해.」","mis":"SO6-1-u2-X21"}],"explanation":["국정 감사는 무엇을 살피나요?","나라를 잘 운영하는지 봐요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#7','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C8',3,'ox','auto','대통령이 법률안을 되돌려 보내는 것은 언제나 잘못된 일이에요.',ARRAY['SO6-1-u2-X20']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C8","difficulty":3,"kind":"ox","stem":"대통령이 법률안을 되돌려 보내는 것은 언제나 잘못된 일이에요.","answer":"X","reason_options":[{"t":"대통령은 새 법에 관한 의견이 다르면 거부권을 행사할 수 있기 때문에","correct":true},{"t":"대통령은 법률안에 무조건 서명해야 하기 때문에","mis":"SO6-1-u2-X20"}],"mis":"SO6-1-u2-X20","explanation":["행사할 수 있는 권한이에요.","옳고 그름의 문제가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#8','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C8',4,'mc','auto','자료의 과정 전체를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X19','SO6-1-u2-X20']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C8","difficulty":4,"kind":"mc","stem":"자료의 과정 전체를 보고 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"법은 국민의 요구에서 출발해 국회의 심의와 대통령의 서명을 거쳐 시행된다","correct":true},{"t":"법은 대통령 혼자 만들어 시행한다","mis":"SO6-1-u2-X19"},{"t":"법은 국민의 요구와 관계없이 만들어진다","mis":"SO6-1-u2-X19"},{"t":"국회가 결정하면 서명 없이 바로 시행된다","mis":"SO6-1-u2-X20"}],"explanation":["국민의 요구가 출발이에요.","국회가 심의해요.","대통령이 서명해요."],"asset":{"type":"passage","lines":["㉠ 대통령이 서명하여 새 법률을 널리 알리고 시행한다.","㉡ 국회의원이 통학길 안전과 관련한 법률안을 국회에 낸다.","㉢ 통학길을 안전하게 해 달라는 국민의 요구가 늘어난다.","㉣ 국회에서 법률안의 내용을 심의하고 투표하여 결정한다."],"title":"뒤섞인 법 만들기 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#9','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C9',4,'mc','auto','국회가 하는 여러 일에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X21']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C9","difficulty":4,"kind":"mc","stem":"국회가 하는 여러 일에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민을 대표해 법을 만들고 나랏일이 잘 운영되는지 살핀다","correct":true},{"t":"국민 대신 재판을 한다","mis":"SO6-1-u2-X18"},{"t":"나라 살림을 직접 운영한다","mis":"SO6-1-u2-X18"},{"t":"대통령의 일을 대신 맡는다","mis":"SO6-1-u2-X21"}],"explanation":["법을 만들어요.","나랏일을 살펴요.","국민을 대표해요."],"asset":{"type":"passage","lines":["㉮ 나라를 잘 운영하는지 확인하고 감독하며, 잘못이 있으면 바로잡도록 요구한다.","㉯ 한 해 나라 살림에 쓸 돈의 계획을 살펴 정하고, 잘 썼는지 살핀다.","㉰ 일을 맡을 사람이 그 일에 알맞은 능력을 갖췄는지 살펴본다."],"title":"국회가 하는 다른 일 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L06_challenge#10','soc',6,1,'u2','L06','g6_1_soc_u2_L06_challenge','lesson_challenge','SO6-1-u2-C8',4,'essay','teacher','우리 생활에서 고쳤으면 하는 문제 하나를 골라, 그 문제를 해결할 법이 만들어지기까지의 과정을 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C8","difficulty":4,"kind":"essay","stem":"우리 생활에서 고쳤으면 하는 문제 하나를 골라, 그 문제를 해결할 법이 만들어지기까지의 과정을 차례대로 쓰세요.","answer_guide":{"answer":"예: 학교 앞 횡단보도가 위험하다는 문제를 골랐다. 먼저 통학길을 안전하게 해 달라는 국민의 요구가 늘어나면, 국회의원이 통학길 안전과 관련한 법률안을 국회에 낸다. 국회에서 국회의원들이 법률안을 심의하고 투표하여 결정하면, 대통령이 서명하여 새 법률을 널리 알리고 시행한다.","scoring_points":["문제를 골랐는가","요구 → 법률안 → 심의·투표 → 서명의 차례를 썼는가","국회와 대통령이 하는 일을 구분했는가"]},"explanation":["문제를 골라요.","네 걸음을 차례대로 써요.","누가 하는지도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#1','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',1,'mc','auto','대통령, 국무총리, 행정 각부 등으로 이루어진 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C10","difficulty":1,"kind":"mc","stem":"대통령, 국무총리, 행정 각부 등으로 이루어진 국가기관은 어디인가요?","options":[{"t":"행정부","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"법원","mis":"SO6-1-u2-X18"},{"t":"시민 단체","mis":"SO6-1-u2-X18"}],"explanation":["나라 살림을 맡아요.","대통령이 최고 책임자예요.","행정부예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#2','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',1,'sa','auto','대통령을 보좌하고 행정 각부를 관리하는 사람은 누구인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C10","difficulty":1,"kind":"sa","stem":"대통령을 보좌하고 행정 각부를 관리하는 사람은 누구인가요? 네 글자로 쓰세요.","answer":["국무총리"],"explanation":["대통령을 돕는 자리예요.","국무◯◯예요.","국무총리예요."],"mis":"SO6-1-u2-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#3','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',1,'ox','auto','대통령은 행정부의 최고 책임자이자 우리나라의 대표예요.',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C10","difficulty":1,"kind":"ox","stem":"대통령은 행정부의 최고 책임자이자 우리나라의 대표예요.","answer":"O","reason_options":[{"t":"국민이 선출한 대통령이 나라의 중요한 일을 결정하기 때문에","correct":true},{"t":"대통령은 법을 만드는 일만 맡기 때문에","mis":"SO6-1-u2-X22"}],"mis":"SO6-1-u2-X22","explanation":["국민이 선출했어요.","중요한 일을 결정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#4','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C11',1,'mc','auto','행정 각부가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X23','SO6-1-u2-X18']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C11","difficulty":1,"kind":"mc","stem":"행정 각부가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"경제·교육·외교·국방·환경 등의 업무를 나눠 맡는다","correct":true},{"t":"나라의 모든 업무를 한 곳이 도맡는다","mis":"SO6-1-u2-X23"},{"t":"법률을 만든다","mis":"SO6-1-u2-X18"},{"t":"재판으로 판결을 내린다","mis":"SO6-1-u2-X18"}],"explanation":["여러 부가 있어요.","업무를 나눠요.","나눠 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#5','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',2,'mc','auto','대통령이 임무를 수행할 수 없는 상황이 생기면 대통령의 임무를 대신하는 사람은 누구인가요?',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C10","difficulty":2,"kind":"mc","stem":"대통령이 임무를 수행할 수 없는 상황이 생기면 대통령의 임무를 대신하는 사람은 누구인가요?","options":[{"t":"국무총리","correct":true},{"t":"행정 각부의 공무원 누구나","mis":"SO6-1-u2-X22"},{"t":"가장 나이 많은 국민","mis":"SO6-1-u2-X22"},{"t":"대통령의 가족","mis":"SO6-1-u2-X22"}],"explanation":["대통령을 보좌하는 자리예요.","대신 맡아요.","국무총리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#6','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C11',2,'match','auto','카드 뉴스와 그 카드 뉴스를 만들었을 행정 각부의 업무를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C11","difficulty":2,"kind":"match","stem":"카드 뉴스와 그 카드 뉴스를 만들었을 행정 각부의 업무를 알맞게 이으세요.","pairs":[{"l":"① 장래 희망 이야기","r":"교육"},{"l":"② 국립 공원 소개","r":"환경"},{"l":"③ 경제 정책의 방향","r":"경제"},{"l":"④ 다른 나라와 함께한 일","r":"외교"}],"mis":"SO6-1-u2-X23","explanation":["꿈은 교육이에요.","공원은 환경이에요.","다른 나라와는 외교예요."],"asset":{"type":"passage","lines":["① 학생들이 꿈꾸는 장래 희망을 이야기하는 카드 뉴스","② 국립 공원의 아름다움을 소개하는 카드 뉴스","③ 우리나라 경제 정책의 방향을 알리는 카드 뉴스","④ 다른 나라와 함께한 일을 담은 카드 뉴스"],"title":"행정 각부가 만든 카드 뉴스 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#7','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C11',2,'blank','auto','(    )에서는 대통령, 국무총리, 행정 각부의 장을 비롯한 국무 위원들이 나라의 중요한 일이나 정책을 의논해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X23']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C11","difficulty":2,"kind":"blank","stem":"(    )에서는 대통령, 국무총리, 행정 각부의 장을 비롯한 국무 위원들이 나라의 중요한 일이나 정책을 의논해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"국무 회의","correct":true},{"t":"학급 회의","mis":"SO6-1-u2-X23"},{"t":"주민 회의","mis":"SO6-1-u2-X23"},{"t":"가족회의","mis":"SO6-1-u2-X23"}],"explanation":["국무 위원이 모여요.","정책을 의논해요.","국무 회의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#8','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',2,'mc','auto','자료의 세 자리 가운데 국민이 선출한 자리는 어느 것인가요?',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C10","difficulty":2,"kind":"mc","stem":"자료의 세 자리 가운데 국민이 선출한 자리는 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SO6-1-u2-X22"},{"t":"㉢","mis":"SO6-1-u2-X22"},{"t":"㉡과 ㉢","mis":"SO6-1-u2-X22"}],"explanation":["최고 책임자예요.","우리나라의 대표예요.","㉠이에요."],"asset":{"type":"passage","lines":["㉠ 행정부의 최고 책임자이자 우리나라의 대표로 나라의 중요한 일을 결정한다.","㉡ ㉠을 보좌하고 행정 각부를 관리한다.","㉢ 경제·교육·외교·국방·환경 등의 업무를 나눠 맡는다."],"title":"행정부를 이루는 세 자리"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#9','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C10',2,'ox','auto','대통령이 잠시 임무를 수행할 수 없게 되면 나라의 중요한 일도 함께 멈춰요.',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C10","difficulty":2,"kind":"ox","stem":"대통령이 잠시 임무를 수행할 수 없게 되면 나라의 중요한 일도 함께 멈춰요.","answer":"X","reason_options":[{"t":"국무총리가 대통령의 임무를 대신해 나라의 살림이 이어지기 때문에","correct":true},{"t":"대통령이 없으면 행정부도 없어지기 때문에","mis":"SO6-1-u2-X22"}],"mis":"SO6-1-u2-X22","explanation":["대신 맡는 자리가 있어요.","살림은 멈추지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_basic#10','soc',6,1,'u2','L07','g6_1_soc_u2_L07_basic','lesson_basic','SO6-1-u2-C11',3,'error','auto','행정부를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X23']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C11","difficulty":3,"kind":"error","stem":"행정부를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「행정 각부는 저마다 나라의 중요한 일을 따로 정해.」","correct":true,"mis_target":"SO6-1-u2-X23"},{"t":"친구 가 — 「중요한 일은 국무 회의에서 함께 의논해.」","mis":"SO6-1-u2-X23"},{"t":"친구 다 — 「행정 각부는 업무를 나눠 맡아.」","mis":"SO6-1-u2-X23"}],"explanation":["중요한 일은 어디서 정하나요?","함께 의논해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#1','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C11',2,'sa','auto','대통령, 국무총리, 행정 각부의 장 등이 모여 나라의 중요한 정책을 의논하는 회의를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C11","difficulty":2,"kind":"sa","stem":"대통령, 국무총리, 행정 각부의 장 등이 모여 나라의 중요한 정책을 의논하는 회의를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["국무회의","국무 회의"],"explanation":["국무 위원이 모여요.","국무 ◯◯예요.","국무 회의예요."],"mis":"SO6-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#2','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C11',2,'ox','auto','행정부 조직은 한 번 정해지면 이름이 바뀌거나 새로 만들어지는 일이 없어요.',ARRAY['SO6-1-u2-X23']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C11","difficulty":2,"kind":"ox","stem":"행정부 조직은 한 번 정해지면 이름이 바뀌거나 새로 만들어지는 일이 없어요.","answer":"X","reason_options":[{"t":"행정부 조직은 필요에 따라 새로 만들어지거나 조정되고 이름이 바뀌기도 하기 때문에","correct":true},{"t":"행정 각부는 처음부터 지금까지 똑같기 때문에","mis":"SO6-1-u2-X23"}],"mis":"SO6-1-u2-X23","explanation":["조직은 달라질 수 있어요.","이름도 바뀌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#3','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C10',3,'mc','auto','국무총리가 대통령의 임무를 대신 맡는 동안 국무총리가 본래 하던 일은 어떻게 되나요?',ARRAY['SO6-1-u2-X22','SO6-1-u2-X23']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C10","difficulty":3,"kind":"mc","stem":"국무총리가 대통령의 임무를 대신 맡는 동안 국무총리가 본래 하던 일은 어떻게 되나요?","options":[{"t":"그대로 함께 맡는다","correct":true},{"t":"모두 멈춘다","mis":"SO6-1-u2-X22"},{"t":"대통령이 맡는다","mis":"SO6-1-u2-X22"},{"t":"행정 각부 하나가 모두 가져간다","mis":"SO6-1-u2-X23"}],"explanation":["두 몫을 함께 져요.","본래 몫도 그대로예요.","함께 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#4','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C10',3,'mc','auto','대통령 자리가 비어도 국무총리가 그 일을 대신 맡게 해 둔 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X22','SO6-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C10","difficulty":3,"kind":"mc","stem":"대통령 자리가 비어도 국무총리가 그 일을 대신 맡게 해 둔 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라의 살림은 멈출 수 없기 때문에","correct":true},{"t":"국무총리의 힘을 키우기 위해서","mis":"SO6-1-u2-X22"},{"t":"대통령의 일을 없애기 위해서","mis":"SO6-1-u2-X22"},{"t":"행정 각부가 할 일이 없어서","mis":"SO6-1-u2-X23"}],"explanation":["살림이 멈추면 어떻게 될까요?","국민이 불편해져요.","멈출 수 없기 때문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#5','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C11',3,'mc','auto','자료의 카드 뉴스를 행정 각부가 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X23','SO6-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C11","difficulty":3,"kind":"mc","stem":"자료의 카드 뉴스를 행정 각부가 만드는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"업무를 나눠 맡은 각 부가 하는 일을 국민에게 알리려고","correct":true},{"t":"한 부가 모든 일을 한다는 것을 알리려고","mis":"SO6-1-u2-X23"},{"t":"법을 새로 만들려고","mis":"SO6-1-u2-X18"},{"t":"재판 결과를 알리려고","mis":"SO6-1-u2-X18"}],"explanation":["부마다 하는 일이 달라요.","국민에게 알려요.","하는 일을 알리려고요."],"asset":{"type":"passage","lines":["① 학생들이 꿈꾸는 장래 희망을 이야기하는 카드 뉴스","② 국립 공원의 아름다움을 소개하는 카드 뉴스","③ 우리나라 경제 정책의 방향을 알리는 카드 뉴스","④ 다른 나라와 함께한 일을 담은 카드 뉴스"],"title":"행정 각부가 만든 카드 뉴스 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#6','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C10',3,'error','auto','행정부를 이루는 자리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C10","difficulty":3,"kind":"error","stem":"행정부를 이루는 자리를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「국무총리가 행정부의 최고 책임자야.」","correct":true,"mis_target":"SO6-1-u2-X22"},{"t":"친구 가 — 「대통령은 국민이 선출해.」","mis":"SO6-1-u2-X22"},{"t":"친구 나 — 「국무총리는 대통령을 보좌해.」","mis":"SO6-1-u2-X22"}],"explanation":["최고 책임자는 누구일까요?","대통령이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#7','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C11',3,'mc','auto','나라의 중요한 일을 행정 각부가 따로 정하지 않고 국무 회의에서 함께 의논하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X23','SO6-1-u2-X22']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C11","difficulty":3,"kind":"mc","stem":"나라의 중요한 일을 행정 각부가 따로 정하지 않고 국무 회의에서 함께 의논하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 업무가 서로 이어져 있어 함께 살펴야 하기 때문에","correct":true},{"t":"각 부가 하는 일이 모두 똑같기 때문에","mis":"SO6-1-u2-X23"},{"t":"회의를 하면 대통령이 필요 없기 때문에","mis":"SO6-1-u2-X22"},{"t":"한 부가 모든 일을 정하기 때문에","mis":"SO6-1-u2-X23"}],"explanation":["업무가 이어져 있어요.","함께 살펴요.","그래서 의논해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#8','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C10',4,'mc','auto','행정부가 하는 일을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X23','SO6-1-u2-X22']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C10","difficulty":4,"kind":"mc","stem":"행정부가 하는 일을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"법에 따라 나라 살림을 맡아, 업무를 나누고 함께 의논하며 국민의 안전하고 편리한 삶을 위해 일한다","correct":true},{"t":"법을 만들고 판결을 내린다","mis":"SO6-1-u2-X18"},{"t":"대통령 혼자 모든 업무를 처리한다","mis":"SO6-1-u2-X23"},{"t":"대통령이 없으면 모든 일을 멈춘다","mis":"SO6-1-u2-X22"}],"explanation":["법에 따라 살림을 맡아요.","나누고 의논해요.","국민의 삶을 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#9','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C11',4,'mc','auto','「학교 안전 교육 자료를 새로 만들어 학교에 나눠 주었다」는 소식을 보고 판단한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X23']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C11","difficulty":4,"kind":"mc","stem":"「학교 안전 교육 자료를 새로 만들어 학교에 나눠 주었다」는 소식을 보고 판단한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"교육 업무를 맡은 행정 각부가 한 일일 것이다","correct":true},{"t":"법원이 판결로 한 일일 것이다","mis":"SO6-1-u2-X18"},{"t":"국방 업무를 맡은 부가 한 일일 것이다","mis":"SO6-1-u2-X23"},{"t":"행정 각부는 이런 일을 하지 않는다","mis":"SO6-1-u2-X23"}],"explanation":["학교와 관련 있어요.","교육 업무예요.","그 부가 한 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L07_challenge#10','soc',6,1,'u2','L07','g6_1_soc_u2_L07_challenge','lesson_challenge','SO6-1-u2-C10',4,'essay','teacher','대통령·국무총리·행정 각부가 각각 하는 일을 쓰고, 대통령이 임무를 수행할 수 없을 때 나라의 살림이 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C10","difficulty":4,"kind":"essay","stem":"대통령·국무총리·행정 각부가 각각 하는 일을 쓰고, 대통령이 임무를 수행할 수 없을 때 나라의 살림이 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 대통령은 국민이 선출한 행정부의 최고 책임자로 나라의 중요한 일을 결정한다. 국무총리는 대통령을 보좌하고 행정 각부를 관리하며, 행정 각부는 경제·교육·외교·국방·환경 등의 업무를 나눠 맡는다. 대통령이 임무를 수행할 수 없게 되면 국무총리가 대통령의 임무를 대신 맡아 나라의 살림이 멈추지 않고 이어진다.","scoring_points":["세 자리가 하는 일을 썼는가","국무총리가 대신 맡음을 썼는가","살림이 멈추지 않는 까닭이 드러났는가"]},"explanation":["세 자리를 써요.","국무총리가 대신해요.","살림은 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#1','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C12',1,'mc','auto','사람들 사이에 다툼이 생기거나 범죄가 일어났을 때 재판을 통해 옳고 그름을 가리는 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X24']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C12","difficulty":1,"kind":"mc","stem":"사람들 사이에 다툼이 생기거나 범죄가 일어났을 때 재판을 통해 옳고 그름을 가리는 국가기관은 어디인가요?","options":[{"t":"법원","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"행정부","mis":"SO6-1-u2-X18"},{"t":"시민 단체","mis":"SO6-1-u2-X24"}],"explanation":["재판을 해요.","옳고 그름을 가려요.","법원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#2','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',1,'sa','auto','하나의 사건에 대해 원칙적으로 세 번까지 재판을 받을 수 있도록 한 제도를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C13","difficulty":1,"kind":"sa","stem":"하나의 사건에 대해 원칙적으로 세 번까지 재판을 받을 수 있도록 한 제도를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["삼심제도","삼심 제도"],"explanation":["세 번까지예요.","삼◯ 제도예요.","삼심 제도예요."],"mis":"SO6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#3','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C12',1,'ox','auto','법원은 법을 어긴 사람을 처벌하여 사회 질서를 유지해요.',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C12","difficulty":1,"kind":"ox","stem":"법원은 법을 어긴 사람을 처벌하여 사회 질서를 유지해요.","answer":"O","reason_options":[{"t":"재판으로 옳고 그름을 가려 법을 지키게 하기 때문에","correct":true},{"t":"법원은 법을 만드는 일만 하기 때문에","mis":"SO6-1-u2-X18"}],"mis":"SO6-1-u2-X18","explanation":["법을 어기면 처벌해요.","질서를 지켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#4','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C12',1,'mc','auto','법을 어겼다고 판단해 재판에 세운 사람을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X24']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C12","difficulty":1,"kind":"mc","stem":"법을 어겼다고 판단해 재판에 세운 사람을 무엇이라고 하나요?","options":[{"t":"피고인","correct":true},{"t":"피해자","mis":"SO6-1-u2-X24"},{"t":"의뢰인","mis":"SO6-1-u2-X24"},{"t":"법관","mis":"SO6-1-u2-X24"}],"explanation":["재판에 선 사람이에요.","피◯◯이에요.","피고인이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#5','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C12',2,'match','auto','자료의 장면과 법원이 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u2-C12","difficulty":2,"kind":"match","stem":"자료의 장면과 법원이 하는 일을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"개인 사이의 다툼을 해결해요"},{"l":"㉡","r":"법을 어긴 사람을 처벌해요"},{"l":"㉢","r":"개인과 국가 사이의 갈등을 해결해요"}],"mis":"SO6-1-u2-X24","explanation":["이웃끼리의 다툼이에요.","법을 어겼어요.","나라와의 갈등이에요."],"asset":{"type":"passage","lines":["㉠ 「위층 소음 때문에 밤에 잠을 잘 수 없어요. 피해에 대한 위자료를 주세요.」","㉡ 「물건을 가져간 것이 증거 영상으로 확인되어 벌금을 선고합니다.」","㉢ 「도로 공사로 우리 집이 피해를 보았어요. 나라에서 보상해 주세요.」"],"title":"법원 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#6','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',2,'mc','auto','공정한 재판을 위한 우리나라의 제도로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X25','SO6-1-u2-X26']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"mc","stem":"공정한 재판을 위한 우리나라의 제도로 알맞은 것은 어느 것인가요?","options":[{"t":"특별한 경우를 빼고 재판의 과정과 결과를 공개한다","correct":true},{"t":"재판을 모두 비공개로 한다","mis":"SO6-1-u2-X25"},{"t":"법원이 다른 국가기관과 협의해 판결한다","mis":"SO6-1-u2-X25"},{"t":"재판은 단 한 번만 받는다","mis":"SO6-1-u2-X26"}],"explanation":["감추지 않아요.","누구나 볼 수 있어요.","공개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#7','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',2,'blank','auto','법원은 다른 국가기관의 영향을 받지 않고 (    )으로 운영되며, 헌법으로 법관의 신분을 보장해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X25']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"blank","stem":"법원은 다른 국가기관의 영향을 받지 않고 (    )으로 운영되며, 헌법으로 법관의 신분을 보장해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"독립적","correct":true},{"t":"의존적","mis":"SO6-1-u2-X25"},{"t":"일시적","mis":"SO6-1-u2-X25"},{"t":"형식적","mis":"SO6-1-u2-X25"}],"explanation":["영향을 받지 않아요.","홀로 서요.","독립적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#8','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',2,'mc','auto','자료에서 판정이 달라질 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X26','SO6-1-u2-X25']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"mc","stem":"자료에서 판정이 달라질 수 있었던 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 사건을 더 위의 법원에서 다시 재판받을 수 있었기 때문에","correct":true},{"t":"사건 내용이 3심에서 바뀌었기 때문에","mis":"SO6-1-u2-X26"},{"t":"재판을 원하는 만큼 계속 받을 수 있기 때문에","mis":"SO6-1-u2-X26"},{"t":"1심 재판을 감추었기 때문에","mis":"SO6-1-u2-X25"}],"explanation":["사건은 그대로예요.","위의 법원이 다시 판정했어요.","삼심 제도 덕분이에요."],"asset":{"type":"passage","lines":["병원의 판단 잘못으로 환자에게 큰 피해가 생겼다며 가족이 재판을 청했다.","1심 — 지방 법원은 병원 측의 손을 들어 주었다.","2심 — 고등 법원도 같은 판정을 내렸다.","3심 — 대법원은 병원이 일부 잘못 판단했다고 보아 가족이 손해 배상을 받게 했다."],"title":"세 번 재판을 받은 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#9','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',2,'ox','auto','하나의 사건에 대해서는 원하는 만큼 몇 번이고 계속 재판을 받을 수 있어요.',ARRAY['SO6-1-u2-X26']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"ox","stem":"하나의 사건에 대해서는 원하는 만큼 몇 번이고 계속 재판을 받을 수 있어요.","answer":"X","reason_options":[{"t":"원칙적으로 세 번까지 재판을 받을 수 있기 때문에","correct":true},{"t":"재판에는 정해진 횟수가 없기 때문에","mis":"SO6-1-u2-X26"}],"mis":"SO6-1-u2-X26","explanation":["횟수가 정해져 있어요.","세 번까지예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_basic#10','soc',6,1,'u2','L08','g6_1_soc_u2_L08_basic','lesson_basic','SO6-1-u2-C13',3,'error','auto','공정한 재판을 위협하는 상황을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X25','SO6-1-u2-X26']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C13","difficulty":3,"kind":"error","stem":"공정한 재판을 위협하는 상황을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「상황 3을 막으려고 재판은 모두 비공개로 해.」","correct":true,"mis_target":"SO6-1-u2-X25"},{"t":"친구 가 — 「상황 1을 막으려고 법원을 독립시켜.」","mis":"SO6-1-u2-X25"},{"t":"친구 나 — 「상황 2를 막으려고 삼심 제도를 둬.」","mis":"SO6-1-u2-X26"}],"explanation":["상황 3은 감추는 거예요.","막으려면 공개해야 해요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["상황 1 — 법관이 바깥의 간섭을 받아 판결을 내린다면?","상황 2 — 단 한 번의 재판으로 판결 내용이 정해진다면?","상황 3 — 재판의 과정과 결과를 모두 감춘다면?"],"title":"공정한 재판을 위협하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#1','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C12',2,'sa','auto','법률 상담을 하고, 다툼이나 범죄 사건이 생겼을 때 의뢰인을 도와 변호를 해 주는 사람은 누구인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C12","difficulty":2,"kind":"sa","stem":"법률 상담을 하고, 다툼이나 범죄 사건이 생겼을 때 의뢰인을 도와 변호를 해 주는 사람은 누구인가요? 세 글자로 쓰세요.","answer":["변호사"],"explanation":["의뢰인을 도와요.","변◯◯예요.","변호사예요."],"mis":"SO6-1-u2-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#2','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C12',2,'ox','auto','개인과 국가, 지방 자치 단체 사이의 갈등은 법원에서 다룰 수 없어요.',ARRAY['SO6-1-u2-X24']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C12","difficulty":2,"kind":"ox","stem":"개인과 국가, 지방 자치 단체 사이의 갈등은 법원에서 다룰 수 없어요.","answer":"X","reason_options":[{"t":"법원은 개인과 국가 사이의 갈등도 재판으로 해결하기 때문에","correct":true},{"t":"국가가 하는 일은 언제나 옳기 때문에","mis":"SO6-1-u2-X24"}],"mis":"SO6-1-u2-X24","explanation":["국가와의 갈등도 있어요.","법원이 가려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#3','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',3,'mc','auto','자료의 상황과 그 상황을 막는 제도를 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X25','SO6-1-u2-X26']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C13","difficulty":3,"kind":"mc","stem":"자료의 상황과 그 상황을 막는 제도를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"상황 1 — 법원의 독립 · 상황 2 — 삼심 제도 · 상황 3 — 재판 공개","correct":true},{"t":"상황 1 — 삼심 제도 · 상황 2 — 재판 공개 · 상황 3 — 법원의 독립","mis":"SO6-1-u2-X25"},{"t":"상황 1 — 재판 공개 · 상황 2 — 법원의 독립 · 상황 3 — 삼심 제도","mis":"SO6-1-u2-X25"},{"t":"세 상황 모두 삼심 제도 하나로 막는다","mis":"SO6-1-u2-X26"}],"explanation":["간섭은 독립으로 막아요.","한 번은 세 번으로요.","감춤은 공개로요."],"asset":{"type":"passage","lines":["상황 1 — 법관이 바깥의 간섭을 받아 판결을 내린다면?","상황 2 — 단 한 번의 재판으로 판결 내용이 정해진다면?","상황 3 — 재판의 과정과 결과를 모두 감춘다면?"],"title":"공정한 재판을 위협하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#4','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',3,'mc','auto','자료에서 삼심 제도가 없었다면 어떻게 되었을지로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X26']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C13","difficulty":3,"kind":"mc","stem":"자료에서 삼심 제도가 없었다면 어떻게 되었을지로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"1심 판정으로 끝나 가족은 손해 배상을 받지 못했을 것이다","correct":true},{"t":"병원이 더 빨리 배상했을 것이다","mis":"SO6-1-u2-X26"},{"t":"재판이 더 공정해졌을 것이다","mis":"SO6-1-u2-X26"},{"t":"사건 내용이 저절로 바뀌었을 것이다","mis":"SO6-1-u2-X26"}],"explanation":["1심은 병원 측이었어요.","3심에서 달라졌어요.","없었다면 1심으로 끝나요."],"asset":{"type":"passage","lines":["병원의 판단 잘못으로 환자에게 큰 피해가 생겼다며 가족이 재판을 청했다.","1심 — 지방 법원은 병원 측의 손을 들어 주었다.","2심 — 고등 법원도 같은 판정을 내렸다.","3심 — 대법원은 병원이 일부 잘못 판단했다고 보아 가족이 손해 배상을 받게 했다."],"title":"세 번 재판을 받은 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#5','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',3,'mc','auto','재판이 공정하게 이루어져야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X25','SO6-1-u2-X24']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C13","difficulty":3,"kind":"mc","stem":"재판이 공정하게 이루어져야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 자유와 권리를 보장하기 위해서","correct":true},{"t":"재판을 빨리 끝내기 위해서","mis":"SO6-1-u2-X25"},{"t":"법원이 다른 기관보다 힘이 세지기 위해서","mis":"SO6-1-u2-X25"},{"t":"재판받는 사람을 줄이기 위해서","mis":"SO6-1-u2-X24"}],"explanation":["억울한 사람이 없어야 해요.","국민을 위해서예요.","자유와 권리를 보장해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#6','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C12',3,'error','auto','법원 세 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X24']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C12","difficulty":3,"kind":"error","stem":"법원 세 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉢은 개인끼리의 다툼이라 나라와는 관계없어.」","correct":true,"mis_target":"SO6-1-u2-X24"},{"t":"친구 가 — 「㉠은 이웃 사이의 다툼을 해결하는 장면이야.」","mis":"SO6-1-u2-X24"},{"t":"친구 다 — 「㉡은 법을 어긴 사람을 처벌하는 장면이야.」","mis":"SO6-1-u2-X24"}],"explanation":["㉢은 누구에게 보상을 청하나요?","나라예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 「위층 소음 때문에 밤에 잠을 잘 수 없어요. 피해에 대한 위자료를 주세요.」","㉡ 「물건을 가져간 것이 증거 영상으로 확인되어 벌금을 선고합니다.」","㉢ 「도로 공사로 우리 집이 피해를 보았어요. 나라에서 보상해 주세요.」"],"title":"법원 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#7','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',3,'ox','auto','자료에서 1심과 2심의 판정이 같았으니 3심에서도 판정은 바뀔 수 없었어요.',ARRAY['SO6-1-u2-X26']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C13","difficulty":3,"kind":"ox","stem":"자료에서 1심과 2심의 판정이 같았으니 3심에서도 판정은 바뀔 수 없었어요.","answer":"X","reason_options":[{"t":"더 위의 법원이 다시 판정하면 앞의 판정과 달라질 수 있기 때문에","correct":true},{"t":"한 번 내린 판정은 절대 바뀌지 않기 때문에","mis":"SO6-1-u2-X26"}],"mis":"SO6-1-u2-X26","explanation":["3심에서 달라졌어요.","다시 판정해요.","그래서 X예요."],"asset":{"type":"passage","lines":["병원의 판단 잘못으로 환자에게 큰 피해가 생겼다며 가족이 재판을 청했다.","1심 — 지방 법원은 병원 측의 손을 들어 주었다.","2심 — 고등 법원도 같은 판정을 내렸다.","3심 — 대법원은 병원이 일부 잘못 판단했다고 보아 가족이 손해 배상을 받게 했다."],"title":"세 번 재판을 받은 이야기(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#8','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C12',4,'mc','auto','법원이 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X24','SO6-1-u2-X18']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C12","difficulty":4,"kind":"mc","stem":"법원이 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다툼과 갈등의 옳고 그름을 가려 줄 곳이 없어 사회 질서가 흔들린다","correct":true},{"t":"다툼이 저절로 사라진다","mis":"SO6-1-u2-X24"},{"t":"법을 어기는 사람이 없어진다","mis":"SO6-1-u2-X24"},{"t":"나라 살림이 더 잘 운영된다","mis":"SO6-1-u2-X18"}],"explanation":["누가 가려 줄까요?","가릴 곳이 없어요.","질서가 흔들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#9','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',4,'mc','auto','공정한 재판을 위한 세 제도에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X25','SO6-1-u2-X26']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C13","difficulty":4,"kind":"mc","stem":"공정한 재판을 위한 세 제도에 공통으로 담긴 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잘못된 판결로 억울한 사람이 생기지 않도록 재판을 공정하게 하려는 것","correct":true},{"t":"재판을 될 수 있는 대로 빨리 끝내려는 것","mis":"SO6-1-u2-X25"},{"t":"법원의 힘을 다른 기관보다 키우려는 것","mis":"SO6-1-u2-X25"},{"t":"재판 횟수를 늘려 법원을 바쁘게 하려는 것","mis":"SO6-1-u2-X26"}],"explanation":["독립·세 번·공개예요.","모두 공정을 위해서예요.","억울함을 막아요."],"asset":{"type":"passage","lines":["상황 1 — 법관이 바깥의 간섭을 받아 판결을 내린다면?","상황 2 — 단 한 번의 재판으로 판결 내용이 정해진다면?","상황 3 — 재판의 과정과 결과를 모두 감춘다면?"],"title":"공정한 재판을 위협하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L08_challenge#10','soc',6,1,'u2','L08','g6_1_soc_u2_L08_challenge','lesson_challenge','SO6-1-u2-C13',4,'essay','teacher','자료의 세 상황 가운데 하나를 골라 그런 일이 생기면 어떤 문제가 생길지 쓰고, 우리나라가 그 상황을 막으려고 둔 제도를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C13","difficulty":4,"kind":"essay","stem":"자료의 세 상황 가운데 하나를 골라 그런 일이 생기면 어떤 문제가 생길지 쓰고, 우리나라가 그 상황을 막으려고 둔 제도를 쓰세요.","answer_guide":{"answer":"예: 상황 2처럼 단 한 번의 재판으로 판결이 정해진다면, 판결이 잘못되었을 때 바로잡을 길이 없어 억울한 사람이 생길 수 있다. 그래서 우리나라는 하나의 사건에 대해 원칙적으로 세 번까지 재판을 받을 수 있는 삼심 제도를 두었다.","scoring_points":["상황을 하나 골랐는가","생길 문제를 썼는가","그 상황을 막는 제도를 바르게 썼는가"]},"explanation":["상황을 골라요.","문제를 써요.","막는 제도를 써요."],"asset":{"type":"passage","lines":["상황 1 — 법관이 바깥의 간섭을 받아 판결을 내린다면?","상황 2 — 단 한 번의 재판으로 판결 내용이 정해진다면?","상황 3 — 재판의 과정과 결과를 모두 감춘다면?"],"title":"공정한 재판을 위협하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#1','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',1,'mc','auto','국가 권력을 국회, 행정부, 법원이 나눠 맡도록 헌법으로 정해 놓은 것을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X27']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C14","difficulty":1,"kind":"mc","stem":"국가 권력을 국회, 행정부, 법원이 나눠 맡도록 헌법으로 정해 놓은 것을 무엇이라고 하나요?","options":[{"t":"권력 분립","correct":true},{"t":"국민 주권","mis":"SO6-1-u2-X27"},{"t":"선거 원칙","mis":"SO6-1-u2-X27"},{"t":"삼심 제도","mis":"SO6-1-u2-X27"}],"explanation":["권력을 나눠요.","세 기관이 맡아요.","권력 분립이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#2','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',1,'sa','auto','국가 권력을 세 국가기관이 나눠 맡도록 정해 둔, 나라의 가장 기본이 되는 법은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C14","difficulty":1,"kind":"sa","stem":"국가 권력을 세 국가기관이 나눠 맡도록 정해 둔, 나라의 가장 기본이 되는 법은 무엇인가요? 두 글자로 쓰세요.","answer":["헌법"],"explanation":["가장 기본이 되는 법이에요.","◯법이에요.","헌법이에요."],"mis":"SO6-1-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#3','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',1,'ox','auto','권력이 한곳에 모이면 그 권력을 마음대로 사용할 수 있어요.',ARRAY['SO6-1-u2-X27']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C14","difficulty":1,"kind":"ox","stem":"권력이 한곳에 모이면 그 권력을 마음대로 사용할 수 있어요.","answer":"O","reason_options":[{"t":"막을 곳이 없어 잘못된 결정을 내려도 바로잡기 어렵기 때문에","correct":true},{"t":"권력이 모이면 언제나 더 공정해지기 때문에","mis":"SO6-1-u2-X27"}],"mis":"SO6-1-u2-X27","explanation":["막을 곳이 없어요.","마음대로 쓸 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#4','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',1,'mc','auto','권력 분립 모습에서 「법을 만드는 힘」을 맡은 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X27']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C14","difficulty":1,"kind":"mc","stem":"권력 분립 모습에서 「법을 만드는 힘」을 맡은 국가기관은 어디인가요?","options":[{"t":"국회","correct":true},{"t":"행정부","mis":"SO6-1-u2-X18"},{"t":"법원","mis":"SO6-1-u2-X18"},{"t":"시민 단체","mis":"SO6-1-u2-X27"}],"explanation":["법을 만들어요.","국민의 대표가 모여요.","국회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#5','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',2,'mc','auto','만화 속 동물 나라에서 문제가 생긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"mc","stem":"만화 속 동물 나라에서 문제가 생긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모든 힘을 한 자리가 가져 막아 줄 곳이 없었기 때문에","correct":true},{"t":"왕을 동물들이 뽑았기 때문에","mis":"SO6-1-u2-X27"},{"t":"힘을 여러 곳이 나눠 가졌기 때문에","mis":"SO6-1-u2-X27"},{"t":"동물들이 법을 너무 잘 지켰기 때문에","mis":"SO6-1-u2-X27"}],"explanation":["왕이 다 했어요.","막을 곳이 없었어요.","힘이 한곳에 모였어요."],"asset":{"type":"passage","lines":["동물들이 뽑은 왕이 법도 혼자 만들고,","나라 살림도 혼자 맡고, 다툼의 판결도 혼자 내렸다.","왕이 불편한 법을 만들어도 막을 곳이 없었고,","동물들은 자기 권리를 말하지 못했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#6','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',2,'match','auto','자료의 견제 모습과 누가 누구를 견제하는지 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"match","stem":"자료의 견제 모습과 누가 누구를 견제하는지 알맞게 이으세요.","pairs":[{"l":"㉮ 국정 감사","r":"국회 → 행정부"},{"l":"㉯ 법률안 거부권","r":"대통령 → 국회"},{"l":"㉰ 명령 취소 결정","r":"법원 → 행정부"}],"mis":"SO6-1-u2-X28","explanation":["국회가 살펴요.","대통령이 돌려보내요.","법원이 취소해요."],"asset":{"type":"passage","lines":["㉮ 국회는 행정부가 법에 따라 나라 살림을 잘 하는지 확인하려고 국정 감사를 했다.","㉯ 대통령은 국회를 통과한 법률안에 의견이 달라 다시 논의하라며 거부권을 행사했다.","㉰ 법원은 행정부의 명령이 헌법에 어긋난다고 보아 취소하라고 결정했다."],"title":"서로 견제하는 세 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#7','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',2,'blank','auto','권력 분립은 한 국가기관이 나라의 중요한 일을 마음대로 처리할 수 없도록 서로를 견제하고 (    )을 이뤄 내게 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"blank","stem":"권력 분립은 한 국가기관이 나라의 중요한 일을 마음대로 처리할 수 없도록 서로를 견제하고 (    )을 이뤄 내게 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"균형","correct":true},{"t":"경쟁","mis":"SO6-1-u2-X29"},{"t":"명령","mis":"SO6-1-u2-X29"},{"t":"복종","mis":"SO6-1-u2-X29"}],"explanation":["어느 쪽으로도 기울지 않아요.","견제와 함께 써요.","균형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#8','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',2,'mc','auto','국가기관의 권력을 나누는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"mc","stem":"국가기관의 권력을 나누는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 자유와 권리를 보장하기 위해서","correct":true},{"t":"나라의 일을 더 빨리 처리하기 위해서","mis":"SO6-1-u2-X29"},{"t":"한 기관의 힘을 가장 크게 만들기 위해서","mis":"SO6-1-u2-X29"},{"t":"기관끼리 서로 미워하게 하려고","mis":"SO6-1-u2-X29"}],"explanation":["누구를 위해서일까요?","국민을 위해서예요.","자유와 권리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#9','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',2,'ox','auto','국가기관끼리 서로 견제하는 것은 서로를 미워하기 때문이에요.',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"ox","stem":"국가기관끼리 서로 견제하는 것은 서로를 미워하기 때문이에요.","answer":"X","reason_options":[{"t":"견제는 잘못을 서로 바로잡아 권력이 올바르게 쓰이게 하려는 일이기 때문에","correct":true},{"t":"국가기관은 서로 도와서는 안 되기 때문에","mis":"SO6-1-u2-X29"}],"mis":"SO6-1-u2-X29","explanation":["누가 나빠서가 아니에요.","서로 바로잡아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_basic#10','soc',6,1,'u2','L09','g6_1_soc_u2_L09_basic','lesson_basic','SO6-1-u2-C14',3,'error','auto','견제 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X28']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"error","stem":"견제 모습을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉰는 행정부가 법원을 견제하는 모습이야.」","correct":true,"mis_target":"SO6-1-u2-X28"},{"t":"친구 가 — 「㉮는 국회가 행정부를 견제하는 모습이야.」","mis":"SO6-1-u2-X28"},{"t":"친구 다 — 「㉯는 대통령이 국회를 견제하는 모습이야.」","mis":"SO6-1-u2-X28"}],"explanation":["㉰에서 결정한 곳은 어디인가요?","법원이에요.","친구 나가 거꾸로 말했어요."],"asset":{"type":"passage","lines":["㉮ 국회는 행정부가 법에 따라 나라 살림을 잘 하는지 확인하려고 국정 감사를 했다.","㉯ 대통령은 국회를 통과한 법률안에 의견이 달라 다시 논의하라며 거부권을 행사했다.","㉰ 법원은 행정부의 명령이 헌법에 어긋난다고 보아 취소하라고 결정했다."],"title":"서로 견제하는 세 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#1','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',2,'sa','auto','서로 견제하여 어느 한 국가기관으로 치우치지 않는 상태를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"sa","stem":"서로 견제하여 어느 한 국가기관으로 치우치지 않는 상태를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["균형"],"explanation":["기울지 않아요.","◯형이에요.","균형이에요."],"mis":"SO6-1-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#2','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',2,'ox','auto','국가기관의 권력은 국가기관끼리만 견제할 수 있고 국민은 견제할 수 없어요.',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"ox","stem":"국가기관의 권력은 국가기관끼리만 견제할 수 있고 국민은 견제할 수 없어요.","answer":"X","reason_options":[{"t":"국민도 시민 단체 활동이나 의견 올리기, 주민 투표 같은 방법으로 견제할 수 있기 때문에","correct":true},{"t":"국민은 대표를 뽑고 나면 나랏일과 관계없기 때문에","mis":"SO6-1-u2-X29"}],"mis":"SO6-1-u2-X29","explanation":["국민도 지켜봐요.","여러 방법이 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 시민 단체 활동에 참여해 국가기관이 하는 일을 지켜본다.","㉡ 국가기관 누리집 게시판에 의견을 올린다.","㉢ 문제가 있는 지역 대표를 임기 전에 주민 투표로 물러나게 하는 제도를 쓴다."],"title":"국민이 국가기관을 지켜보는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#3','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',3,'mc','auto','만화 속 동물 나라에 권력 분립을 적용한다면 가장 알맞은 모습은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X17']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"만화 속 동물 나라에 권력 분립을 적용한다면 가장 알맞은 모습은 어느 것인가요?","options":[{"t":"법 만들기·나라 살림·판결을 서로 다른 곳이 나눠 맡고 서로 살핀다","correct":true},{"t":"왕에게 힘을 더 모아 준다","mis":"SO6-1-u2-X27"},{"t":"판결만 다른 곳에 맡기고 나머지는 왕이 한다","mis":"SO6-1-u2-X27"},{"t":"왕을 없애고 아무도 나랏일을 맡지 않는다","mis":"SO6-1-u2-X17"}],"explanation":["세 가지 힘이 있어요.","나눠 맡아요.","서로 살펴요."],"asset":{"type":"passage","lines":["동물들이 뽑은 왕이 법도 혼자 만들고,","나라 살림도 혼자 맡고, 다툼의 판결도 혼자 내렸다.","왕이 불편한 법을 만들어도 막을 곳이 없었고,","동물들은 자기 권리를 말하지 못했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#4','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',3,'mc','auto','자료의 ㉯에서 대통령이 법률안을 국회로 돌려보낸 것이 견제가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X20','SO6-1-u2-X29','SO6-1-u2-X28']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"자료의 ㉯에서 대통령이 법률안을 국회로 돌려보낸 것이 견제가 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국회가 법을 마음대로 만들지 못하게 다시 살펴보게 하기 때문에","correct":true},{"t":"대통령이 법을 대신 만들기 때문에","mis":"SO6-1-u2-X20"},{"t":"국회가 없어지게 되기 때문에","mis":"SO6-1-u2-X29"},{"t":"법원이 판결을 바꾸기 때문에","mis":"SO6-1-u2-X28"}],"explanation":["다시 논의하게 해요.","마음대로 못 해요.","그래서 견제예요."],"asset":{"type":"passage","lines":["㉮ 국회는 행정부가 법에 따라 나라 살림을 잘 하는지 확인하려고 국정 감사를 했다.","㉯ 대통령은 국회를 통과한 법률안에 의견이 달라 다시 논의하라며 거부권을 행사했다.","㉰ 법원은 행정부의 명령이 헌법에 어긋난다고 보아 취소하라고 결정했다."],"title":"서로 견제하는 세 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#5','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',3,'mc','auto','권력 분립이 잘 지켜질 때의 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"권력 분립이 잘 지켜질 때의 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 국가기관도 가장 크지 않고 서로 견제하며 균형을 이룬다","correct":true},{"t":"한 국가기관의 힘이 가장 커진다","mis":"SO6-1-u2-X27"},{"t":"국가기관끼리 아무 관계가 없다","mis":"SO6-1-u2-X29"},{"t":"국민은 국가기관을 지켜볼 수 없다","mis":"SO6-1-u2-X29"}],"explanation":["가장 큰 곳이 없어요.","서로 견제해요.","균형을 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#6','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',3,'error','auto','권력 분립을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X29','SO6-1-u2-X27']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"error","stem":"권력 분립을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「권력을 나누는 건 나라의 일을 더 빨리 처리하려는 거야.」","correct":true,"mis_target":"SO6-1-u2-X29"},{"t":"친구 나 — 「한 기관이 마음대로 하지 못하게 하려는 거야.」","mis":"SO6-1-u2-X27"},{"t":"친구 다 — 「국민의 자유와 권리를 지키려는 거야.」","mis":"SO6-1-u2-X29"}],"explanation":["빨리 하려는 것일까요?","마음대로 못 하게 하려는 거예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#7','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',3,'mc','auto','자료의 방법처럼 국민이 국가기관을 지켜보고 견제할 수 있는 바탕으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X29','SO6-1-u2-X04','SO6-1-u2-X28']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"자료의 방법처럼 국민이 국가기관을 지켜보고 견제할 수 있는 바탕으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모든 권력은 국민의 동의를 바탕으로 이루어지기 때문에","correct":true},{"t":"국민이 국가기관보다 힘이 세야 하기 때문에","mis":"SO6-1-u2-X29"},{"t":"지역 대표는 마음대로 일해도 되기 때문에","mis":"SO6-1-u2-X04"},{"t":"국가기관끼리는 견제할 수 없기 때문에","mis":"SO6-1-u2-X28"}],"explanation":["권력은 어디서 나올까요?","국민의 동의예요.","그래서 지켜봐요."],"asset":{"type":"passage","lines":["㉠ 시민 단체 활동에 참여해 국가기관이 하는 일을 지켜본다.","㉡ 국가기관 누리집 게시판에 의견을 올린다.","㉢ 문제가 있는 지역 대표를 임기 전에 주민 투표로 물러나게 하는 제도를 쓴다."],"title":"국민이 국가기관을 지켜보는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#8','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',4,'mc','auto','「법원이 행정부의 명령을 취소하라고 결정했다」는 소식을 권력 분립과 이어 바르게 해석한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X28','SO6-1-u2-X29']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"mc","stem":"「법원이 행정부의 명령을 취소하라고 결정했다」는 소식을 권력 분립과 이어 바르게 해석한 것은 어느 것인가요?","options":[{"t":"법원이 헌법에 어긋난 행정부의 명령을 바로잡아 견제한 것이다","correct":true},{"t":"법원이 행정부의 일을 모두 빼앗은 것이다","mis":"SO6-1-u2-X28"},{"t":"행정부가 법원을 견제한 것이다","mis":"SO6-1-u2-X28"},{"t":"국가기관끼리 다투어 나라가 위험해진 것이다","mis":"SO6-1-u2-X29"}],"explanation":["누가 결정했나요?","법원이에요.","바로잡는 견제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#9','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',4,'mc','auto','국회·행정부·법원과 국민의 관계를 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29','SO6-1-u2-X01']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"mc","stem":"국회·행정부·법원과 국민의 관계를 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"세 기관이 권력을 나눠 맡아 서로 견제하고, 국민은 그 권력이 올바르게 쓰이는지 지켜본다","correct":true},{"t":"세 기관 가운데 하나가 나머지를 다스리고 국민은 따르기만 한다","mis":"SO6-1-u2-X27"},{"t":"세 기관은 서로 관계없이 일하고 국민도 관여하지 않는다","mis":"SO6-1-u2-X29"},{"t":"국민이 세 기관의 일을 모두 직접 맡는다","mis":"SO6-1-u2-X01"}],"explanation":["세 기관이 나눠요.","서로 견제해요.","국민이 지켜봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L09_challenge#10','soc',6,1,'u2','L09','g6_1_soc_u2_L09_challenge','lesson_challenge','SO6-1-u2-C14',4,'essay','teacher','만화 속 동물 나라에서 생긴 문제를 쓰고, 우리나라가 권력을 나눠 맡게 한 방법과 그 까닭을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"essay","stem":"만화 속 동물 나라에서 생긴 문제를 쓰고, 우리나라가 권력을 나눠 맡게 한 방법과 그 까닭을 견주어 쓰세요.","answer_guide":{"answer":"예: 동물 나라에서는 왕 혼자 법을 만들고 나라 살림을 맡고 판결까지 내려, 불편한 법을 만들어도 막을 곳이 없었고 동물들은 권리를 말하지 못했다. 우리나라는 헌법으로 국회는 법을 만들고 행정부는 나라 살림을 맡고 법원은 재판을 하도록 권력을 나누었다. 서로 견제하고 균형을 이루어 한 기관이 마음대로 하지 못하게 하여 국민의 자유와 권리를 보장하기 위해서이다.","scoring_points":["동물 나라의 문제를 썼는가","세 기관이 나눠 맡은 힘을 썼는가","견제와 균형·자유와 권리로 까닭을 썼는가"]},"explanation":["한 자리에 모였어요.","셋으로 나눠요.","자유와 권리를 지켜요."],"asset":{"type":"passage","lines":["동물들이 뽑은 왕이 법도 혼자 만들고,","나라 살림도 혼자 맡고, 다툼의 판결도 혼자 내렸다.","왕이 불편한 법을 만들어도 막을 곳이 없었고,","동물들은 자기 권리를 말하지 못했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#1','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',1,'mc','auto','사람들이 정보를 주고받으며 의사소통하기 위해 사용하는 수단을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"mc","stem":"사람들이 정보를 주고받으며 의사소통하기 위해 사용하는 수단을 무엇이라고 하나요?","options":[{"t":"미디어","correct":true},{"t":"광장","mis":"SO6-1-u2-X30"},{"t":"규칙","mis":"SO6-1-u2-X30"},{"t":"투표","mis":"SO6-1-u2-X30"}],"explanation":["정보를 주고받아요.","의사소통 수단이에요.","미디어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#2','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',1,'sa','auto','종이에 글과 사진을 실어 새로운 정보를 전하는 미디어는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"sa","stem":"종이에 글과 사진을 실어 새로운 정보를 전하는 미디어는 무엇인가요? 두 글자로 쓰세요.","answer":["신문"],"explanation":["글과 사진이에요.","◯문이에요.","신문이에요."],"mis":"SO6-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#3','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',1,'ox','auto','옛사람들은 미디어를 전혀 이용하지 않았어요.',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"ox","stem":"옛사람들은 미디어를 전혀 이용하지 않았어요.","answer":"X","reason_options":[{"t":"벽화, 말을 탄 전달, 새 다리에 묶은 편지처럼 옛사람들도 미디어를 이용했기 때문에","correct":true},{"t":"미디어는 오늘날에 처음 생긴 기계만을 말하기 때문에","mis":"SO6-1-u2-X30"}],"mis":"SO6-1-u2-X30","explanation":["옛날에도 소식을 전했어요.","방법이 달랐을 뿐이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#4','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',1,'mc','auto','영상과 소리 등을 이용해 다양한 정보를 전달하는 미디어는 어느 것인가요?',ARRAY['SO6-1-u2-X31']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"mc","stem":"영상과 소리 등을 이용해 다양한 정보를 전달하는 미디어는 어느 것인가요?","options":[{"t":"방송","correct":true},{"t":"신문","mis":"SO6-1-u2-X31"},{"t":"편지","mis":"SO6-1-u2-X31"},{"t":"벽보","mis":"SO6-1-u2-X31"}],"explanation":["영상과 소리예요.","텔레비전·라디오예요.","방송이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#5','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',2,'mc','auto','세 친구의 이야기에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X31','SO6-1-u2-X30']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"mc","stem":"세 친구의 이야기에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 정보를 서로 다른 미디어로 얻었다","correct":true},{"t":"세 친구 모두 같은 미디어를 이용했다","mis":"SO6-1-u2-X31"},{"t":"정보를 얻는 방법은 하나뿐이다","mis":"SO6-1-u2-X30"},{"t":"대화방은 미디어가 아니다","mis":"SO6-1-u2-X30"}],"explanation":["방송, 신문, 대화방이에요.","내용은 같아요.","미디어가 달라요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"어제 방송 뉴스에서 봤는데, 해로운 성분이 든 학용품이 있대."},{"who":"친구 나","text":"나도 같은 내용을 신문 기사에서 읽었어."},{"who":"친구 다","text":"대화방에 올라온 글에도 조심하라고 쓰여 있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#6','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',2,'match','auto','미디어의 종류와 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"match","stem":"미디어의 종류와 특징을 알맞게 이으세요.","pairs":[{"l":"신문","r":"글과 사진 등으로 새로운 정보를 전해요"},{"l":"방송","r":"영상과 소리 등으로 다양한 정보를 전해요"},{"l":"사회 관계망 서비스","r":"글·음성·영상 등을 주고받으며 의사소통해요"}],"mis":"SO6-1-u2-X31","explanation":["글과 사진이에요.","영상과 소리예요.","주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#7','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',2,'blank','auto','신문과 방송은 많은 사람을 대상으로 정보를 (    ) 전달해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X31']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"blank","stem":"신문과 방송은 많은 사람을 대상으로 정보를 (    ) 전달해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"신속하게","correct":true},{"t":"한 사람에게만","mis":"SO6-1-u2-X31"},{"t":"아주 느리게","mis":"SO6-1-u2-X31"},{"t":"몰래","mis":"SO6-1-u2-X31"}],"explanation":["많은 사람에게 전해요.","빠르게 전해요.","신속하게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#8','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',2,'mc','auto','자료의 세 방법이 모두 미디어라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"mc","stem":"자료의 세 방법이 모두 미디어라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모두 소식과 정보를 주고받는 수단이기 때문에","correct":true},{"t":"모두 종이로 만들었기 때문에","mis":"SO6-1-u2-X30"},{"t":"모두 오늘날에도 똑같이 쓰기 때문에","mis":"SO6-1-u2-X30"},{"t":"모두 기계를 이용했기 때문에","mis":"SO6-1-u2-X30"}],"explanation":["모습은 달라요.","하는 일은 같아요.","정보를 주고받아요."],"asset":{"type":"passage","lines":["㉠ 동굴 벽에 그림을 남겼다.","㉡ 말을 타고 달려가 소식을 직접 전했다.","㉢ 새 다리에 편지를 묶어 날려 보냈다."],"title":"옛사람들이 소식을 전한 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#9','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',2,'ox','auto','자료의 ㉮와 ㉯는 겉모습이 아주 다르지만 둘 다 미디어예요.',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"ox","stem":"자료의 ㉮와 ㉯는 겉모습이 아주 다르지만 둘 다 미디어예요.","answer":"O","reason_options":[{"t":"둘 다 사람들에게 선거와 관련한 정보를 제공하는 수단이기 때문에","correct":true},{"t":"미디어는 겉모습이 같아야 하기 때문에","mis":"SO6-1-u2-X30"}],"mis":"SO6-1-u2-X30","explanation":["종이와 누리집이에요.","둘 다 정보를 전해요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 옛날의 선거 공고문 — 종이에 써서 사람이 많이 모이는 곳에 붙였다.","㉯ 오늘날의 선거 안내 누리집 — 인터넷에서 보고 궁금한 점을 묻고 답한다."],"title":"모습이 다른 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_basic#10','soc',6,1,'u2','L10','g6_1_soc_u2_L10_basic','lesson_basic','SO6-1-u2-C15',3,'error','auto','미디어를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X30','SO6-1-u2-X31']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"error","stem":"미디어를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「종이로 된 것만 미디어라고 할 수 있어.」","correct":true,"mis_target":"SO6-1-u2-X30"},{"t":"친구 가 — 「전화도 정보를 주고받는 미디어야.」","mis":"SO6-1-u2-X30"},{"t":"친구 나 — 「사회 관계망 서비스로 의사소통도 해.」","mis":"SO6-1-u2-X31"}],"explanation":["겉모습으로 정할까요?","정보를 주고받는지가 중요해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#1','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',2,'sa','auto','스마트 기기로 인터넷에서 글, 음성, 영상 등을 주고받으며 의사소통하는 미디어는 「○○ 관계망 서비스」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"sa","stem":"스마트 기기로 인터넷에서 글, 음성, 영상 등을 주고받으며 의사소통하는 미디어는 「○○ 관계망 서비스」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["사회"],"explanation":["여러 사람이 이어져요.","◯회예요.","사회예요."],"mis":"SO6-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#2','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',2,'ox','auto','신문과 방송은 적은 사람에게만 천천히 정보를 전달해요.',ARRAY['SO6-1-u2-X31']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"ox","stem":"신문과 방송은 적은 사람에게만 천천히 정보를 전달해요.","answer":"X","reason_options":[{"t":"신문과 방송은 많은 사람을 대상으로 정보를 신속하게 전하기 때문에","correct":true},{"t":"신문과 방송은 한 사람씩 찾아가 전하기 때문에","mis":"SO6-1-u2-X31"}],"mis":"SO6-1-u2-X31","explanation":["많은 사람에게예요.","신속하게예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#3','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',3,'mc','auto','자료의 ㉮와 ㉯가 미디어인지 정하는 잣대로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"mc","stem":"자료의 ㉮와 ㉯가 미디어인지 정하는 잣대로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 정보를 주고받는 수단인가","correct":true},{"t":"종이로 만들었는가","mis":"SO6-1-u2-X30"},{"t":"요즘 쓰는 것인가","mis":"SO6-1-u2-X30"},{"t":"벽에 걸어 두는가","mis":"SO6-1-u2-X30"}],"explanation":["겉모습이 아니에요.","하는 일을 봐요.","정보를 주고받는지예요."],"asset":{"type":"passage","lines":["㉮ 옛날의 선거 공고문 — 종이에 써서 사람이 많이 모이는 곳에 붙였다.","㉯ 오늘날의 선거 안내 누리집 — 인터넷에서 보고 궁금한 점을 묻고 답한다."],"title":"모습이 다른 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#4','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',3,'mc','auto','자료의 ㉮와 ㉯를 견줄 때 「종이인가」라는 잣대를 걷어 내야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"mc","stem":"자료의 ㉮와 ㉯를 견줄 때 「종이인가」라는 잣대를 걷어 내야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"종이인지 아닌지는 정보를 주고받는 수단인지와 관계없기 때문에","correct":true},{"t":"종이로 된 것은 미디어가 아니기 때문에","mis":"SO6-1-u2-X30"},{"t":"㉯도 종이로 만들었기 때문에","mis":"SO6-1-u2-X30"},{"t":"잣대는 많을수록 좋기 때문에","mis":"SO6-1-u2-X30"}],"explanation":["겉모습을 재는 잣대예요.","미디어를 정하지 못해요.","그래서 걷어 내요."],"asset":{"type":"passage","lines":["㉮ 옛날의 선거 공고문 — 종이에 써서 사람이 많이 모이는 곳에 붙였다.","㉯ 오늘날의 선거 안내 누리집 — 인터넷에서 보고 궁금한 점을 묻고 답한다."],"title":"모습이 다른 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#5','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',3,'mc','auto','상황에 맞게 미디어를 고른 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X31']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"mc","stem":"상황에 맞게 미디어를 고른 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"먼 곳에 사는 할머니께 안부를 여쭐 때 전화를 이용한다","correct":true},{"t":"많은 사람에게 급한 소식을 알릴 때 쪽지 한 장만 쓴다","mis":"SO6-1-u2-X31"},{"t":"영상으로 운동 방법을 보고 싶을 때 신문을 펼친다","mis":"SO6-1-u2-X31"},{"t":"친구와 바로 의견을 나눌 때 벽화를 그린다","mis":"SO6-1-u2-X31"}],"explanation":["상황에 따라 골라요.","멀리 있는 사람과 이야기해요.","전화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#6','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',3,'error','auto','미디어 종류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X31','SO6-1-u2-X30']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"error","stem":"미디어 종류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「방송은 글로만 정보를 전해.」","correct":true,"mis_target":"SO6-1-u2-X31"},{"t":"친구 가 — 「신문은 글과 사진으로 새 정보를 전해.」","mis":"SO6-1-u2-X31"},{"t":"친구 다 — 「책도 정보를 전하는 미디어야.」","mis":"SO6-1-u2-X30"}],"explanation":["방송은 무엇으로 전하나요?","영상과 소리예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#7','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',3,'ox','auto','「미디어」는 많은 사람이 모이는 장소를 가리키는 말이에요.',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C15","difficulty":3,"kind":"ox","stem":"「미디어」는 많은 사람이 모이는 장소를 가리키는 말이에요.","answer":"X","reason_options":[{"t":"미디어는 정보를 주고받으며 의사소통하기 위해 사용하는 수단이기 때문에","correct":true},{"t":"사람이 모이는 곳에서만 정보를 주고받기 때문에","mis":"SO6-1-u2-X30"}],"mis":"SO6-1-u2-X30","explanation":["장소가 아니에요.","수단이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#8','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',4,'mc','auto','옛날부터 오늘날까지 미디어의 모습을 견주어 내린 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X30','SO6-1-u2-X31']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C15","difficulty":4,"kind":"mc","stem":"옛날부터 오늘날까지 미디어의 모습을 견주어 내린 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모습은 달라졌어도 정보를 주고받는 수단이라는 점은 같다","correct":true},{"t":"옛날의 것은 미디어가 아니었다","mis":"SO6-1-u2-X30"},{"t":"오늘날의 미디어는 정보를 주고받지 않는다","mis":"SO6-1-u2-X30"},{"t":"미디어는 한 가지 종류만 있다","mis":"SO6-1-u2-X31"}],"explanation":["모습이 달라졌어요.","하는 일은 같아요.","정보를 주고받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#9','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',4,'mc','auto','세 친구처럼 여러 미디어로 같은 소식을 접할 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X31','SO6-1-u2-X30']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C15","difficulty":4,"kind":"mc","stem":"세 친구처럼 여러 미디어로 같은 소식을 접할 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들은 상황에 따라 다양한 미디어를 이용해 정보를 주고받는다","correct":true},{"t":"한 가지 미디어만 이용해야 한다","mis":"SO6-1-u2-X31"},{"t":"대화방은 의사소통 수단이 아니다","mis":"SO6-1-u2-X30"},{"t":"미디어는 옛날에만 쓰였다","mis":"SO6-1-u2-X30"}],"explanation":["여러 미디어예요.","상황에 따라 골라요.","다양하게 이용해요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"어제 방송 뉴스에서 봤는데, 해로운 성분이 든 학용품이 있대."},{"who":"친구 나","text":"나도 같은 내용을 신문 기사에서 읽었어."},{"who":"친구 다","text":"대화방에 올라온 글에도 조심하라고 쓰여 있었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L10_challenge#10','soc',6,1,'u2','L10','g6_1_soc_u2_L10_challenge','lesson_challenge','SO6-1-u2-C15',4,'essay','teacher','생활 속에서 미디어를 이용한 경험 하나를 쓰고, 그것이 미디어라고 할 수 있는 까닭을 미디어의 뜻과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C15","difficulty":4,"kind":"essay","stem":"생활 속에서 미디어를 이용한 경험 하나를 쓰고, 그것이 미디어라고 할 수 있는 까닭을 미디어의 뜻과 이어 쓰세요.","answer_guide":{"answer":"예: 나는 날씨 예보 방송을 보고 다가올 일주일 날씨에 관한 정보를 얻었다. 방송은 영상과 소리로 많은 사람에게 정보를 신속하게 전하는 수단이다. 미디어는 사람들이 정보를 주고받으며 의사소통하기 위해 사용하는 수단이므로 방송은 미디어라고 할 수 있다.","scoring_points":["미디어를 이용한 경험을 썼는가","주고받은 정보를 썼는가","미디어의 뜻과 이어 까닭을 썼는가"]},"explanation":["경험을 떠올려요.","어떤 정보였나요?","미디어의 뜻과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#1','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',1,'mc','auto','미디어가 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전하는 것은 어떤 역할인가요?',ARRAY['SO6-1-u2-X32','SO6-1-u2-X33']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"mc","stem":"미디어가 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전하는 것은 어떤 역할인가요?","options":[{"t":"새로운 사실 전달","correct":true},{"t":"가치나 규범 제시","mis":"SO6-1-u2-X32"},{"t":"사회문제의 해결 방안 제시","mis":"SO6-1-u2-X32"},{"t":"정보를 감추는 일","mis":"SO6-1-u2-X33"}],"explanation":["새로운 사실이에요.","신속하게 전해요.","새로운 사실 전달이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#2','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',1,'sa','auto','개인이 글, 사진, 영상 등을 만들어 미디어로 다른 사람들과 나누는 것을 무엇이라고 하나요? 「○인 미디어」처럼 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"sa","stem":"개인이 글, 사진, 영상 등을 만들어 미디어로 다른 사람들과 나누는 것을 무엇이라고 하나요? 「○인 미디어」처럼 다섯 글자로 쓰세요.","answer":["1인 미디어","1인미디어"],"explanation":["개인이 만들어요.","한 사람이에요.","1인 미디어예요."],"mis":"SO6-1-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#3','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',1,'ox','auto','미디어로 전달되는 정보에는 사회에서 중요하게 여기는 가치나 규범이 담겨 있기도 해요.',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"ox","stem":"미디어로 전달되는 정보에는 사회에서 중요하게 여기는 가치나 규범이 담겨 있기도 해요.","answer":"O","reason_options":[{"t":"사람들이 그 정보를 보며 중요한 가치를 알고 존중하는 태도를 기르기 때문에","correct":true},{"t":"미디어는 사실만 전하고 생각은 담지 않기 때문에","mis":"SO6-1-u2-X32"}],"mis":"SO6-1-u2-X32","explanation":["가치가 담겨요.","존중하는 태도를 길러요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#4','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',1,'mc','auto','미디어를 이용하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"mc","stem":"미디어를 이용하면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"많은 사람에게 같은 내용의 정보를 한꺼번에 전할 수 있다","correct":true},{"t":"한 사람에게만 정보를 전할 수 있다","mis":"SO6-1-u2-X33"},{"t":"정보를 주고받지 못하게 막을 수 있다","mis":"SO6-1-u2-X33"},{"t":"옛날 일만 알 수 있다","mis":"SO6-1-u2-X32"}],"explanation":["많은 사람에게 전해요.","한꺼번에 전해요.","같은 정보를 함께 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#5','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',2,'match','auto','자료와 그 자료가 보여 주는 미디어의 역할을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"match","stem":"자료와 그 자료가 보여 주는 미디어의 역할을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"새로운 사실을 신속하게 전해요"},{"l":"㉡","r":"가치나 규범을 보여 줘요"},{"l":"㉢","r":"사회문제와 해결 방안을 제시해요"}],"mis":"SO6-1-u2-X32","explanation":["새 소식이에요.","바른 말을 권해요.","문제와 해결이에요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#6','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',2,'mc','auto','자료 가운데 가치나 규범을 보여 주는 역할을 하는 것끼리 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"mc","stem":"자료 가운데 가치나 규범을 보여 주는 역할을 하는 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"㉡, ㉣","correct":true},{"t":"㉠, ㉤","mis":"SO6-1-u2-X32"},{"t":"㉢, ㉥","mis":"SO6-1-u2-X32"},{"t":"㉠, ㉢","mis":"SO6-1-u2-X32"}],"explanation":["바른 말을 권해요.","이해와 존중이에요.","㉡, ㉣이에요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#7','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',2,'blank','auto','미디어를 이용해 주고받는 여러 정보와 사람들의 생각은 사회문제에 관한 (    )을 하는 데 영향을 미쳐요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"blank","stem":"미디어를 이용해 주고받는 여러 정보와 사람들의 생각은 사회문제에 관한 (    )을 하는 데 영향을 미쳐요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"의사 결정","correct":true},{"t":"물건 계산","mis":"SO6-1-u2-X33"},{"t":"날씨 예보","mis":"SO6-1-u2-X33"},{"t":"건물 공사","mis":"SO6-1-u2-X33"}],"explanation":["함께 정하는 일이에요.","사회문제를 해결해요.","의사 결정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#8','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',2,'mc','auto','자료의 글이 보여 주는 미디어의 역할로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X32','SO6-1-u2-X33']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"mc","stem":"자료의 글이 보여 주는 미디어의 역할로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사회문제를 지목하고 해결 방안을 제시한다","correct":true},{"t":"옛날의 모습만 전한다","mis":"SO6-1-u2-X32"},{"t":"가치나 규범만 제시한다","mis":"SO6-1-u2-X32"},{"t":"사람들이 생각을 나누지 못하게 한다","mis":"SO6-1-u2-X33"}],"explanation":["문제를 짚었어요.","해결 방법을 냈어요.","사회문제를 다뤄요."],"asset":{"type":"passage","lines":["문제 — 논밭을 없애고 산의 나무를 베어 태양광 발전 시설을 세웠다.","해결 방법 — 도시의 건물 지붕과 주차장에 태양광 패널을 달자.","댓글 — 「좋은 생각이에요.」 「설치 비용은 어떻게 하죠?」 「다른 방법도 찾아봐요.」"],"title":"어느 글과 댓글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#9','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',2,'ox','auto','자료의 댓글처럼 사람들은 미디어로 서로 다른 생각을 나누며 사회문제를 여러 관점에서 이해하기도 해요.',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"ox","stem":"자료의 댓글처럼 사람들은 미디어로 서로 다른 생각을 나누며 사회문제를 여러 관점에서 이해하기도 해요.","answer":"O","reason_options":[{"t":"미디어로 생각을 주고받으며 해결책을 함께 찾기 때문에","correct":true},{"t":"미디어에서는 한 가지 생각만 나눌 수 있기 때문에","mis":"SO6-1-u2-X33"}],"mis":"SO6-1-u2-X33","explanation":["댓글이 여럿이에요.","생각이 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["문제 — 논밭을 없애고 산의 나무를 베어 태양광 발전 시설을 세웠다.","해결 방법 — 도시의 건물 지붕과 주차장에 태양광 패널을 달자.","댓글 — 「좋은 생각이에요.」 「설치 비용은 어떻게 하죠?」 「다른 방법도 찾아봐요.」"],"title":"어느 글과 댓글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_basic#10','soc',6,1,'u2','L11','g6_1_soc_u2_L11_basic','lesson_basic','SO6-1-u2-C16',3,'error','auto','미디어의 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"error","stem":"미디어의 역할을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「1인 미디어가 늘면서 정보를 만드는 사람은 오히려 줄었어.」","correct":true,"mis_target":"SO6-1-u2-X33"},{"t":"친구 나 — 「이제는 누구나 정보를 만드는 사람이 될 수 있어.」","mis":"SO6-1-u2-X33"},{"t":"친구 다 — 「미디어는 새로운 사실을 신속하게 전해.」","mis":"SO6-1-u2-X32"}],"explanation":["1인 미디어가 늘었어요.","만드는 사람도 늘었어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#1','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',2,'sa','auto','사물이나 현상을 관찰할 때 그 사람이 보고 생각하는 태도나 방향 또는 처지를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"sa","stem":"사물이나 현상을 관찰할 때 그 사람이 보고 생각하는 태도나 방향 또는 처지를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["관점"],"explanation":["보는 자리예요.","관◯이에요.","관점이에요."],"mis":"SO6-1-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#2','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',2,'ox','auto','자료의 ㉤과 ㉥은 모두 돌고래 이야기라서 미디어의 같은 역할만 보여 줘요.',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"ox","stem":"자료의 ㉤과 ㉥은 모두 돌고래 이야기라서 미디어의 같은 역할만 보여 줘요.","answer":"X","reason_options":[{"t":"㉤은 새로 정해진 사실을 전하고 ㉥은 문제와 그 해결 과정을 보여 줘 역할이 다르기 때문에","correct":true},{"t":"같은 대상을 다루면 역할도 늘 같기 때문에","mis":"SO6-1-u2-X32"}],"mis":"SO6-1-u2-X32","explanation":["같은 대상이에요.","전하는 것이 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#3','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',3,'mc','auto','자료의 두 소식을 읽은 사람들에게 생길 영향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"mc","stem":"자료의 두 소식을 읽은 사람들에게 생길 영향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"방치된 킥보드를 옮겨 달라는 신고가 늘고, 더 안전한 환경을 바라는 목소리가 커진다","correct":true},{"t":"사람들이 킥보드 문제에 관심을 끊는다","mis":"SO6-1-u2-X33"},{"t":"아무 영향도 생기지 않는다","mis":"SO6-1-u2-X33"},{"t":"소식을 읽은 한 사람만 알게 된다","mis":"SO6-1-u2-X33"}],"explanation":["많은 사람이 알게 돼요.","신고가 늘어요.","더 안전해지길 바라요."],"asset":{"type":"passage","lines":["소식 ㉮ — 보호 구역에 방치된 전동 킥보드를 발견 즉시 옮기고 신고를 받는다.","소식 ㉯ — 킥보드를 함부로 세워 두지 못하게 하는 법을 만들어 달라는 요구가 커진다."],"title":"미디어가 전한 두 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#4','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',3,'mc','auto','민주주의에서 미디어가 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"mc","stem":"민주주의에서 미디어가 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주고받는 정보와 사람들의 생각이 사회문제에 관한 의사 결정에 영향을 미치기 때문에","correct":true},{"t":"미디어가 사람들의 생각을 하나로 정해 주기 때문에","mis":"SO6-1-u2-X33"},{"t":"미디어가 모든 일을 대신 처리해 주기 때문에","mis":"SO6-1-u2-X33"},{"t":"미디어가 정보를 감춰 주기 때문에","mis":"SO6-1-u2-X33"}],"explanation":["정보가 오가요.","생각이 모여요.","결정에 영향을 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#5','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',3,'mc','auto','자료를 미디어의 역할에 따라 모두 나눈 것으로 바른 것은 어느 것인가요?',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"mc","stem":"자료를 미디어의 역할에 따라 모두 나눈 것으로 바른 것은 어느 것인가요?","options":[{"t":"새로운 사실 — ㉠㉤ · 가치나 규범 — ㉡㉣ · 사회문제와 해결 — ㉢㉥","correct":true},{"t":"새로운 사실 — ㉡㉣ · 가치나 규범 — ㉠㉤ · 사회문제와 해결 — ㉢㉥","mis":"SO6-1-u2-X32"},{"t":"새로운 사실 — ㉢㉥ · 가치나 규범 — ㉡㉣ · 사회문제와 해결 — ㉠㉤","mis":"SO6-1-u2-X32"},{"t":"새로운 사실 — ㉠㉡ · 가치나 규범 — ㉢㉣ · 사회문제와 해결 — ㉤㉥","mis":"SO6-1-u2-X32"}],"explanation":["새 소식은 ㉠㉤이에요.","가치는 ㉡㉣이에요.","문제와 해결은 ㉢㉥이에요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#6','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',3,'error','auto','자료를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"error","stem":"자료를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉣은 새로 정해진 규칙을 알리는 소식이야.」","correct":true,"mis_target":"SO6-1-u2-X32"},{"t":"친구 가 — 「㉡은 바른 말을 쓰자는 가치를 보여 줘.」","mis":"SO6-1-u2-X32"},{"t":"친구 나 — 「㉢은 문제를 짚고 해결 방법을 내놓았어.」","mis":"SO6-1-u2-X32"}],"explanation":["㉣은 무엇을 돕나요?","이해와 존중이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#7','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',3,'ox','auto','민주주의에서 미디어를 「파수꾼」에 빗대는 것은 미디어가 사회문제를 지켜보고 알리기 때문이에요.',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"ox","stem":"민주주의에서 미디어를 「파수꾼」에 빗대는 것은 미디어가 사회문제를 지켜보고 알리기 때문이에요.","answer":"O","reason_options":[{"t":"파수꾼처럼 사회를 지켜보다가 문제를 알려 사람들이 생각을 모으게 하기 때문에","correct":true},{"t":"파수꾼처럼 사람들이 정보를 보지 못하게 막기 때문에","mis":"SO6-1-u2-X33"}],"mis":"SO6-1-u2-X33","explanation":["파수꾼은 지켜봐요.","문제를 알려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#8','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',4,'mc','auto','자료의 글과 댓글이 오가는 모습을 민주주의와 이어 해석한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C16","difficulty":4,"kind":"mc","stem":"자료의 글과 댓글이 오가는 모습을 민주주의와 이어 해석한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"여러 사람이 미디어로 생각을 나누며 더 나은 해결 방법을 함께 찾아 간다","correct":true},{"t":"글쓴이의 생각만 옳으므로 댓글은 필요 없다","mis":"SO6-1-u2-X33"},{"t":"생각이 다르면 미디어를 쓰지 말아야 한다","mis":"SO6-1-u2-X33"},{"t":"댓글은 사회문제와 아무 관계가 없다","mis":"SO6-1-u2-X32"}],"explanation":["생각이 달라요.","함께 나눠요.","해결 방법을 찾아요."],"asset":{"type":"passage","lines":["문제 — 논밭을 없애고 산의 나무를 베어 태양광 발전 시설을 세웠다.","해결 방법 — 도시의 건물 지붕과 주차장에 태양광 패널을 달자.","댓글 — 「좋은 생각이에요.」 「설치 비용은 어떻게 하죠?」 「다른 방법도 찾아봐요.」"],"title":"어느 글과 댓글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#9','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',4,'mc','auto','민주주의에서 미디어의 역할을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C16","difficulty":4,"kind":"mc","stem":"민주주의에서 미디어의 역할을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"중요한 사실을 알리고 가치를 보여 주며 사회문제를 짚어 사람들의 생각을 모은다","correct":true},{"t":"정보를 감추어 사람들이 결정하지 못하게 한다","mis":"SO6-1-u2-X33"},{"t":"새로운 사실만 전하고 생각은 나누지 않게 한다","mis":"SO6-1-u2-X32"},{"t":"미디어를 만든 사람만 정보를 얻게 한다","mis":"SO6-1-u2-X33"}],"explanation":["사실·가치·문제예요.","생각을 모아요.","결정을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L11_challenge#10','soc',6,1,'u2','L11','g6_1_soc_u2_L11_challenge','lesson_challenge','SO6-1-u2-C16',4,'essay','teacher','자료 가운데 두 가지를 골라 각각 미디어의 어떤 역할을 보여 주는지 쓰고, 민주주의에서 미디어가 중요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C16","difficulty":4,"kind":"essay","stem":"자료 가운데 두 가지를 골라 각각 미디어의 어떤 역할을 보여 주는지 쓰고, 민주주의에서 미디어가 중요한 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠은 방치된 킥보드를 곧바로 옮긴다는 새 소식이라 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전하는 역할을 보여 준다. ㉢은 태양광 시설의 문제를 짚고 해결 방법을 알려 사회문제를 지목하고 해결 방안을 제시하는 역할을 보여 준다. 미디어로 주고받는 정보와 사람들의 생각은 사회문제에 관한 의사 결정에 영향을 미치므로 민주주의에서 미디어가 중요하다.","scoring_points":["자료 두 가지를 골랐는가","각 자료의 역할을 바르게 썼는가","의사 결정과 이어 중요한 까닭을 썼는가"]},"explanation":["두 자료를 골라요.","역할을 써요.","결정과 이어요."],"asset":{"type":"passage","lines":["㉠ 보호 구역에 방치된 전동 킥보드를 곧바로 옮긴다는 새 소식","㉡ 편견과 차별이 없는 말을 쓰자고 권하는 텔레비전 프로그램","㉢ 논밭과 산에 세운 태양광 시설의 문제와 해결 방법을 알린 글","㉣ 발달 장애 아동을 이해하도록 돕는 어린이 프로그램 기사","㉤ 새 돌고래를 수족관에 들일 수 없게 됐다는 소식","㉥ 돌고래가 바다로 돌아가기까지를 담은 방송"],"title":"미디어 자료 여섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#1','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',1,'mc','auto','사실과 다른 내용을 진짜처럼 꾸며서 전달하는 정보를 무엇이라고 하나요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"mc","stem":"사실과 다른 내용을 진짜처럼 꾸며서 전달하는 정보를 무엇이라고 하나요?","options":[{"t":"허위 조작 정보","correct":true},{"t":"여론","mis":"SO6-1-u2-X34"},{"t":"관점","mis":"SO6-1-u2-X34"},{"t":"가치나 규범","mis":"SO6-1-u2-X34"}],"explanation":["사실과 달라요.","진짜처럼 꾸며요.","허위 조작 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#2','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',1,'sa','auto','많은 사람이 갖고 있는 공통된 의견을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"sa","stem":"많은 사람이 갖고 있는 공통된 의견을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["여론"],"explanation":["많은 사람의 의견이에요.","◯론이에요.","여론이에요."],"mis":"SO6-1-u2-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#3','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',1,'ox','auto','사람들이 주고받는 정보에는 언제나 사실만 담겨 있어요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"ox","stem":"사람들이 주고받는 정보에는 언제나 사실만 담겨 있어요.","answer":"X","reason_options":[{"t":"사실과 다른 정보가 섞여 있어 피해를 보기도 하기 때문에","correct":true},{"t":"미디어로 전하는 정보는 모두 확인을 거치기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["사실과 다른 정보도 있어요.","피해를 보기도 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#4','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',1,'mc','auto','사실을 전하는 뉴스처럼 보이지만 거짓이거나 사실을 잘못 해석한 내용을 담은 정보를 가리키는 말은 무엇인가요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"mc","stem":"사실을 전하는 뉴스처럼 보이지만 거짓이거나 사실을 잘못 해석한 내용을 담은 정보를 가리키는 말은 무엇인가요?","options":[{"t":"가짜 뉴스","correct":true},{"t":"일기","mis":"SO6-1-u2-X34"},{"t":"편지","mis":"SO6-1-u2-X34"},{"t":"여론","mis":"SO6-1-u2-X34"}],"explanation":["뉴스처럼 보여요.","내용은 거짓이에요.","가짜 뉴스예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#5','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',2,'mc','auto','만화 속 친구가 억울해한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X35','SO6-1-u2-X34']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"mc","stem":"만화 속 친구가 억울해한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사실이 아닌 글 때문에 친구들이 잘못 판단해 회장으로 뽑히지 못했기 때문에","correct":true},{"t":"글이 너무 늦게 올라왔기 때문에","mis":"SO6-1-u2-X35"},{"t":"친구들이 글을 읽지 않았기 때문에","mis":"SO6-1-u2-X34"},{"t":"회장 선거가 없어졌기 때문에","mis":"SO6-1-u2-X35"}],"explanation":["글이 사실이 아니었어요.","친구들이 잘못 판단했어요.","뽑히지 못했어요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#6','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',2,'mc','auto','만화에서 글이 사실이 아니라고 밝혀진 뒤에도 그대로 남은 것은 무엇인가요?',ARRAY['SO6-1-u2-X35']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"mc","stem":"만화에서 글이 사실이 아니라고 밝혀진 뒤에도 그대로 남은 것은 무엇인가요?","options":[{"t":"그 글을 믿고 이미 내린 결정","correct":true},{"t":"대화방에 올라온 그 글","mis":"SO6-1-u2-X35"},{"t":"글을 믿었던 마음 전부","mis":"SO6-1-u2-X35"},{"t":"아무것도 남지 않았다","mis":"SO6-1-u2-X35"}],"explanation":["글은 지울 수 있어요.","결정은 이미 내려졌어요.","결정이 남아요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#7','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',2,'blank','auto','허위 조작 정보로 잘못된 여론이 만들어지면 합리적인 (    )을 방해해 민주주의를 위협할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"blank","stem":"허위 조작 정보로 잘못된 여론이 만들어지면 합리적인 (    )을 방해해 민주주의를 위협할 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"의사 결정","correct":true},{"t":"장보기","mis":"SO6-1-u2-X34"},{"t":"숙제 검사","mis":"SO6-1-u2-X34"},{"t":"날씨 예보","mis":"SO6-1-u2-X34"}],"explanation":["함께 정하는 일이에요.","합리적이어야 해요.","의사 결정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#8','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',2,'match','auto','미디어와 관련한 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"match","stem":"미디어와 관련한 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"허위 조작 정보","r":"사실과 다른 내용을 진짜처럼 꾸며 전하는 정보"},{"l":"가짜 뉴스","r":"뉴스처럼 보이지만 거짓이거나 잘못 해석한 정보"},{"l":"여론","r":"많은 사람이 갖고 있는 공통된 의견"}],"mis":"SO6-1-u2-X34","explanation":["꾸민 정보예요.","뉴스를 흉내 내요.","공통된 의견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#9','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',2,'ox','auto','카드처럼 사실과 다른 정보는 일부러 만들기도 하지만, 사실을 정확히 확인하지 않아서 생기기도 해요.',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"ox","stem":"카드처럼 사실과 다른 정보는 일부러 만들기도 하지만, 사실을 정확히 확인하지 않아서 생기기도 해요.","answer":"O","reason_options":[{"t":"㉠처럼 확인하지 않고 옮길 때도 사실과 다른 정보가 생기기 때문에","correct":true},{"t":"사실과 다른 정보는 언제나 일부러 만들 때만 생기기 때문에","mis":"SO6-1-u2-X34"}],"mis":"SO6-1-u2-X34","explanation":["㉠을 보세요.","확인하지 않아도 생겨요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 사실을 정확하게 확인하지 않고 옮겨서","㉡ 사람들의 관심을 끌려고","㉢ 자신이 지지하는 쪽의 당선을 도우려고","㉣ 조회 수를 높여 더 큰 이익을 얻으려고"],"title":"사실과 다른 정보가 생기는 까닭 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_basic#10','soc',6,1,'u2','L12','g6_1_soc_u2_L12_basic','lesson_basic','SO6-1-u2-C17',3,'error','auto','미디어를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X36','SO6-1-u2-X37']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"error","stem":"미디어를 대하는 태도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「허위 조작 정보가 있으니 미디어는 아예 쓰지 말자.」","correct":true,"mis_target":"SO6-1-u2-X36"},{"t":"친구 가 — 「내용이 사실인지 따져 보고 이용하자.」","mis":"SO6-1-u2-X36"},{"t":"친구 다 — 「자극적인 동영상은 경계하자.」","mis":"SO6-1-u2-X37"}],"explanation":["미디어는 필요한 정보도 전해요.","따져 보고 이용해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#1','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',2,'sa','auto','미디어의 내용을 있는 그대로 믿지 않고 옳고 그름을 따져 분석하는 태도를 「○○○으로 분석하는 태도」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"sa","stem":"미디어의 내용을 있는 그대로 믿지 않고 옳고 그름을 따져 분석하는 태도를 「○○○으로 분석하는 태도」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["비판적"],"explanation":["따져 보는 태도예요.","비◯◯이에요.","비판적이에요."],"mis":"SO6-1-u2-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#2','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',2,'ox','auto','만화에서 글이 사실이 아니라고 밝혀지자 회장 선거 결과도 저절로 바뀌었어요.',ARRAY['SO6-1-u2-X35']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"ox","stem":"만화에서 글이 사실이 아니라고 밝혀지자 회장 선거 결과도 저절로 바뀌었어요.","answer":"X","reason_options":[{"t":"사실이 아니라고 밝혀져도 그 글을 믿고 이미 정한 일은 되돌아오지 않기 때문에","correct":true},{"t":"사실이 밝혀지면 모든 결과가 처음으로 돌아가기 때문에","mis":"SO6-1-u2-X35"}],"mis":"SO6-1-u2-X35","explanation":["결과는 그대로였어요.","이미 정했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#3','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',3,'mc','auto','자료의 일에서 그때 사람들에게 필요했던 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X34','SO6-1-u2-X36']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"mc","stem":"자료의 일에서 그때 사람들에게 필요했던 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신문에 실린 소식이라도 사실인지 거짓인지 따져 보는 태도","correct":true},{"t":"신문에 실렸으니 그대로 믿는 태도","mis":"SO6-1-u2-X37"},{"t":"소문을 더 빨리 퍼뜨리는 태도","mis":"SO6-1-u2-X34"},{"t":"신문을 아예 읽지 않는 태도","mis":"SO6-1-u2-X36"}],"explanation":["소문이 실렸어요.","확인하지 않았어요.","따져 봐야 했어요."],"asset":{"type":"passage","lines":["아주 오래전 큰 지진이 나 많은 사람이 어려움을 겪었다.","그때 근거 없는 소문이 돌았는데, 한 신문이 사실을 확인하지 않고 그대로 실었다.","그 결과 아무 잘못 없는 사람들이 억울하게 큰 피해를 입었다."],"title":"오래전에 있었던 일(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#4','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',3,'mc','auto','자료에서 신문이 기사를 쓸 때 했어야 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X34','SO6-1-u2-X38']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"mc","stem":"자료에서 신문이 기사를 쓸 때 했어야 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"소문을 싣기 전에 사실인지 반드시 확인한다","correct":true},{"t":"소문을 더 자극적으로 꾸민다","mis":"SO6-1-u2-X34"},{"t":"읽는 사람이 좋아할 내용만 싣는다","mis":"SO6-1-u2-X38"},{"t":"소문을 가장 먼저 싣는다","mis":"SO6-1-u2-X34"}],"explanation":["근거 없는 소문이었어요.","확인이 먼저예요.","사실인지 확인해요."],"asset":{"type":"passage","lines":["아주 오래전 큰 지진이 나 많은 사람이 어려움을 겪었다.","그때 근거 없는 소문이 돌았는데, 한 신문이 사실을 확인하지 않고 그대로 실었다.","그 결과 아무 잘못 없는 사람들이 억울하게 큰 피해를 입었다."],"title":"오래전에 있었던 일(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#5','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',3,'mc','auto','만화의 일을 되돌아볼 때 피해를 막을 수 있었던 때로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X35','SO6-1-u2-X34']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"mc","stem":"만화의 일을 되돌아볼 때 피해를 막을 수 있었던 때로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"글을 믿고 투표하기 전에 사실인지 확인했을 때","correct":true},{"t":"투표가 끝난 뒤 글을 지웠을 때","mis":"SO6-1-u2-X35"},{"t":"글을 더 많은 사람에게 보냈을 때","mis":"SO6-1-u2-X34"},{"t":"언제 확인하든 결과는 같다","mis":"SO6-1-u2-X35"}],"explanation":["결정한 뒤에는 남아요.","결정하기 전이 중요해요.","미리 확인해요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#6','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',3,'error','auto','사실과 다른 정보가 생기는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"error","stem":"사실과 다른 정보가 생기는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「사실을 여러 번 확인해 정확하게 알리려다 생기는 거야.」","correct":true,"mis_target":"SO6-1-u2-X34"},{"t":"친구 가 — 「사람들의 관심을 끌려고 만들기도 해.」","mis":"SO6-1-u2-X34"},{"t":"친구 나 — 「조회 수를 높여 이익을 얻으려고 올리기도 해.」","mis":"SO6-1-u2-X34"}],"explanation":["여러 번 확인하면 어떻게 될까요?","오히려 줄어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 사실을 정확하게 확인하지 않고 옮겨서","㉡ 사람들의 관심을 끌려고","㉢ 자신이 지지하는 쪽의 당선을 도우려고","㉣ 조회 수를 높여 더 큰 이익을 얻으려고"],"title":"사실과 다른 정보가 생기는 까닭 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#7','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',3,'ox','auto','조회 수를 높이려고 올린 자극적인 동영상을 보고 사람들이 편견을 가질 수도 있어요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"ox","stem":"조회 수를 높이려고 올린 자극적인 동영상을 보고 사람들이 편견을 가질 수도 있어요.","answer":"O","reason_options":[{"t":"사실과 다르거나 치우친 내용을 그대로 믿게 될 수 있기 때문에","correct":true},{"t":"자극적인 동영상은 언제나 사실만 담기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["자극적이에요.","치우칠 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#8','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',4,'mc','auto','미디어의 내용을 비판적으로 분석하여 이용해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X36','SO6-1-u2-X33']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C17","difficulty":4,"kind":"mc","stem":"미디어의 내용을 비판적으로 분석하여 이용해야 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"허위 조작 정보로 잘못된 여론이 만들어지면 합리적인 의사 결정을 방해해 민주주의를 위협할 수 있기 때문에","correct":true},{"t":"미디어가 전하는 정보는 모두 거짓이기 때문에","mis":"SO6-1-u2-X36"},{"t":"미디어를 아예 이용하지 않는 것이 가장 좋기 때문에","mis":"SO6-1-u2-X36"},{"t":"미디어가 사람들의 생각을 하나로 정해 주기 때문에","mis":"SO6-1-u2-X33"}],"explanation":["잘못된 여론이 생겨요.","결정을 방해해요.","민주주의를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#9','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',4,'mc','auto','만화와 같은 일이 나라 전체의 선거에서 일어난다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X35','SO6-1-u2-X34']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C17","difficulty":4,"kind":"mc","stem":"만화와 같은 일이 나라 전체의 선거에서 일어난다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잘못된 여론이 만들어져 국민의 뜻이 바르게 담기지 못한 결정이 내려질 수 있다","correct":true},{"t":"나중에 사실이 밝혀지면 결정도 저절로 바뀐다","mis":"SO6-1-u2-X35"},{"t":"선거에는 아무 영향이 없다","mis":"SO6-1-u2-X35"},{"t":"여론은 사실과 관계없이 늘 옳다","mis":"SO6-1-u2-X34"}],"explanation":["많은 사람이 믿어요.","잘못된 여론이에요.","결정이 흔들려요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L12_challenge#10','soc',6,1,'u2','L12','g6_1_soc_u2_L12_challenge','lesson_challenge','SO6-1-u2-C17',4,'essay','teacher','만화의 일을 보고 허위 조작 정보가 어떤 피해를 주는지 쓰고, 그런 피해를 막으려면 미디어를 어떻게 이용해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C17","difficulty":4,"kind":"essay","stem":"만화의 일을 보고 허위 조작 정보가 어떤 피해를 주는지 쓰고, 그런 피해를 막으려면 미디어를 어떻게 이용해야 하는지 쓰세요.","answer_guide":{"answer":"예: 대화방에 올라온 사실이 아닌 글 때문에 친구들이 잘못 판단해 그 친구는 회장으로 뽑히지 못했고, 글이 거짓으로 밝혀진 뒤에도 결과는 되돌아오지 않았다. 이처럼 허위 조작 정보는 사람의 권리를 침해하고 잘못된 결정을 낳는다. 그래서 정보를 그대로 믿지 말고 사실인지 따져 보며 비판적으로 분석하여 이용하고, 확인되지 않은 글은 퍼뜨리지 않아야 한다.","scoring_points":["허위 조작 정보의 피해를 썼는가","결정은 되돌아오지 않음을 썼는가","비판적으로 이용하는 방법을 썼는가"]},"explanation":["어떤 피해였나요?","되돌아오지 않았어요.","따져 보고 이용해요."],"asset":{"type":"passage","lines":["① 단체 대화방에 「어떤 친구가 먹을 것을 사 주며 표를 부탁했다」는 글이 올라왔다.","② 글을 본 친구들이 실망했고, 그 친구는 회장으로 뽑히지 못했다.","③ 나중에 그 글은 사실이 아니었다고 밝혀졌다.","④ 그 친구는 「거짓 소문 때문에 떨어지다니 억울해!」라고 말했다."],"title":"교과서 만화를 내 말로 줄인 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#1','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',1,'mc','auto','사실을 확인하는 작업이 부족해 신문이나 방송이 사실과 다른 정보를 전하는 것을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X34','SO6-1-u2-X37','SO6-1-u2-X38']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"mc","stem":"사실을 확인하는 작업이 부족해 신문이나 방송이 사실과 다른 정보를 전하는 것을 무엇이라고 하나요?","options":[{"t":"오보","correct":true},{"t":"여론","mis":"SO6-1-u2-X34"},{"t":"비평","mis":"SO6-1-u2-X37"},{"t":"관점","mis":"SO6-1-u2-X38"}],"explanation":["잘못 알린 거예요.","확인이 부족했어요.","오보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#2','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',1,'sa','auto','방송 프로그램이나 기사를 보고 우수한 점과 부족한 점을 분석해 가치를 판단하는 사람을 「미디어 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"sa","stem":"방송 프로그램이나 기사를 보고 우수한 점과 부족한 점을 분석해 가치를 판단하는 사람을 「미디어 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["비평가"],"explanation":["가치를 판단해요.","비◯◯예요.","비평가예요."],"mis":"SO6-1-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#3','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',1,'ox','auto','신문이나 방송에 보도된 내용은 확인하지 않고 그대로 믿어도 돼요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"ox","stem":"신문이나 방송에 보도된 내용은 확인하지 않고 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"신문이나 방송도 오보를 전할 수 있어 다른 자료로 확인해야 하기 때문에","correct":true},{"t":"보도된 내용은 언제나 사실이기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["오보도 있어요.","확인이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#4','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',1,'mc','auto','미디어를 올바르게 이용하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X38']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"mc","stem":"미디어를 올바르게 이용하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"확인되지 않은 정보는 함부로 공유하지 않는다","correct":true},{"t":"재미있는 정보는 확인 없이 널리 알린다","mis":"SO6-1-u2-X37"},{"t":"믿고 싶지 않은 정보는 거짓이라고 정한다","mis":"SO6-1-u2-X38"},{"t":"맞춤형 정보만 골라 본다","mis":"SO6-1-u2-X38"}],"explanation":["확인하지 않았어요.","퍼뜨리면 안 돼요.","공유하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#5','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',2,'mc','auto','같은 영화를 다룬 두 기사의 내용이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X36','SO6-1-u2-X38']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"mc","stem":"같은 영화를 다룬 두 기사의 내용이 다른 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 기사가 여러 관점 가운데 서로 다른 관점에 기대어 전했기 때문에","correct":true},{"t":"두 기사 가운데 하나는 반드시 허위 조작 정보이기 때문에","mis":"SO6-1-u2-X36"},{"t":"영화가 두 편이기 때문에","mis":"SO6-1-u2-X38"},{"t":"기사는 늘 같은 내용을 전해야 하기 때문에","mis":"SO6-1-u2-X38"}],"explanation":["같은 영화예요.","보는 쪽이 달라요.","관점이 달라요."],"asset":{"type":"passage","lines":["기사 ㉠ — 「어느 영화, 별점 최하! 실망으로 가득 찬 극장」","기사 ㉡ — 「어느 영화, 관객들에게 최고라는 평」"],"title":"같은 영화를 다룬 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#6','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',2,'mc','auto','메모의 네 자리 가운데 따져 봐야 할 곳으로 걸리지 않는 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"mc","stem":"메모의 네 자리 가운데 따져 봐야 할 곳으로 걸리지 않는 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"SO6-1-u2-X37"},{"t":"㉰","mis":"SO6-1-u2-X37"},{"t":"㉱","mis":"SO6-1-u2-X37"}],"explanation":["뉴스 흉내는 걸려요.","소문 출처도 걸려요.","글쓴이와 날짜는 괜찮아요."],"asset":{"type":"passage","lines":["㉮ 제목 앞에 「속보」라는 말을 붙였다.","㉯ 글쓴이의 이름과 올린 날짜가 또렷이 적혀 있다.","㉰ 「우리 동네에 도는 소문에 따르면」이라고만 출처를 밝혔다.","㉱ 주장은 세게 하는데 뒷받침하는 것은 그 소문뿐이다."],"title":"어느 게시 글을 살펴본 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#7','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',2,'blank','auto','맞춤형 정보에만 익숙해지면 자신의 관점과 다른 정보를 접하지 않아 (    )이 강해질 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X38']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"blank","stem":"맞춤형 정보에만 익숙해지면 자신의 관점과 다른 정보를 접하지 않아 (    )이 강해질 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"편견","correct":true},{"t":"체력","mis":"SO6-1-u2-X38"},{"t":"기억력","mis":"SO6-1-u2-X38"},{"t":"인내심","mis":"SO6-1-u2-X38"}],"explanation":["한쪽만 봐요.","생각이 치우쳐요.","편견이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#8','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',2,'match','auto','허위 조작 정보가 퍼지는 모습과 주의하는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"match","stem":"허위 조작 정보가 퍼지는 모습과 주의하는 방법을 알맞게 이으세요.","pairs":[{"l":"뉴스 형식을 흉내 낸 제목","r":"곧바로 믿지 않고 사실인지 살펴요"},{"l":"믿을 만한 사람이 전해 준 정보","r":"다른 자료로 사실인지 확인해요"},{"l":"이름으로 검색해 나온 결과","r":"다른 정보의 내용도 함께 활용해요"}],"mis":"SO6-1-u2-X37","explanation":["흉내를 경계해요.","사람을 믿어도 확인해요.","검색 결과도 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#9','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',2,'ox','auto','점검표 ②에 「그렇다」라고 답했다면 미디어를 올바르게 이용하는 습관이에요.',ARRAY['SO6-1-u2-X38']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"ox","stem":"점검표 ②에 「그렇다」라고 답했다면 미디어를 올바르게 이용하는 습관이에요.","answer":"X","reason_options":[{"t":"믿고 싶지 않은 정보라도 확인하지 않고 거짓이라 정하는 것은 올바른 태도가 아니기 때문에","correct":true},{"t":"믿고 싶지 않은 정보는 대부분 거짓이기 때문에","mis":"SO6-1-u2-X38"}],"mis":"SO6-1-u2-X38","explanation":["②를 다시 읽어요.","확인 없이 정하면 안 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 미디어의 정보를 무조건 믿지 않고 의심하나요?","② 믿고 싶지 않은 정보는 거짓이라고 생각하나요?","③ 맞춤형으로 제공되는 정보만 이용하나요?","④ 확인되지 않은 정보를 미디어로 공유하나요?","⑤ 불분명한 내용은 다른 자료를 찾아 확인하나요?"],"title":"나의 미디어 이용 습관 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_basic#10','soc',6,1,'u2','L13','g6_1_soc_u2_L13_basic','lesson_basic','SO6-1-u2-C18',3,'error','auto','메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"error","stem":"메모를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉯처럼 글쓴이와 날짜가 있으니 이 글은 믿어도 돼.」","correct":true,"mis_target":"SO6-1-u2-X37"},{"t":"친구 나 — 「㉰는 믿을 만한 출처가 아니야.」","mis":"SO6-1-u2-X37"},{"t":"친구 다 — 「㉱는 근거가 타당하지 않아.」","mis":"SO6-1-u2-X37"}],"explanation":["걸린 자리가 있어요.","하나라도 걸리면 따져 봐요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 제목 앞에 「속보」라는 말을 붙였다.","㉯ 글쓴이의 이름과 올린 날짜가 또렷이 적혀 있다.","㉰ 「우리 동네에 도는 소문에 따르면」이라고만 출처를 밝혔다.","㉱ 주장은 세게 하는데 뒷받침하는 것은 그 소문뿐이다."],"title":"어느 게시 글을 살펴본 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#1','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',2,'sa','auto','이용자의 관심에 맞춰 미디어가 자동으로 골라 보내 주는 정보를 「○○○ 정보」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"sa","stem":"이용자의 관심에 맞춰 미디어가 자동으로 골라 보내 주는 정보를 「○○○ 정보」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["맞춤형"],"explanation":["나에게 맞춰요.","맞◯◯이에요.","맞춤형이에요."],"mis":"SO6-1-u2-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#2','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',2,'ox','auto','네 기준 가운데 하나라도 걸리면 그 내용은 그대로 믿지 않고 따져 봐야 해요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"ox","stem":"네 기준 가운데 하나라도 걸리면 그 내용은 그대로 믿지 않고 따져 봐야 해요.","answer":"O","reason_options":[{"t":"괜찮은 자리가 많아도 걸린 자리가 있으면 허위 조작 정보일 수 있기 때문에","correct":true},{"t":"괜찮은 자리가 더 많으면 믿어도 되기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["하나라도 걸려요.","따져 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#3','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',3,'mc','auto','메모를 보고 이 글을 어떻게 할지 정한 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X36']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"mc","stem":"메모를 보고 이 글을 어떻게 할지 정한 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"걸린 자리가 있으니 공유하지 않고 다른 자료로 사실인지 확인한다","correct":true},{"t":"글쓴이와 날짜가 있으니 믿고 그대로 공유한다","mis":"SO6-1-u2-X37"},{"t":"제목에 속보가 붙었으니 빨리 퍼뜨린다","mis":"SO6-1-u2-X37"},{"t":"미디어는 모두 거짓이니 앞으로 아무것도 보지 않는다","mis":"SO6-1-u2-X36"}],"explanation":["걸린 자리가 셋이에요.","공유하지 않아요.","확인해요."],"asset":{"type":"passage","lines":["㉮ 제목 앞에 「속보」라는 말을 붙였다.","㉯ 글쓴이의 이름과 올린 날짜가 또렷이 적혀 있다.","㉰ 「우리 동네에 도는 소문에 따르면」이라고만 출처를 밝혔다.","㉱ 주장은 세게 하는데 뒷받침하는 것은 그 소문뿐이다."],"title":"어느 게시 글을 살펴본 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#4','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',3,'mc','auto','같은 대상을 두고 서로 다른 내용의 기사를 만났을 때의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X38','SO6-1-u2-X37','SO6-1-u2-X36']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"mc","stem":"같은 대상을 두고 서로 다른 내용의 기사를 만났을 때의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다른 신문이나 책, 인터넷에서 관련 정보를 찾아 다양한 관점을 균형 있게 살핀다","correct":true},{"t":"내 생각과 같은 기사만 믿는다","mis":"SO6-1-u2-X38"},{"t":"먼저 나온 기사를 사실로 정한다","mis":"SO6-1-u2-X37"},{"t":"두 기사 모두 거짓이라고 정한다","mis":"SO6-1-u2-X36"}],"explanation":["관점이 달라요.","더 찾아봐요.","균형 있게 살펴요."],"asset":{"type":"passage","lines":["기사 ㉠ — 「어느 영화, 별점 최하! 실망으로 가득 찬 극장」","기사 ㉡ — 「어느 영화, 관객들에게 최고라는 평」"],"title":"같은 영화를 다룬 두 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#5','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',3,'mc','auto','맞춤형 정보만 이용할 때 생길 수 있는 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X38','SO6-1-u2-X37','SO6-1-u2-X36']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"mc","stem":"맞춤형 정보만 이용할 때 생길 수 있는 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"자신의 관점과 다른 정보를 접하지 않아 편견이 강해진다","correct":true},{"t":"관심 있는 정보를 찾기 어려워진다","mis":"SO6-1-u2-X38"},{"t":"정보가 퍼지는 속도가 느려진다","mis":"SO6-1-u2-X37"},{"t":"미디어를 이용하는 사람이 줄어든다","mis":"SO6-1-u2-X36"}],"explanation":["비슷한 정보만 와요.","다른 관점을 못 봐요.","편견이 강해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#6','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',3,'error','auto','미디어 비평가가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X38']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"error","stem":"미디어 비평가가 하는 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「인기가 많은 프로그램인지만 점검해.」","correct":true,"mis_target":"SO6-1-u2-X37"},{"t":"친구 가 — 「정확한 사실을 보도하는지 점검해.」","mis":"SO6-1-u2-X37"},{"t":"친구 나 — 「여러 입장을 균형 있게 다루는지도 봐.」","mis":"SO6-1-u2-X38"}],"explanation":["무엇을 점검하나요?","사실과 균형이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#7','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',3,'ox','auto','메모의 ㉯에서 「그렇다」가 나왔으니 이 글은 허위 조작 정보일 수 없어요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"ox","stem":"메모의 ㉯에서 「그렇다」가 나왔으니 이 글은 허위 조작 정보일 수 없어요.","answer":"X","reason_options":[{"t":"작성자와 날짜가 또렷해도 출처나 근거가 걸리면 허위 조작 정보일 수 있기 때문에","correct":true},{"t":"작성자와 날짜가 있는 글은 모두 사실이기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["㉯는 괜찮아요.","다른 자리가 걸려요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 제목 앞에 「속보」라는 말을 붙였다.","㉯ 글쓴이의 이름과 올린 날짜가 또렷이 적혀 있다.","㉰ 「우리 동네에 도는 소문에 따르면」이라고만 출처를 밝혔다.","㉱ 주장은 세게 하는데 뒷받침하는 것은 그 소문뿐이다."],"title":"어느 게시 글을 살펴본 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#8','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',4,'mc','auto','허위 조작 정보를 줄이기 위한 노력을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X36']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C18","difficulty":4,"kind":"mc","stem":"허위 조작 정보를 줄이기 위한 노력을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"사회는 허위 조작 정보를 막는 방안을 마련하고, 개인은 이용 습관을 점검하며 비판적으로 분석해 활용한다","correct":true},{"t":"사회가 막아 주니 개인은 아무것도 하지 않아도 된다","mis":"SO6-1-u2-X37"},{"t":"개인이 조심하면 되니 사회는 노력할 필요가 없다","mis":"SO6-1-u2-X37"},{"t":"미디어를 모두 없애면 된다","mis":"SO6-1-u2-X36"}],"explanation":["사회의 노력이 있어요.","나의 노력도 있어요.","둘 다 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#9','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',4,'mc','auto','점검표에 바람직하게 답한 것끼리 묶은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X38','SO6-1-u2-X37']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C18","difficulty":4,"kind":"mc","stem":"점검표에 바람직하게 답한 것끼리 묶은 것은 어느 것인가요?","options":[{"t":"① 그렇다 · ③ 그렇지 않다 · ⑤ 그렇다","correct":true},{"t":"① 그렇지 않다 · ③ 그렇다 · ⑤ 그렇다","mis":"SO6-1-u2-X38"},{"t":"② 그렇다 · ④ 그렇다 · ⑤ 그렇지 않다","mis":"SO6-1-u2-X37"},{"t":"① 그렇다 · ② 그렇다 · ③ 그렇다","mis":"SO6-1-u2-X38"}],"explanation":["의심은 좋아요.","맞춤형만은 아니에요.","확인은 좋아요."],"asset":{"type":"passage","lines":["① 미디어의 정보를 무조건 믿지 않고 의심하나요?","② 믿고 싶지 않은 정보는 거짓이라고 생각하나요?","③ 맞춤형으로 제공되는 정보만 이용하나요?","④ 확인되지 않은 정보를 미디어로 공유하나요?","⑤ 불분명한 내용은 다른 자료를 찾아 확인하나요?"],"title":"나의 미디어 이용 습관 점검표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L13_challenge#10','soc',6,1,'u2','L13','g6_1_soc_u2_L13_challenge','lesson_challenge','SO6-1-u2-C18',4,'essay','teacher','메모의 네 자리를 기준에 따라 살펴 걸리는 자리와 걸리지 않는 자리를 쓰고, 이 글을 어떻게 이용해야 할지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C18","difficulty":4,"kind":"essay","stem":"메모의 네 자리를 기준에 따라 살펴 걸리는 자리와 걸리지 않는 자리를 쓰고, 이 글을 어떻게 이용해야 할지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: ㉮는 「속보」라는 말로 뉴스 형식을 흉내 내어 걸리고, ㉰는 소문을 출처로 들어 믿을 만한 출처가 아니어서 걸리며, ㉱는 근거가 소문뿐이라 타당하지 않아 걸린다. ㉯는 글쓴이와 날짜가 또렷해 걸리지 않는다. 걸린 자리가 하나라도 있으므로 이 글을 그대로 믿거나 공유하지 않고, 다른 자료를 찾아 사실인지 확인해야 한다.","scoring_points":["걸리는 자리를 바르게 썼는가","걸리지 않는 자리를 썼는가","하나라도 걸리면 따져 본다는 까닭과 행동을 썼는가"]},"explanation":["네 자리를 살펴요.","걸리는 곳을 골라요.","어떻게 할지 써요."],"asset":{"type":"passage","lines":["㉮ 제목 앞에 「속보」라는 말을 붙였다.","㉯ 글쓴이의 이름과 올린 날짜가 또렷이 적혀 있다.","㉰ 「우리 동네에 도는 소문에 따르면」이라고만 출처를 밝혔다.","㉱ 주장은 세게 하는데 뒷받침하는 것은 그 소문뿐이다."],"title":"어느 게시 글을 살펴본 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#1','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',1,'mc','auto','뉴스 기사를 쓰는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C19","difficulty":1,"kind":"mc","stem":"뉴스 기사를 쓰는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주제 고르기 → 조사하고 정리하기 → 기사 쓰기 → 기준에 따라 검토하기","correct":true},{"t":"기사 쓰기 → 주제 고르기 → 검토하기 → 조사하기","mis":"SO6-1-u2-X40"},{"t":"조사하기 → 검토하기 → 주제 고르기 → 기사 쓰기","mis":"SO6-1-u2-X40"},{"t":"주제 고르기 → 기사 쓰기 → 조사하기 → 검토하기","mis":"SO6-1-u2-X40"}],"explanation":["주제가 먼저예요.","조사한 뒤 써요.","마지막에 검토해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#2','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',1,'sa','auto','기사에 실은 내용을 어디에서 알아냈는지 밝힌 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C19","difficulty":1,"kind":"sa","stem":"기사에 실은 내용을 어디에서 알아냈는지 밝힌 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["어디서 왔나요?","◯처예요.","출처예요."],"mis":"SO6-1-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#3','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',1,'ox','auto','날마다 똑같이 되풀이되는 일도 뉴스 기사가 될 만한 일이에요.',ARRAY['SO6-1-u2-X39']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C19","difficulty":1,"kind":"ox","stem":"날마다 똑같이 되풀이되는 일도 뉴스 기사가 될 만한 일이에요.","answer":"X","reason_options":[{"t":"날마다 되풀이되는 일은 새로운 소식이 아니기 때문에","correct":true},{"t":"모든 일은 똑같이 기사가 될 만하기 때문에","mis":"SO6-1-u2-X39"}],"mis":"SO6-1-u2-X39","explanation":["새로운 소식인가요?","되풀이되는 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#4','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',1,'mc','auto','기사를 쓰는 데 필요한 내용을 조사하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C19","difficulty":1,"kind":"mc","stem":"기사를 쓰는 데 필요한 내용을 조사하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"설문지·인터넷 검색·면담 조사","correct":true},{"t":"떠오르는 대로 지어 쓰기","mis":"SO6-1-u2-X40"},{"t":"제목만 보고 짐작하기","mis":"SO6-1-u2-X40"},{"t":"친구의 말만 그대로 옮기기","mis":"SO6-1-u2-X40"}],"explanation":["직접 알아봐요.","여러 방법이 있어요.","설문지·검색·면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#5','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',2,'mc','auto','주제 후보 가운데 뉴스 기사가 될 만한 일의 조건에 맞지 않는 것은 어느 것인가요?',ARRAY['SO6-1-u2-X39']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"mc","stem":"주제 후보 가운데 뉴스 기사가 될 만한 일의 조건에 맞지 않는 것은 어느 것인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SO6-1-u2-X39"},{"t":"㉢","mis":"SO6-1-u2-X39"},{"t":"㉣","mis":"SO6-1-u2-X39"}],"explanation":["새로운 일인가요?","평소와 같아요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 우리 학교 학급 회장 선거가 처음으로 온라인 투표로 열렸다.","㉡ 오늘 아침에도 평소처럼 등교했다.","㉢ 우리 지역에 어린이 도서관이 새로 문을 열었다.","㉣ 초등학생들이 겪는 통학길 안전 문제와 해결 방안"],"title":"뉴스 기사 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#6','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',2,'match','auto','기사가 될 만한 일의 조건과 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"match","stem":"기사가 될 만한 일의 조건과 그 예를 알맞게 이으세요.","pairs":[{"l":"최근에 생기거나 밝혀진 일","r":"어제 새로 문을 연 어린이 도서관"},{"l":"영향을 받는 사람이 많은 일","r":"전교생이 지켜야 할 새 놀이 규칙"},{"l":"쉽게 겪을 수 없는 일","r":"처음으로 온라인 투표로 치른 회장 선거"}],"mis":"SO6-1-u2-X39","explanation":["최근이에요.","많은 사람이에요.","처음 겪어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#7','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',2,'blank','auto','조사한 내용을 정리할 때에는 사실과 다르거나 (    )된 내용을 기록하지 않도록 주의해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"blank","stem":"조사한 내용을 정리할 때에는 사실과 다르거나 (    )된 내용을 기록하지 않도록 주의해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"왜곡","correct":true},{"t":"정리","mis":"SO6-1-u2-X40"},{"t":"요약","mis":"SO6-1-u2-X40"},{"t":"확인","mis":"SO6-1-u2-X40"}],"explanation":["사실을 비틀어요.","사실과 달라져요.","왜곡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#8','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',2,'mc','auto','조각 가운데 사실을 과장한 것이어서 기사에 싣지 않는 것이 좋은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"mc","stem":"조각 가운데 사실을 과장한 것이어서 기사에 싣지 않는 것이 좋은 것은 어느 것인가요?","options":[{"t":"㉲","correct":true},{"t":"㉮","mis":"SO6-1-u2-X40"},{"t":"㉰","mis":"SO6-1-u2-X40"},{"t":"㉱","mis":"SO6-1-u2-X40"}],"explanation":["설문에 없는 말이에요.","부풀렸어요.","㉲예요."],"asset":{"type":"passage","lines":["㉮ 전교 어린이 회의에서 쉬는 시간 놀이 규칙을 새로 정했다.","㉯ 회의 안건은 학년별 대표가 미리 모은 의견에서 나왔다.","㉰ 학생 설문 결과를 바탕으로 했다고 회의록에 적혀 있다.","㉱ 새 규칙은 다음 주부터 시행한다.","㉲ 「모든 학생이 열렬히 환영했다」(설문에 없는 말)","㉳ 「이제 다툼은 절대 생기지 않는다」(확인되지 않은 말)"],"title":"기사에 실을 조각 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#9','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',2,'ox','auto','기사를 쓸 때 눈길을 끌려고 사실보다 조금 부풀려 써도 괜찮아요.',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"ox","stem":"기사를 쓸 때 눈길을 끌려고 사실보다 조금 부풀려 써도 괜찮아요.","answer":"X","reason_options":[{"t":"부풀려 쓰면 사실을 왜곡하게 되고 읽는 사람의 신뢰를 잃기 때문에","correct":true},{"t":"재미있는 기사가 사실보다 중요하기 때문에","mis":"SO6-1-u2-X40"}],"mis":"SO6-1-u2-X40","explanation":["사실이 먼저예요.","부풀리면 왜곡이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_basic#10','soc',6,1,'u2','L14','g6_1_soc_u2_L14_basic','lesson_basic','SO6-1-u2-C19',3,'error','auto','기사를 쓰고 검토하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"error","stem":"기사를 쓰고 검토하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「출처는 글이 길어지니까 빼자.」","correct":true,"mis_target":"SO6-1-u2-X40"},{"t":"친구 가 — 「기사 제목, 작성일, 작성자를 적자.」","mis":"SO6-1-u2-X40"},{"t":"친구 다 — 「사실과 다른 내용이 없는지 살펴보자.」","mis":"SO6-1-u2-X40"}],"explanation":["출처는 왜 밝히나요?","신뢰를 줘요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#1','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',2,'sa','auto','기사가 될 만한 일의 조건 가운데 「영향을 받는 사람이 ○○ 일」의 ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"sa","stem":"기사가 될 만한 일의 조건 가운데 「영향을 받는 사람이 ○○ 일」의 ○○에 알맞은 두 글자를 쓰세요.","answer":["많은"],"explanation":["사람 수와 관계있어요.","◯은이에요.","많은이에요."],"mis":"SO6-1-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#2','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',2,'ox','auto','같은 일을 두고 썼는데 친구의 기사와 내 기사의 내용이 다를 수 있어요.',ARRAY['SO6-1-u2-X39']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"ox","stem":"같은 일을 두고 썼는데 친구의 기사와 내 기사의 내용이 다를 수 있어요.","answer":"O","reason_options":[{"t":"무엇이 기사가 될 만한지 정하는 것은 사람이나 모둠에 따라 달라질 수 있기 때문에","correct":true},{"t":"둘 가운데 하나는 반드시 거짓이기 때문에","mis":"SO6-1-u2-X39"}],"mis":"SO6-1-u2-X39","explanation":["고르는 것이 달라요.","사람마다 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#3','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',3,'mc','auto','조각 ㉮·㉯·㉰·㉱를 실은 기사를 검토표로 살폈을 때의 답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"mc","stem":"조각 ㉮·㉯·㉰·㉱를 실은 기사를 검토표로 살폈을 때의 답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"과장·왜곡한 것은 없고, 출처(설문 결과·회의록)도 있다","correct":true},{"t":"과장한 것이 있고 출처는 없다","mis":"SO6-1-u2-X40"},{"t":"출처가 있으니 사실인지는 살필 필요가 없다","mis":"SO6-1-u2-X40"},{"t":"검토표는 기사와 관계없이 답이 정해져 있다","mis":"SO6-1-u2-X40"}],"explanation":["부풀린 조각이 없어요.","㉰가 출처예요.","그렇게 답해요."],"asset":{"type":"passage","lines":["㉮ 전교 어린이 회의에서 쉬는 시간 놀이 규칙을 새로 정했다.","㉯ 회의 안건은 학년별 대표가 미리 모은 의견에서 나왔다.","㉰ 학생 설문 결과를 바탕으로 했다고 회의록에 적혀 있다.","㉱ 새 규칙은 다음 주부터 시행한다.","㉲ 「모든 학생이 열렬히 환영했다」(설문에 없는 말)","㉳ 「이제 다툼은 절대 생기지 않는다」(확인되지 않은 말)"],"title":"기사에 실을 조각 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#4','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',3,'mc','auto','조각 ㉰를 빼고 ㉳을 넣어 다시 쓴 기사를 검토할 때 달라지는 답을 바르게 고른 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"mc","stem":"조각 ㉰를 빼고 ㉳을 넣어 다시 쓴 기사를 검토할 때 달라지는 답을 바르게 고른 것은 어느 것인가요?","options":[{"t":"과장·왜곡이 「있다」로, 출처가 「없다」로 바뀐다","correct":true},{"t":"과장·왜곡만 「있다」로 바뀌고 출처는 그대로다","mis":"SO6-1-u2-X40"},{"t":"출처만 「없다」로 바뀌고 과장·왜곡은 그대로다","mis":"SO6-1-u2-X40"},{"t":"두 기사의 검토 답은 똑같다","mis":"SO6-1-u2-X40"}],"explanation":["㉰는 출처였어요.","㉳은 확인되지 않은 말이에요.","두 답이 바뀌어요."],"asset":{"type":"passage","lines":["㉮ 전교 어린이 회의에서 쉬는 시간 놀이 규칙을 새로 정했다.","㉯ 회의 안건은 학년별 대표가 미리 모은 의견에서 나왔다.","㉰ 학생 설문 결과를 바탕으로 했다고 회의록에 적혀 있다.","㉱ 새 규칙은 다음 주부터 시행한다.","㉲ 「모든 학생이 열렬히 환영했다」(설문에 없는 말)","㉳ 「이제 다툼은 절대 생기지 않는다」(확인되지 않은 말)"],"title":"기사에 실을 조각 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#5','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',3,'mc','auto','기사 검토표의 답이 기사마다 달라지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"mc","stem":"기사 검토표의 답이 기사마다 달라지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"검토표는 그 기사에 그런 내용이 있는지 없는지를 묻기 때문에","correct":true},{"t":"검토표의 답은 미리 정해져 있기 때문에","mis":"SO6-1-u2-X40"},{"t":"두 번째에는 기준이 바뀌기 때문에","mis":"SO6-1-u2-X40"},{"t":"기사를 많이 쓸수록 점수가 오르기 때문에","mis":"SO6-1-u2-X40"}],"explanation":["기준은 같아요.","기사가 달라요.","있는지 없는지를 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#6','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',3,'error','auto','주제 후보를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X39']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"error","stem":"주제 후보를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉡도 오늘 일어난 일이니 기사가 될 만해.」","correct":true,"mis_target":"SO6-1-u2-X39"},{"t":"친구 가 — 「㉠은 쉽게 겪을 수 없는 일이라 기사가 될 만해.」","mis":"SO6-1-u2-X39"},{"t":"친구 나 — 「㉣은 많은 초등학생이 겪는 문제야.」","mis":"SO6-1-u2-X39"}],"explanation":["㉡은 늘 있는 일이에요.","새롭지 않아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 우리 학교 학급 회장 선거가 처음으로 온라인 투표로 열렸다.","㉡ 오늘 아침에도 평소처럼 등교했다.","㉢ 우리 지역에 어린이 도서관이 새로 문을 열었다.","㉣ 초등학생들이 겪는 통학길 안전 문제와 해결 방안"],"title":"뉴스 기사 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#7','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',3,'ox','auto','출처를 분명하게 밝혀야 기사를 읽는 사람에게 신뢰를 줄 수 있어요.',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"ox","stem":"출처를 분명하게 밝혀야 기사를 읽는 사람에게 신뢰를 줄 수 있어요.","answer":"O","reason_options":[{"t":"어디에서 알아낸 내용인지 알아야 사실인지 확인할 수 있기 때문에","correct":true},{"t":"출처는 기사의 길이를 늘리기 위한 것이기 때문에","mis":"SO6-1-u2-X40"}],"mis":"SO6-1-u2-X40","explanation":["어디서 알아냈나요?","확인할 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#8','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',4,'mc','auto','기준 4를 판단하려면 무엇이 더 있어야 하나요?',ARRAY['SO6-1-u2-X40','SO6-1-u2-X39']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C19","difficulty":4,"kind":"mc","stem":"기준 4를 판단하려면 무엇이 더 있어야 하나요?","options":[{"t":"같은 주제로 쓴 친구의 기사","correct":true},{"t":"내 기사의 제목 하나","mis":"SO6-1-u2-X40"},{"t":"조사한 사람의 이름","mis":"SO6-1-u2-X40"},{"t":"아무것도 필요 없다","mis":"SO6-1-u2-X39"}],"explanation":["서로 다른 점을 봐요.","견줄 기사가 필요해요.","친구의 기사예요."],"asset":{"type":"passage","lines":["1. 기사의 내용이 사실인가요?","2. 사실을 과장하거나 왜곡한 것이 있나요?","3. 내용을 뒷받침할 출처가 제시되어 있나요?","4. 같은 주제의 기사들 사이에 서로 다른 점이 있나요?"],"title":"기사 검토 기준"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#9','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',4,'mc','auto','이 단원에서 공부한 내용과 뉴스 기사 쓰기를 이어 가장 알맞게 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X40','SO6-1-u2-X39']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C19","difficulty":4,"kind":"mc","stem":"이 단원에서 공부한 내용과 뉴스 기사 쓰기를 이어 가장 알맞게 정리한 것은 어느 것인가요?","options":[{"t":"사실을 확인하고 출처를 밝혀 기사를 쓰면 허위 조작 정보를 줄이고 사람들이 바르게 판단하도록 도울 수 있다","correct":true},{"t":"기사는 재미만 있으면 사실이 아니어도 된다","mis":"SO6-1-u2-X40"},{"t":"기사를 쓰는 일은 민주주의와 관계없다","mis":"SO6-1-u2-X39"},{"t":"같은 일은 누가 써도 기사가 같아야 한다","mis":"SO6-1-u2-X39"}],"explanation":["사실과 출처예요.","허위 조작 정보를 줄여요.","바른 판단을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_L14_challenge#10','soc',6,1,'u2','L14','g6_1_soc_u2_L14_challenge','lesson_challenge','SO6-1-u2-C19',4,'essay','teacher','주제 후보 가운데 하나를 골라 기사가 될 만한 까닭을 쓰고, 그 기사를 쓸 때의 조사 방법과 주의할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO6-1-u2-C19","difficulty":4,"kind":"essay","stem":"주제 후보 가운데 하나를 골라 기사가 될 만한 까닭을 쓰고, 그 기사를 쓸 때의 조사 방법과 주의할 점을 쓰세요.","answer_guide":{"answer":"예: ㉢ 「우리 지역에 어린이 도서관이 새로 문을 열었다」를 고르겠다. 최근에 생긴 일이고 지역의 많은 어린이가 영향을 받기 때문에 기사가 될 만하다. 도서관 누리집을 인터넷으로 검색하고 사서 선생님을 면담하며 친구들에게 설문지를 받아 조사하겠다. 조사한 내용은 출처와 함께 적고, 사실과 다르거나 부풀린 내용은 쓰지 않도록 주의하겠다.","scoring_points":["주제를 골라 기사가 될 만한 까닭을 썼는가","조사 방법을 썼는가","출처·사실 같은 주의할 점을 썼는가"]},"explanation":["주제를 골라요.","어떻게 조사할까요?","주의할 점을 써요."],"asset":{"type":"passage","lines":["㉠ 우리 학교 학급 회장 선거가 처음으로 온라인 투표로 열렸다.","㉡ 오늘 아침에도 평소처럼 등교했다.","㉢ 우리 지역에 어린이 도서관이 새로 문을 열었다.","㉣ 초등학생들이 겪는 통학길 안전 문제와 해결 방안"],"title":"뉴스 기사 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#1','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C1',1,'mc','auto','국민이 투표로 대표를 뽑아 나랏일을 맡기는 일을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"mc","stem":"국민이 투표로 대표를 뽑아 나랏일을 맡기는 일을 무엇이라고 하나요?","options":[{"t":"선거","correct":true},{"t":"재판","mis":"SO6-1-u2-X02"},{"t":"견제","mis":"SO6-1-u2-X02"},{"t":"비평","mis":"SO6-1-u2-X02"}],"explanation":["투표로 뽑아요.","대표를 뽑아요.","선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#2','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C4',1,'mc','auto','선거 과정에서 투표 바로 다음에 하는 일은 무엇인가요?',ARRAY['SO6-1-u2-X09']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C4","difficulty":1,"kind":"mc","stem":"선거 과정에서 투표 바로 다음에 하는 일은 무엇인가요?","options":[{"t":"개표","correct":true},{"t":"후보자 등록","mis":"SO6-1-u2-X09"},{"t":"선거 운동","mis":"SO6-1-u2-X09"},{"t":"선거인 명부 작성","mis":"SO6-1-u2-X09"}],"explanation":["표를 셀 차례예요.","투표함을 열어요.","개표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#3','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C6',1,'mc','auto','선거 공약을 평가할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"mc","stem":"선거 공약을 평가할 때 살펴볼 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"공약이 국민의 요구를 반영하는지","correct":true},{"t":"후보자의 옷차림이 멋진지","mis":"SO6-1-u2-X15"},{"t":"후보자가 상대를 많이 깎아내리는지","mis":"SO6-1-u2-X15"},{"t":"공약 글씨가 큰지","mis":"SO6-1-u2-X15"}],"explanation":["공약을 재요.","국민이 바라는지 봐요.","요구를 반영하는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#4','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C7',1,'mc','auto','우리나라의 세 국가기관이 아닌 것은 어느 것인가요?',ARRAY['SO6-1-u2-X17']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C7","difficulty":1,"kind":"mc","stem":"우리나라의 세 국가기관이 아닌 것은 어느 것인가요?","options":[{"t":"시민 단체","correct":true},{"t":"국회","mis":"SO6-1-u2-X17"},{"t":"행정부","mis":"SO6-1-u2-X17"},{"t":"법원","mis":"SO6-1-u2-X17"}],"explanation":["세 기관을 떠올려요.","국회·행정부·법원이에요.","시민 단체가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#5','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C10',1,'mc','auto','행정부의 최고 책임자는 누구인가요?',ARRAY['SO6-1-u2-X22','SO6-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C10","difficulty":1,"kind":"mc","stem":"행정부의 최고 책임자는 누구인가요?","options":[{"t":"대통령","correct":true},{"t":"국무총리","mis":"SO6-1-u2-X22"},{"t":"국회의원","mis":"SO6-1-u2-X18"},{"t":"법관","mis":"SO6-1-u2-X18"}],"explanation":["국민이 선출해요.","우리나라의 대표예요.","대통령이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#6','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C12',1,'mc','auto','재판을 통해 다툼의 옳고 그름을 가리는 국가기관은 어디인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X24']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C12","difficulty":1,"kind":"mc","stem":"재판을 통해 다툼의 옳고 그름을 가리는 국가기관은 어디인가요?","options":[{"t":"법원","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"행정부","mis":"SO6-1-u2-X18"},{"t":"선거 관리 위원회","mis":"SO6-1-u2-X24"}],"explanation":["재판을 해요.","판결을 내려요.","법원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#7','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C15',1,'mc','auto','정보를 주고받으며 의사소통하기 위해 사용하는 수단을 가리키는 말은 무엇인가요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"mc","stem":"정보를 주고받으며 의사소통하기 위해 사용하는 수단을 가리키는 말은 무엇인가요?","options":[{"t":"미디어","correct":true},{"t":"여론","mis":"SO6-1-u2-X30"},{"t":"공약","mis":"SO6-1-u2-X30"},{"t":"관점","mis":"SO6-1-u2-X30"}],"explanation":["수단이에요.","정보를 주고받아요.","미디어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#8','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C17',1,'mc','auto','많은 사람이 갖고 있는 공통된 의견을 무엇이라고 하나요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"mc","stem":"많은 사람이 갖고 있는 공통된 의견을 무엇이라고 하나요?","options":[{"t":"여론","correct":true},{"t":"오보","mis":"SO6-1-u2-X34"},{"t":"공약","mis":"SO6-1-u2-X34"},{"t":"출처","mis":"SO6-1-u2-X34"}],"explanation":["공통된 의견이에요.","◯론이에요.","여론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#9','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C1',2,'mc','auto','신문 ①에서 전교 회장을 뽑기로 한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X03','SO6-1-u2-X01','SO6-1-u2-X02']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C1","difficulty":2,"kind":"mc","stem":"신문 ①에서 전교 회장을 뽑기로 한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"전교생 모두가 날마다 모여 회의할 수 없어 대표에게 맡기려고","correct":true},{"t":"회장이 학교의 주인이 되게 하려고","mis":"SO6-1-u2-X03"},{"t":"학생들이 학교 일에 관심을 끊게 하려고","mis":"SO6-1-u2-X01"},{"t":"선생님이 대표를 정해 주려고","mis":"SO6-1-u2-X02"}],"explanation":["모두 모일 수 없어요.","대표에게 맡겨요.","그래서 뽑아요."],"asset":{"type":"passage","lines":["전교생이 날마다 한자리에 모여 회의할 수는 없어 전교 회장을 뽑기로 했다.","지난 선거에서는 두 후보의 표가 같아 다시 세어 보았지만 결과는 그대로였다.","늦게 투표한 한 학생의 표로 결과가 갈렸다."],"title":"신문 ① — 전교 어린이 회장 선거가 다가왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#10','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C4',2,'mc','auto','신문 ②에서 선거 관리 위원 학생들이 맨 먼저 한 일은 선거 과정의 어느 걸음과 같나요?',ARRAY['SO6-1-u2-X09','SO6-1-u2-X10']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C4","difficulty":2,"kind":"mc","stem":"신문 ②에서 선거 관리 위원 학생들이 맨 먼저 한 일은 선거 과정의 어느 걸음과 같나요?","options":[{"t":"선거인 명부 작성","correct":true},{"t":"후보자 등록","mis":"SO6-1-u2-X09"},{"t":"개표","mis":"SO6-1-u2-X09"},{"t":"선거 운동","mis":"SO6-1-u2-X10"}],"explanation":["명단을 만들었어요.","맨 먼저 해요.","선거인 명부 작성이에요."],"asset":{"type":"passage","lines":["선거 관리 위원 학생들이 먼저 투표할 학생 명단을 만들었다.","후보 등록 → 선거 운동 → 투표 → 개표 → 당선자 발표 차례로 진행한다.","몸이 불편한 학생은 교실에서 투표할 수 있게 했다.","기표소에서 혼자 투표하고, 누구를 뽑았는지는 말하지 않는다."],"title":"신문 ② — 우리 학교 선거는 이렇게 치러요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#11','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C6',2,'mc','auto','신문 ③의 공약 가운데 「구체적인가」라는 잣대에 걸리는 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":11,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"신문 ③의 공약 가운데 「구체적인가」라는 잣대에 걸리는 것은 어느 것인가요?","options":[{"t":"기호 2의 공약","correct":true},{"t":"기호 1의 공약","mis":"SO6-1-u2-X15"},{"t":"기호 3의 공약","mis":"SO6-1-u2-X15"},{"t":"세 공약 모두","mis":"SO6-1-u2-X15"}],"explanation":["어떻게 할지가 있나요?","더 좋게만 하겠대요.","기호 2예요."],"asset":{"type":"passage","lines":["기호 1 — 쉬는 시간 놀이 기구를 학년별로 나누어 빌려주겠습니다.","기호 2 — 학교를 더 좋게 만들겠습니다.","기호 3 — 모든 학생에게 날마다 간식을 주겠습니다."],"title":"신문 ③ — 후보 공약 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#12','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C8',2,'mc','auto','신문 ④에서 국회가 법률안을 심의하고 투표로 정한 뒤 법이 시행되기까지 남은 걸음은 무엇인가요?',ARRAY['SO6-1-u2-X19']::text[],false,'{"seq":12,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"mc","stem":"신문 ④에서 국회가 법률안을 심의하고 투표로 정한 뒤 법이 시행되기까지 남은 걸음은 무엇인가요?","options":[{"t":"대통령이 서명하여 널리 알리고 시행한다","correct":true},{"t":"법원이 판결한다","mis":"SO6-1-u2-X19"},{"t":"국민이 다시 요구한다","mis":"SO6-1-u2-X19"},{"t":"행정 각부가 투표한다","mis":"SO6-1-u2-X19"}],"explanation":["국회가 정했어요.","마지막 자리가 남았어요.","대통령의 서명이에요."],"asset":{"type":"passage","lines":["국회의원들이 법률안을 심의하는 회의장을 보았다.","국민의 요구로 낸 법률안이 심의와 투표를 거쳐 정해진다고 들었다.","나라 살림에 쓸 돈의 계획을 살피는 일도 한다고 했다."],"title":"신문 ④ — 국회 견학 다녀왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#13','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C11',2,'mc','auto','신문 ⑤의 카드 뉴스를 만든 곳은 어느 국가기관에 속하나요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X23']::text[],false,'{"seq":13,"concept":"SO6-1-u2-C11","difficulty":2,"kind":"mc","stem":"신문 ⑤의 카드 뉴스를 만든 곳은 어느 국가기관에 속하나요?","options":[{"t":"행정부","correct":true},{"t":"국회","mis":"SO6-1-u2-X18"},{"t":"법원","mis":"SO6-1-u2-X18"},{"t":"선거 관리 위원회","mis":"SO6-1-u2-X23"}],"explanation":["행정 각부가 만들었어요.","살림을 맡아요.","행정부예요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#14','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C14',2,'mc','auto','신문 ⑥의 둘째 컷에서 생긴 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X28']::text[],false,'{"seq":14,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"mc","stem":"신문 ⑥의 둘째 컷에서 생긴 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한곳에 모인 힘을 막을 곳이 없어 마음대로 쓸 수 있다","correct":true},{"t":"힘이 고르게 나뉘었다","mis":"SO6-1-u2-X27"},{"t":"세 곳이 서로 살핀다","mis":"SO6-1-u2-X28"},{"t":"사람들의 권리가 더 커졌다","mis":"SO6-1-u2-X27"}],"explanation":["한 사람이 다 해요.","막을 곳이 없어요.","마음대로 써요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#15','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C16',2,'mc','auto','신문 ⑦에서 하천 쓰레기 문제를 알리고 해결 방법을 내놓은 것은 미디어의 어떤 역할인가요?',ARRAY['SO6-1-u2-X32','SO6-1-u2-X33']::text[],false,'{"seq":15,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 하천 쓰레기 문제를 알리고 해결 방법을 내놓은 것은 미디어의 어떤 역할인가요?","options":[{"t":"사회문제를 지목하고 해결 방안을 제시하는 역할","correct":true},{"t":"가치나 규범을 보여 주는 역할","mis":"SO6-1-u2-X32"},{"t":"새로운 사실을 신속하게 전하는 역할","mis":"SO6-1-u2-X32"},{"t":"정보를 감추는 역할","mis":"SO6-1-u2-X33"}],"explanation":["문제를 알렸어요.","해결 방법도 냈어요.","사회문제 역할이에요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#16','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C18',2,'mc','auto','신문 ⑧의 대화방 글을 기준에 따라 살필 때 걸리는 자리로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"mc","stem":"신문 ⑧의 대화방 글을 기준에 따라 살필 때 걸리는 자리로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뉴스 형식을 흉내 냈고 믿을 만한 출처가 없다","correct":true},{"t":"글쓴이와 날짜가 적혀 있다","mis":"SO6-1-u2-X37"},{"t":"대화방에 올라왔다","mis":"SO6-1-u2-X37"},{"t":"걸리는 자리가 하나도 없다","mis":"SO6-1-u2-X37"}],"explanation":["속보를 붙였어요.","출처가 들은 이야기예요.","두 곳이 걸려요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#17','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C3',3,'mc','auto','선거에 참여하지 않는 사람이 많아지면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X07','SO6-1-u2-X06']::text[],false,'{"seq":17,"concept":"SO6-1-u2-C3","difficulty":3,"kind":"mc","stem":"선거에 참여하지 않는 사람이 많아지면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민의 뜻이 선거 결과에 고르게 담기기 어려워진다","correct":true},{"t":"국민 주권이 더 강해진다","mis":"SO6-1-u2-X07"},{"t":"결과가 더 정확해진다","mis":"SO6-1-u2-X06"},{"t":"아무 변화도 없다","mis":"SO6-1-u2-X06"}],"explanation":["참여가 줄어요.","뜻이 덜 담겨요.","고르게 담기기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#18','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C5',3,'mc','auto','「박사 학위가 있는 사람은 여러 표를 낸다」는 규칙이 공정하지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X12','SO6-1-u2-X13']::text[],false,'{"seq":18,"concept":"SO6-1-u2-C5","difficulty":3,"kind":"mc","stem":"「박사 학위가 있는 사람은 여러 표를 낸다」는 규칙이 공정하지 않은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학력과 관계없이 모두가 한 표씩 투표하는 평등 선거에 어긋나기 때문에","correct":true},{"t":"비밀 선거에 어긋나기 때문에","mis":"SO6-1-u2-X12"},{"t":"투표 시간이 길어지기 때문에","mis":"SO6-1-u2-X13"},{"t":"박사는 투표할 수 없기 때문에","mis":"SO6-1-u2-X12"}],"explanation":["여러 표예요.","한 표씩이어야 해요.","평등 선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#19','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C7',3,'mc','auto','어린이 보호 구역의 교통안전을 위해 세 국가기관이 할 수 있는 일을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":19,"concept":"SO6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어린이 보호 구역의 교통안전을 위해 세 국가기관이 할 수 있는 일을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"국회 — 관련 법 만들기 · 행정부 — 단속 카메라 설치 · 법원 — 위반 재판","correct":true},{"t":"국회 — 단속 카메라 설치 · 행정부 — 위반 재판 · 법원 — 관련 법 만들기","mis":"SO6-1-u2-X18"},{"t":"국회 — 위반 재판 · 행정부 — 관련 법 만들기 · 법원 — 단속 카메라 설치","mis":"SO6-1-u2-X18"},{"t":"세 기관이 모두 같은 일을 한다","mis":"SO6-1-u2-X17"}],"explanation":["법을 만들어요.","설치를 지시해요.","재판해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#20','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C14',3,'mc','auto','다음 가운데 국회가 행정부를 견제하는 모습은 어느 것인가요?',ARRAY['SO6-1-u2-X28','SO6-1-u2-X20']::text[],false,'{"seq":20,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"다음 가운데 국회가 행정부를 견제하는 모습은 어느 것인가요?","options":[{"t":"국정 감사로 나라 살림을 잘 하는지 확인한다","correct":true},{"t":"법률안에 거부권을 행사한다","mis":"SO6-1-u2-X28"},{"t":"행정부의 명령을 취소하라고 결정한다","mis":"SO6-1-u2-X28"},{"t":"법률안에 서명한다","mis":"SO6-1-u2-X20"}],"explanation":["국회가 해요.","행정부를 살펴요.","국정 감사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#21','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C17',3,'mc','auto','허위 조작 정보가 민주주의를 위협할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X36','SO6-1-u2-X34','SO6-1-u2-X35']::text[],false,'{"seq":21,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"mc","stem":"허위 조작 정보가 민주주의를 위협할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"잘못된 여론을 만들어 사람들이 합리적으로 결정하지 못하게 하기 때문에","correct":true},{"t":"사람들이 미디어를 아예 쓰지 않게 하기 때문에","mis":"SO6-1-u2-X36"},{"t":"여론을 늘 바르게 만들기 때문에","mis":"SO6-1-u2-X34"},{"t":"결정이 나중에 저절로 바로잡히기 때문에","mis":"SO6-1-u2-X35"}],"explanation":["여론이 잘못돼요.","결정이 흔들려요.","민주주의를 위협해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#22','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C18',3,'mc','auto','「유명한 사람이 대화방에 올린 글이니 사실일 거야」라는 생각에 대한 판단으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X36','SO6-1-u2-X38']::text[],false,'{"seq":22,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"mc","stem":"「유명한 사람이 대화방에 올린 글이니 사실일 거야」라는 생각에 대한 판단으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"믿을 만한 사람이 전한 정보라도 다른 자료로 사실인지 확인해야 한다","correct":true},{"t":"유명한 사람의 글은 모두 사실이다","mis":"SO6-1-u2-X37"},{"t":"대화방 글은 모두 거짓이다","mis":"SO6-1-u2-X36"},{"t":"믿고 싶은 글이면 확인할 필요가 없다","mis":"SO6-1-u2-X38"}],"explanation":["누가 올렸든 확인해요.","다른 자료를 봐요.","사실인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#23','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C3',4,'mc','auto','신문 ①~③을 함께 볼 때 선거에 대해 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X06','SO6-1-u2-X13','SO6-1-u2-X05']::text[],false,'{"seq":23,"concept":"SO6-1-u2-C3","difficulty":4,"kind":"mc","stem":"신문 ①~③을 함께 볼 때 선거에 대해 내릴 수 있는 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"한 사람 한 사람의 참여가 결과를 정하므로, 정해진 절차와 원칙을 지키며 공약을 따져 투표해야 한다","correct":true},{"t":"결과는 정해져 있으니 공약을 볼 필요가 없다","mis":"SO6-1-u2-X06"},{"t":"절차는 그때그때 바꾸어도 된다","mis":"SO6-1-u2-X13"},{"t":"인기 있는 후보에게 표를 모아 주면 된다","mis":"SO6-1-u2-X05"}],"explanation":["①은 한 표예요.","②는 절차와 원칙이에요.","③은 공약이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#24','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C5',4,'essay','teacher','신문 ②를 보고 학교 선거에서 지킨 선거 원칙 두 가지를 찾아 쓰고, 선거 원칙을 지켜야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u2-C5","difficulty":4,"kind":"essay","stem":"신문 ②를 보고 학교 선거에서 지킨 선거 원칙 두 가지를 찾아 쓰고, 선거 원칙을 지켜야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 기표소에서 혼자 투표하고 누구를 뽑았는지 말하지 않는 것은 비밀 선거의 원칙을 지킨 것이다. 몸이 불편한 학생도 교실에서 투표하게 한 것은 투표할 수 있는 사람이면 누구나 투표하게 하는 보통 선거의 뜻을 지킨 것이다. 선거 원칙을 지켜야 공정하고 민주적인 선거가 이루어지고 모든 사람이 동등한 권리를 누릴 수 있다.","scoring_points":["선거 원칙 두 가지를 찾았는가","신문의 장면과 바르게 이었는가","원칙을 지키는 까닭을 썼는가"]},"explanation":["신문 ②를 다시 읽어요.","원칙을 찾아요.","까닭을 써요."],"asset":{"type":"passage","lines":["선거 관리 위원 학생들이 먼저 투표할 학생 명단을 만들었다.","후보 등록 → 선거 운동 → 투표 → 개표 → 당선자 발표 차례로 진행한다.","몸이 불편한 학생은 교실에서 투표할 수 있게 했다.","기표소에서 혼자 투표하고, 누구를 뽑았는지는 말하지 않는다."],"title":"신문 ② — 우리 학교 선거는 이렇게 치러요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_a#25','soc',6,1,'u2','','g6_1_soc_u2_review_a','unit_review','SO6-1-u2-C3',4,'essay','teacher','신문 ①을 보고 선거에 참여하는 것이 중요한 까닭을 쓰고, 다시 센 일과 늦게 들어온 한 표가 결과에 준 영향을 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u2-C3","difficulty":4,"kind":"essay","stem":"신문 ①을 보고 선거에 참여하는 것이 중요한 까닭을 쓰고, 다시 센 일과 늦게 들어온 한 표가 결과에 준 영향을 견주어 쓰세요.","answer_guide":{"answer":"예: 선거는 국민 주권을 실현하는 가장 기본적인 방법이고, 한 표 차이로도 결과가 달라질 수 있어 참여가 중요하다. 신문 ①에서 표를 다시 센 일은 실수가 없는지 확인한 것이라 결과가 그대로였지만, 늦게 투표한 학생의 한 표는 같던 결과를 갈라 놓았다. 그러니 결과를 정하는 것은 다시 세기가 아니라 한 사람 한 사람의 참여이다.","scoring_points":["참여가 중요한 까닭을 썼는가","다시 세기는 확인임을 썼는가","한 표가 결과를 바꾼 점을 견주었는가"]},"explanation":["국민 주권이에요.","다시 세기는 확인이에요.","한 표가 갈랐어요."],"asset":{"type":"passage","lines":["전교생이 날마다 한자리에 모여 회의할 수는 없어 전교 회장을 뽑기로 했다.","지난 선거에서는 두 후보의 표가 같아 다시 세어 보았지만 결과는 그대로였다.","늦게 투표한 한 학생의 표로 결과가 갈렸다."],"title":"신문 ① — 전교 어린이 회장 선거가 다가왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#1','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C1',1,'sa','auto','선거에서 대표를 뽑을 권리를 가진 사람을 가리키는 세 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO6-1-u2-C1","difficulty":1,"kind":"sa","stem":"선거에서 대표를 뽑을 권리를 가진 사람을 가리키는 세 글자 낱말을 쓰세요.","answer":["유권자"],"explanation":["권리를 가진 사람이에요.","유◯◯예요.","유권자예요."],"mis":"SO6-1-u2-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#2','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C5',1,'mc','auto','18세 이상이면 누구나 투표할 수 있다는 선거 원칙은 무엇인가요?',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C5","difficulty":1,"kind":"mc","stem":"18세 이상이면 누구나 투표할 수 있다는 선거 원칙은 무엇인가요?","options":[{"t":"보통 선거","correct":true},{"t":"평등 선거","mis":"SO6-1-u2-X12"},{"t":"직접 선거","mis":"SO6-1-u2-X12"},{"t":"비밀 선거","mis":"SO6-1-u2-X12"}],"explanation":["누구나예요.","나이만 되면 돼요.","보통 선거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#3','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C6',1,'ox','auto','투표할 때에는 누구에게 투표했는지 다른 사람에게 말하지 않아요.',ARRAY['SO6-1-u2-X16']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"ox","stem":"투표할 때에는 누구에게 투표했는지 다른 사람에게 말하지 않아요.","answer":"O","reason_options":[{"t":"비밀 선거의 원칙에 따라 투표의 비밀을 지키기 때문에","correct":true},{"t":"누구에게 투표했는지 모두 알려야 공정하기 때문에","mis":"SO6-1-u2-X16"}],"mis":"SO6-1-u2-X16","explanation":["비밀이에요.","말하지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#4','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C8',1,'sa','auto','법률이 될 사항을 정리해 국회에 내는 문서를 가리키는 세 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO6-1-u2-C8","difficulty":1,"kind":"sa","stem":"법률이 될 사항을 정리해 국회에 내는 문서를 가리키는 세 글자 낱말을 쓰세요.","answer":["법률안"],"explanation":["아직 법이 아니에요.","법률◯이에요.","법률안이에요."],"mis":"SO6-1-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#5','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C11',1,'sa','auto','경제·교육·외교·국방·환경 등의 업무를 나눠 맡는 곳을 「행정 ○○」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO6-1-u2-C11","difficulty":1,"kind":"sa","stem":"경제·교육·외교·국방·환경 등의 업무를 나눠 맡는 곳을 「행정 ○○」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["각부"],"explanation":["여러 부가 있어요.","◯부예요.","각부예요."],"mis":"SO6-1-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#6','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C13',1,'sa','auto','하나의 사건에 원칙적으로 세 번까지 재판을 받을 수 있게 한 제도를 「○○ 제도」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO6-1-u2-C13","difficulty":1,"kind":"sa","stem":"하나의 사건에 원칙적으로 세 번까지 재판을 받을 수 있게 한 제도를 「○○ 제도」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["삼심"],"explanation":["세 번이에요.","삼◯이에요.","삼심이에요."],"mis":"SO6-1-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#7','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C15',1,'sa','auto','영상과 소리 등으로 많은 사람에게 정보를 신속하게 전하는 미디어를 가리키는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO6-1-u2-C15","difficulty":1,"kind":"sa","stem":"영상과 소리 등으로 많은 사람에게 정보를 신속하게 전하는 미디어를 가리키는 두 글자 낱말을 쓰세요.","answer":["방송"],"explanation":["영상과 소리예요.","◯송이에요.","방송이에요."],"mis":"SO6-1-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#8','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C18',1,'sa','auto','사실을 확인하는 작업이 부족해 사실과 다른 정보를 전하는 것을 가리키는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"sa","stem":"사실을 확인하는 작업이 부족해 사실과 다른 정보를 전하는 것을 가리키는 두 글자 낱말을 쓰세요.","answer":["오보"],"explanation":["잘못 알렸어요.","◯보예요.","오보예요."],"mis":"SO6-1-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#9','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C3',2,'mc','auto','신문 ①에서 표를 다시 센 일의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X08']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"mc","stem":"신문 ①에서 표를 다시 센 일의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"결과에 잘못이나 실수가 있는지 확인한 일","correct":true},{"t":"결과를 바꾸려고 한 일","mis":"SO6-1-u2-X08"},{"t":"투표를 처음부터 다시 한 일","mis":"SO6-1-u2-X08"},{"t":"새 표를 더한 일","mis":"SO6-1-u2-X08"}],"explanation":["다시 셌어요.","결과는 그대로였어요.","확인한 일이에요."],"asset":{"type":"passage","lines":["전교생이 날마다 한자리에 모여 회의할 수는 없어 전교 회장을 뽑기로 했다.","지난 선거에서는 두 후보의 표가 같아 다시 세어 보았지만 결과는 그대로였다.","늦게 투표한 한 학생의 표로 결과가 갈렸다."],"title":"신문 ① — 전교 어린이 회장 선거가 다가왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#10','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C5',2,'mc','auto','신문 ②에서 몸이 불편한 학생이 교실에서 투표하도록 한 것과 같은 뜻을 지닌 실제 투표 방법은 어느 것인가요?',ARRAY['SO6-1-u2-X14']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"mc","stem":"신문 ②에서 몸이 불편한 학생이 교실에서 투표하도록 한 것과 같은 뜻을 지닌 실제 투표 방법은 어느 것인가요?","options":[{"t":"거소 투표","correct":true},{"t":"재검표","mis":"SO6-1-u2-X14"},{"t":"국정 감사","mis":"SO6-1-u2-X14"},{"t":"인사 청문회","mis":"SO6-1-u2-X14"}],"explanation":["머무는 곳에서 해요.","투표소에 못 가도 돼요.","거소 투표예요."],"asset":{"type":"passage","lines":["선거 관리 위원 학생들이 먼저 투표할 학생 명단을 만들었다.","후보 등록 → 선거 운동 → 투표 → 개표 → 당선자 발표 차례로 진행한다.","몸이 불편한 학생은 교실에서 투표할 수 있게 했다.","기표소에서 혼자 투표하고, 누구를 뽑았는지는 말하지 않는다."],"title":"신문 ② — 우리 학교 선거는 이렇게 치러요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#11','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C6',2,'mc','auto','신문 ③에서 기호 3의 공약이 걸리는 잣대로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":11,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"신문 ③에서 기호 3의 공약이 걸리는 잣대로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"실천할 수 있는가","correct":true},{"t":"후보자의 목소리가 큰가","mis":"SO6-1-u2-X15"},{"t":"우리 반 후보인가","mis":"SO6-1-u2-X15"},{"t":"글자가 많은가","mis":"SO6-1-u2-X15"}],"explanation":["날마다 간식이에요.","지킬 수 있을까요?","실천할 수 있는지예요."],"asset":{"type":"passage","lines":["기호 1 — 쉬는 시간 놀이 기구를 학년별로 나누어 빌려주겠습니다.","기호 2 — 학교를 더 좋게 만들겠습니다.","기호 3 — 모든 학생에게 날마다 간식을 주겠습니다."],"title":"신문 ③ — 후보 공약 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#12','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C9',2,'mc','auto','신문 ④에서 국회가 나라 살림에 쓸 돈의 계획을 살핀다고 한 일은 무엇인가요?',ARRAY['SO6-1-u2-X21','SO6-1-u2-X20']::text[],false,'{"seq":12,"concept":"SO6-1-u2-C9","difficulty":2,"kind":"mc","stem":"신문 ④에서 국회가 나라 살림에 쓸 돈의 계획을 살핀다고 한 일은 무엇인가요?","options":[{"t":"예산안 심의","correct":true},{"t":"인사 청문회","mis":"SO6-1-u2-X21"},{"t":"국정 감사","mis":"SO6-1-u2-X21"},{"t":"법률안 거부","mis":"SO6-1-u2-X20"}],"explanation":["돈의 계획이에요.","예산이에요.","예산안 심의예요."],"asset":{"type":"passage","lines":["국회의원들이 법률안을 심의하는 회의장을 보았다.","국민의 요구로 낸 법률안이 심의와 투표를 거쳐 정해진다고 들었다.","나라 살림에 쓸 돈의 계획을 살피는 일도 한다고 했다."],"title":"신문 ④ — 국회 견학 다녀왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#13','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C10',2,'mc','auto','신문 ⑤에서 대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X22','SO6-1-u2-X23']::text[],false,'{"seq":13,"concept":"SO6-1-u2-C10","difficulty":2,"kind":"mc","stem":"신문 ⑤에서 대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나라의 살림은 멈출 수 없기 때문에","correct":true},{"t":"국무총리가 최고 책임자이기 때문에","mis":"SO6-1-u2-X22"},{"t":"대통령의 일이 사라지기 때문에","mis":"SO6-1-u2-X22"},{"t":"행정 각부가 할 일이 없어서","mis":"SO6-1-u2-X23"}],"explanation":["자리가 비었어요.","일은 남아요.","멈출 수 없어요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#14','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C14',2,'mc','auto','신문 ⑥의 셋째·넷째 컷이 나타내는 것은 무엇인가요?',ARRAY['SO6-1-u2-X27']::text[],false,'{"seq":14,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"mc","stem":"신문 ⑥의 셋째·넷째 컷이 나타내는 것은 무엇인가요?","options":[{"t":"권력 분립과 견제와 균형","correct":true},{"t":"삼심 제도","mis":"SO6-1-u2-X27"},{"t":"선거 원칙","mis":"SO6-1-u2-X27"},{"t":"국민 주권만","mis":"SO6-1-u2-X27"}],"explanation":["셋이 나눠요.","서로 살펴요.","권력 분립이에요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#15','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C16',2,'mc','auto','신문 ⑦에서 이웃을 배려하는 말을 쓰자는 글이 보여 주는 미디어의 역할은 어느 것인가요?',ARRAY['SO6-1-u2-X32','SO6-1-u2-X33']::text[],false,'{"seq":15,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 이웃을 배려하는 말을 쓰자는 글이 보여 주는 미디어의 역할은 어느 것인가요?","options":[{"t":"가치나 규범을 보여 주는 역할","correct":true},{"t":"새로운 사실을 신속하게 전하는 역할","mis":"SO6-1-u2-X32"},{"t":"사회문제의 해결 방안을 제시하는 역할","mis":"SO6-1-u2-X32"},{"t":"여론을 막는 역할","mis":"SO6-1-u2-X33"}],"explanation":["배려하는 말이에요.","중요한 가치예요.","가치나 규범이에요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#16','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C17',2,'mc','auto','신문 ⑧에서 사실이 아닌 글이 빨리 퍼진 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X36','SO6-1-u2-X30']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C17","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 사실이 아닌 글이 빨리 퍼진 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 사실인지 확인하지 않고 그대로 믿고 전했기 때문에","correct":true},{"t":"글에 날짜가 적혀 있지 않았기 때문에","mis":"SO6-1-u2-X37"},{"t":"학교 누리집이 없었기 때문에","mis":"SO6-1-u2-X36"},{"t":"대화방은 미디어가 아니기 때문에","mis":"SO6-1-u2-X30"}],"explanation":["확인하지 않았어요.","그대로 전했어요.","그래서 퍼졌어요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#17','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C1',3,'error','auto','선거와 민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X03']::text[],false,'{"seq":17,"concept":"SO6-1-u2-C1","difficulty":3,"kind":"error","stem":"선거와 민주주의를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「대표를 뽑았으니 이제 국민은 나랏일에 관심을 끊어도 돼.」","correct":true,"mis_target":"SO6-1-u2-X03"},{"t":"친구 가 — 「선거는 민주주의의 꽃이야.」","mis":"SO6-1-u2-X03"},{"t":"친구 다 — 「국민이 주인으로서 권리를 행사하는 거야.」","mis":"SO6-1-u2-X03"}],"explanation":["국민은 여전히 주인이에요.","관심을 끊으면 안 돼요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#18','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C6',3,'error','auto','공약을 평가하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":18,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"error","stem":"공약을 평가하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「상대 후보를 세게 비판한 공약일수록 좋은 공약이야.」","correct":true,"mis_target":"SO6-1-u2-X15"},{"t":"친구 나 — 「실천할 수 있는지 봐야 해.」","mis":"SO6-1-u2-X15"},{"t":"친구 다 — 「국민의 요구를 반영했는지도 봐야 해.」","mis":"SO6-1-u2-X15"}],"explanation":["공약 자체를 재요.","비방은 잣대가 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#19','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C9',3,'error','auto','국회가 맡은 여러 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X21']::text[],false,'{"seq":19,"concept":"SO6-1-u2-C9","difficulty":3,"kind":"error","stem":"국회가 맡은 여러 일을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「인사 청문회는 법원의 판결을 다시 살피는 자리야.」","correct":true,"mis_target":"SO6-1-u2-X21"},{"t":"친구 가 — 「국정 감사로 행정부가 일을 잘 하는지 확인해.」","mis":"SO6-1-u2-X21"},{"t":"친구 나 — 「예산안을 살펴 나라 살림의 계획을 정해.」","mis":"SO6-1-u2-X21"}],"explanation":["인사 청문회는 사람을 살펴요.","판결과 관계없어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#20','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C14',3,'error','auto','견제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":20,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"error","stem":"견제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「국가기관을 견제하는 일은 국가기관만 할 수 있어.」","correct":true,"mis_target":"SO6-1-u2-X29"},{"t":"친구 가 — 「국민도 시민 단체 활동으로 지켜볼 수 있어.」","mis":"SO6-1-u2-X29"},{"t":"친구 다 — 「누리집 게시판에 의견을 올릴 수도 있어.」","mis":"SO6-1-u2-X29"}],"explanation":["국민도 할 수 있어요.","여러 방법이 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#21','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C16',3,'error','auto','민주주의와 미디어를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":21,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"error","stem":"민주주의와 미디어를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「미디어는 정보만 전할 뿐 사람들의 결정에는 영향을 주지 않아.」","correct":true,"mis_target":"SO6-1-u2-X33"},{"t":"친구 가 — 「미디어는 사회문제를 짚어 줘.」","mis":"SO6-1-u2-X32"},{"t":"친구 나 — 「누구나 1인 미디어로 정보를 만들 수 있어.」","mis":"SO6-1-u2-X33"}],"explanation":["정보와 생각이 모여요.","결정에 영향을 줘요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#22','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C19',3,'error','auto','기사를 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":22,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"error","stem":"기사를 쓰며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「모두가 기뻐했다고 쓰면 더 재미있으니 그렇게 쓰자.」","correct":true,"mis_target":"SO6-1-u2-X40"},{"t":"친구 나 — 「설문 결과를 출처로 밝히자.」","mis":"SO6-1-u2-X40"},{"t":"친구 다 — 「과장한 표현이 없는지 검토하자.」","mis":"SO6-1-u2-X40"}],"explanation":["부풀리면 안 돼요.","사실이 먼저예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#23','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C14',4,'mc','auto','신문 ④~⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29','SO6-1-u2-X17']::text[],false,'{"seq":23,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"mc","stem":"신문 ④~⑥을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세 국가기관이 하는 일을 나눠 맡고 서로 견제하여 국민의 자유와 권리를 지킨다","correct":true},{"t":"한 국가기관이 모든 일을 맡아야 빠르다","mis":"SO6-1-u2-X27"},{"t":"세 기관은 서로 관계없이 일한다","mis":"SO6-1-u2-X29"},{"t":"국가기관은 국민의 권리와 관계없다","mis":"SO6-1-u2-X17"}],"explanation":["④는 국회예요.","⑤는 행정부와 법원이에요.","⑥은 권력 분립이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#24','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C6',4,'essay','teacher','신문 ③의 세 공약을 잣대에 따라 평가하고, 내가 투표할 후보와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u2-C6","difficulty":4,"kind":"essay","stem":"신문 ③의 세 공약을 잣대에 따라 평가하고, 내가 투표할 후보와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 기호 2의 공약은 무엇을 어떻게 할지가 없어 구체적이지 않다. 기호 3의 공약은 날마다 모든 학생에게 간식을 주기 어려워 실천할 수 있는지 의문이다. 기호 1의 공약은 놀이 기구를 학년별로 나누어 빌려주겠다는 방법이 있고 실천할 수 있으며 학생들의 요구도 반영했다. 그래서 나는 기호 1에게 투표하겠다.","scoring_points":["세 공약을 잣대로 평가했는가","고른 후보를 밝혔는가","잣대와 이어 까닭을 썼는가"]},"explanation":["잣대를 떠올려요.","세 공약을 재요.","스스로 골라요."],"asset":{"type":"passage","lines":["기호 1 — 쉬는 시간 놀이 기구를 학년별로 나누어 빌려주겠습니다.","기호 2 — 학교를 더 좋게 만들겠습니다.","기호 3 — 모든 학생에게 날마다 간식을 주겠습니다."],"title":"신문 ③ — 후보 공약 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_b#25','soc',6,1,'u2','','g6_1_soc_u2_review_b','unit_review','SO6-1-u2-C12',4,'essay','teacher','신문 ⑤를 보고 행정부와 법원이 하는 일을 각각 쓰고, 공정한 재판을 위한 제도 한 가지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u2-C12","difficulty":4,"kind":"essay","stem":"신문 ⑤를 보고 행정부와 법원이 하는 일을 각각 쓰고, 공정한 재판을 위한 제도 한 가지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 행정부는 국회에서 만든 법에 따라 나라 살림을 맡아 하고, 행정 각부가 교육·환경 등의 업무를 나눠 맡는다. 법원은 다툼이나 범죄가 있을 때 재판으로 옳고 그름을 가려 사회 질서를 유지한다. 법원은 재판의 과정과 결과를 공개하는데, 국민이 재판을 지켜보며 믿을 수 있게 하여 재판을 공정하게 하기 위해서이다.","scoring_points":["행정부가 하는 일을 썼는가","법원이 하는 일을 썼는가","공정한 재판을 위한 제도와 까닭을 썼는가"]},"explanation":["살림을 맡아요.","옳고 그름을 가려요.","제도를 하나 골라요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#1','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C2',1,'ox','auto','선거로 뽑힌 대표는 헌법과 법률에 따라 국민을 위해 일해요.',ARRAY['SO6-1-u2-X04']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C2","difficulty":1,"kind":"ox","stem":"선거로 뽑힌 대표는 헌법과 법률에 따라 국민을 위해 일해요.","answer":"O","reason_options":[{"t":"대표는 국민의 행복한 삶을 위해 정해진 법에 따라 나랏일을 결정하기 때문에","correct":true},{"t":"대표는 뽑히고 나면 마음대로 일해도 되기 때문에","mis":"SO6-1-u2-X04"}],"mis":"SO6-1-u2-X04","explanation":["법에 따라 일해요.","국민을 위해서예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#2','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C5',1,'sa','auto','투표권을 가진 사람이 남에게 맡기지 않고 스스로 투표하는 선거 원칙은 「○○ 선거」예요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO6-1-u2-C5","difficulty":1,"kind":"sa","stem":"투표권을 가진 사람이 남에게 맡기지 않고 스스로 투표하는 선거 원칙은 「○○ 선거」예요. ○○에 알맞은 두 글자를 쓰세요.","answer":["직접"],"explanation":["스스로 해요.","◯접이에요.","직접이에요."],"mis":"SO6-1-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#3','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C6',1,'sa','auto','후보자의 기호, 사진, 공약 등을 담아 사람들이 보는 곳에 붙이는 종이를 「선거 ○○」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"sa","stem":"후보자의 기호, 사진, 공약 등을 담아 사람들이 보는 곳에 붙이는 종이를 「선거 ○○」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["벽보"],"explanation":["벽에 붙여요.","◯보예요.","벽보예요."],"mis":"SO6-1-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#4','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C8',1,'ox','auto','법을 만드는 일은 국회에서 해요.',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C8","difficulty":1,"kind":"ox","stem":"법을 만드는 일은 국회에서 해요.","answer":"O","reason_options":[{"t":"국회는 국민의 뜻에 따라 법을 만드는 국가기관이기 때문에","correct":true},{"t":"법은 법원에서 판결로 만들기 때문에","mis":"SO6-1-u2-X18"}],"mis":"SO6-1-u2-X18","explanation":["법을 만드는 곳이에요.","국민의 대표가 모여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#5','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C10',1,'ox','auto','국무총리는 대통령을 보좌하고 행정 각부를 관리해요.',ARRAY['SO6-1-u2-X22']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C10","difficulty":1,"kind":"ox","stem":"국무총리는 대통령을 보좌하고 행정 각부를 관리해요.","answer":"O","reason_options":[{"t":"국무총리는 행정부에서 대통령을 돕는 자리이기 때문에","correct":true},{"t":"국무총리는 법원에서 판결을 내리는 자리이기 때문에","mis":"SO6-1-u2-X22"}],"mis":"SO6-1-u2-X22","explanation":["대통령을 도와요.","행정 각부를 관리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#6','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C13',1,'ox','auto','공정한 재판을 위해 법관은 바깥의 간섭 없이 판결해야 해요.',ARRAY['SO6-1-u2-X25']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C13","difficulty":1,"kind":"ox","stem":"공정한 재판을 위해 법관은 바깥의 간섭 없이 판결해야 해요.","answer":"O","reason_options":[{"t":"법원은 독립적으로 운영되고 헌법으로 법관의 신분을 보장하기 때문에","correct":true},{"t":"법관은 다른 국가기관의 지시대로 판결해야 하기 때문에","mis":"SO6-1-u2-X25"}],"mis":"SO6-1-u2-X25","explanation":["간섭이 없어야 해요.","독립적이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#7','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C16',1,'ox','auto','미디어는 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전해요.',ARRAY['SO6-1-u2-X32']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"ox","stem":"미디어는 많은 사람에게 영향을 미치는 새로운 사실을 신속하게 전해요.","answer":"O","reason_options":[{"t":"신문·방송·인터넷으로 같은 소식을 많은 사람이 곧바로 알 수 있기 때문에","correct":true},{"t":"미디어는 오래된 소식만 전하기 때문에","mis":"SO6-1-u2-X32"}],"mis":"SO6-1-u2-X32","explanation":["새로운 사실이에요.","빠르게 전해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#8','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C18',1,'ox','auto','확인되지 않은 정보는 미디어로 함부로 공유하지 않아요.',ARRAY['SO6-1-u2-X37']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C18","difficulty":1,"kind":"ox","stem":"확인되지 않은 정보는 미디어로 함부로 공유하지 않아요.","answer":"O","reason_options":[{"t":"확인하지 않고 공유하면 허위 조작 정보가 더 빠르게 퍼지기 때문에","correct":true},{"t":"재미있는 정보는 확인하지 않아도 되기 때문에","mis":"SO6-1-u2-X37"}],"mis":"SO6-1-u2-X37","explanation":["확인이 먼저예요.","퍼뜨리지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#9','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C3',2,'ox','auto','신문 ①에서 늦게 투표한 한 학생의 표는 결과에 아무 영향도 주지 못했어요.',ARRAY['SO6-1-u2-X06']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C3","difficulty":2,"kind":"ox","stem":"신문 ①에서 늦게 투표한 한 학생의 표는 결과에 아무 영향도 주지 못했어요.","answer":"X","reason_options":[{"t":"같던 결과를 그 한 표가 갈랐기 때문에","correct":true},{"t":"한 사람의 표는 결과를 바꿀 수 없기 때문에","mis":"SO6-1-u2-X06"}],"mis":"SO6-1-u2-X06","explanation":["표가 같았어요.","한 표로 갈렸어요.","그래서 X예요."],"asset":{"type":"passage","lines":["전교생이 날마다 한자리에 모여 회의할 수는 없어 전교 회장을 뽑기로 했다.","지난 선거에서는 두 후보의 표가 같아 다시 세어 보았지만 결과는 그대로였다.","늦게 투표한 한 학생의 표로 결과가 갈렸다."],"title":"신문 ① — 전교 어린이 회장 선거가 다가왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#10','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C5',2,'ox','auto','신문 ②에서 기표소에서 혼자 투표하고 누구를 뽑았는지 말하지 않는 것은 비밀 선거의 원칙을 지키는 모습이에요.',ARRAY['SO6-1-u2-X12']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C5","difficulty":2,"kind":"ox","stem":"신문 ②에서 기표소에서 혼자 투표하고 누구를 뽑았는지 말하지 않는 것은 비밀 선거의 원칙을 지키는 모습이에요.","answer":"O","reason_options":[{"t":"누구에게 투표했는지 알 수 없도록 비밀을 보장하기 때문에","correct":true},{"t":"투표는 친구와 함께 정해야 하기 때문에","mis":"SO6-1-u2-X12"}],"mis":"SO6-1-u2-X12","explanation":["혼자 투표해요.","말하지 않아요.","그래서 O예요."],"asset":{"type":"passage","lines":["선거 관리 위원 학생들이 먼저 투표할 학생 명단을 만들었다.","후보 등록 → 선거 운동 → 투표 → 개표 → 당선자 발표 차례로 진행한다.","몸이 불편한 학생은 교실에서 투표할 수 있게 했다.","기표소에서 혼자 투표하고, 누구를 뽑았는지는 말하지 않는다."],"title":"신문 ② — 우리 학교 선거는 이렇게 치러요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#11','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C6',2,'ox','auto','신문 ③의 기호 1 공약은 무엇을 어떻게 할지 밝혀 구체적인 편이에요.',ARRAY['SO6-1-u2-X15']::text[],false,'{"seq":11,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"ox","stem":"신문 ③의 기호 1 공약은 무엇을 어떻게 할지 밝혀 구체적인 편이에요.","answer":"O","reason_options":[{"t":"놀이 기구를 학년별로 나누어 빌려주겠다는 방법을 밝혔기 때문에","correct":true},{"t":"공약은 짧을수록 구체적이기 때문에","mis":"SO6-1-u2-X15"}],"mis":"SO6-1-u2-X15","explanation":["방법이 있어요.","무엇을 어떻게 할지 밝혔어요.","그래서 O예요."],"asset":{"type":"passage","lines":["기호 1 — 쉬는 시간 놀이 기구를 학년별로 나누어 빌려주겠습니다.","기호 2 — 학교를 더 좋게 만들겠습니다.","기호 3 — 모든 학생에게 날마다 간식을 주겠습니다."],"title":"신문 ③ — 후보 공약 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#12','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C8',2,'ox','auto','신문 ④처럼 법은 국민의 요구에서 출발하기도 해요.',ARRAY['SO6-1-u2-X19']::text[],false,'{"seq":12,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"ox","stem":"신문 ④처럼 법은 국민의 요구에서 출발하기도 해요.","answer":"O","reason_options":[{"t":"국민의 요구에 따라 국회의원이 법률안을 내기도 하기 때문에","correct":true},{"t":"법은 국민과 관계없이 만들어지기 때문에","mis":"SO6-1-u2-X19"}],"mis":"SO6-1-u2-X19","explanation":["국민의 요구예요.","법률안을 내요.","그래서 O예요."],"asset":{"type":"passage","lines":["국회의원들이 법률안을 심의하는 회의장을 보았다.","국민의 요구로 낸 법률안이 심의와 투표를 거쳐 정해진다고 들었다.","나라 살림에 쓸 돈의 계획을 살피는 일도 한다고 했다."],"title":"신문 ④ — 국회 견학 다녀왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#13','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C13',2,'ox','auto','신문 ⑤에서 법원이 재판의 과정과 결과를 공개하는 것은 공정한 재판을 위한 제도예요.',ARRAY['SO6-1-u2-X25']::text[],false,'{"seq":13,"concept":"SO6-1-u2-C13","difficulty":2,"kind":"ox","stem":"신문 ⑤에서 법원이 재판의 과정과 결과를 공개하는 것은 공정한 재판을 위한 제도예요.","answer":"O","reason_options":[{"t":"국민이 재판을 지켜보며 믿을 수 있게 하기 때문에","correct":true},{"t":"재판은 감출수록 공정하기 때문에","mis":"SO6-1-u2-X25"}],"mis":"SO6-1-u2-X25","explanation":["공개해요.","지켜볼 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#14','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C14',2,'ox','auto','신문 ⑥의 넷째 컷처럼 세 곳이 서로 살피는 까닭은 서로를 미워하기 때문이에요.',ARRAY['SO6-1-u2-X29']::text[],false,'{"seq":14,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"ox","stem":"신문 ⑥의 넷째 컷처럼 세 곳이 서로 살피는 까닭은 서로를 미워하기 때문이에요.","answer":"X","reason_options":[{"t":"서로 바로잡아 권력이 올바르게 쓰이게 하려는 것이기 때문에","correct":true},{"t":"세 곳은 서로 도우면 안 되기 때문에","mis":"SO6-1-u2-X29"}],"mis":"SO6-1-u2-X29","explanation":["바로잡으려는 거예요.","미워해서가 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#15','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C16',2,'ox','auto','신문 ⑦에서 소식지를 읽은 주민들이 모여 의견을 나눈 것은 미디어가 사람들의 생각을 모으는 모습이에요.',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":15,"concept":"SO6-1-u2-C16","difficulty":2,"kind":"ox","stem":"신문 ⑦에서 소식지를 읽은 주민들이 모여 의견을 나눈 것은 미디어가 사람들의 생각을 모으는 모습이에요.","answer":"O","reason_options":[{"t":"미디어로 주고받은 정보와 생각이 의사 결정에 영향을 미치기 때문에","correct":true},{"t":"소식지는 읽는 사람의 생각과 관계없기 때문에","mis":"SO6-1-u2-X33"}],"mis":"SO6-1-u2-X33","explanation":["소식지를 읽었어요.","모여 의견을 나눴어요.","그래서 O예요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#16','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C19',2,'ox','auto','신문 ⑧에서 기자단이 출처를 밝혀 바로잡는 기사를 쓴 것은 읽는 사람에게 신뢰를 주는 방법이에요.',ARRAY['SO6-1-u2-X40']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C19","difficulty":2,"kind":"ox","stem":"신문 ⑧에서 기자단이 출처를 밝혀 바로잡는 기사를 쓴 것은 읽는 사람에게 신뢰를 주는 방법이에요.","answer":"O","reason_options":[{"t":"어디에서 확인한 내용인지 알면 사실인지 판단할 수 있기 때문에","correct":true},{"t":"출처는 기사를 길게 만들기만 하기 때문에","mis":"SO6-1-u2-X40"}],"mis":"SO6-1-u2-X40","explanation":["출처를 밝혔어요.","확인할 수 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#17','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C2',3,'ox','auto','선거로 뽑힌 대표가 지역 발전을 위해 힘쓰면 사람들이 더 살기 좋은 환경에서 생활할 수 있어요.',ARRAY['SO6-1-u2-X04']::text[],false,'{"seq":17,"concept":"SO6-1-u2-C2","difficulty":3,"kind":"ox","stem":"선거로 뽑힌 대표가 지역 발전을 위해 힘쓰면 사람들이 더 살기 좋은 환경에서 생활할 수 있어요.","answer":"O","reason_options":[{"t":"대표가 지역의 중요한 일을 결정하고 실행하기 때문에","correct":true},{"t":"대표가 누구든 지역은 저절로 발전하기 때문에","mis":"SO6-1-u2-X04"}],"mis":"SO6-1-u2-X04","explanation":["대표가 힘써요.","지역이 달라져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#18','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C5',3,'ox','auto','투표소에 가기 어려운 유권자를 위해 여러 투표 방법을 두는 것은 선거권을 보장하려는 노력이에요.',ARRAY['SO6-1-u2-X14']::text[],false,'{"seq":18,"concept":"SO6-1-u2-C5","difficulty":3,"kind":"ox","stem":"투표소에 가기 어려운 유권자를 위해 여러 투표 방법을 두는 것은 선거권을 보장하려는 노력이에요.","answer":"O","reason_options":[{"t":"모든 사람이 평등하게 선거에 참여할 수 있게 하기 때문에","correct":true},{"t":"투표하는 사람을 줄이려는 것이기 때문에","mis":"SO6-1-u2-X14"}],"mis":"SO6-1-u2-X14","explanation":["누구나 참여해요.","선거권이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#19','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C8',3,'ox','auto','법을 만드는 국회와 마지막에 서명하는 대통령의 자리가 나뉜 것은 권력이 한곳에 모이지 않게 하는 것과 이어져요.',ARRAY['SO6-1-u2-X20']::text[],false,'{"seq":19,"concept":"SO6-1-u2-C8","difficulty":3,"kind":"ox","stem":"법을 만드는 국회와 마지막에 서명하는 대통령의 자리가 나뉜 것은 권력이 한곳에 모이지 않게 하는 것과 이어져요.","answer":"O","reason_options":[{"t":"국회가 만든 법률안을 대통령이 서명하거나 되돌려 보내며 서로 살피기 때문에","correct":true},{"t":"대통령이 법을 대신 만들기 때문에","mis":"SO6-1-u2-X20"}],"mis":"SO6-1-u2-X20","explanation":["자리가 나뉘어요.","서로 살펴요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#20','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C14',3,'ox','auto','권력 분립이 잘 이루어지면 어느 한 국가기관도 나라의 중요한 일을 마음대로 처리하기 어려워요.',ARRAY['SO6-1-u2-X27']::text[],false,'{"seq":20,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"ox","stem":"권력 분립이 잘 이루어지면 어느 한 국가기관도 나라의 중요한 일을 마음대로 처리하기 어려워요.","answer":"O","reason_options":[{"t":"세 기관이 권력을 나눠 맡고 서로 견제하며 균형을 이루기 때문에","correct":true},{"t":"한 기관이 다른 기관의 일을 모두 맡기 때문에","mis":"SO6-1-u2-X27"}],"mis":"SO6-1-u2-X27","explanation":["나눠 맡아요.","서로 견제해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#21','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C17',3,'ox','auto','사실이 아니라고 밝혀진 정보는 그 정보를 믿고 내린 결정까지 모두 저절로 되돌려 놓아요.',ARRAY['SO6-1-u2-X35']::text[],false,'{"seq":21,"concept":"SO6-1-u2-C17","difficulty":3,"kind":"ox","stem":"사실이 아니라고 밝혀진 정보는 그 정보를 믿고 내린 결정까지 모두 저절로 되돌려 놓아요.","answer":"X","reason_options":[{"t":"정보를 지워도 그 정보를 믿고 이미 정한 일은 그대로 남기 때문에","correct":true},{"t":"사실이 밝혀지면 모든 것이 처음으로 돌아가기 때문에","mis":"SO6-1-u2-X35"}],"mis":"SO6-1-u2-X35","explanation":["정보는 지워요.","결정은 남아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#22','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C18',3,'ox','auto','다양한 관점의 정보를 균형 있게 살피면 편견을 줄이는 데 도움이 돼요.',ARRAY['SO6-1-u2-X38']::text[],false,'{"seq":22,"concept":"SO6-1-u2-C18","difficulty":3,"kind":"ox","stem":"다양한 관점의 정보를 균형 있게 살피면 편견을 줄이는 데 도움이 돼요.","answer":"O","reason_options":[{"t":"한쪽 관점의 정보만 보면 생각이 치우치기 때문에","correct":true},{"t":"내 관점과 같은 정보만 보는 것이 가장 정확하기 때문에","mis":"SO6-1-u2-X38"}],"mis":"SO6-1-u2-X38","explanation":["여러 관점이에요.","균형 있게 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#23','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C17',4,'mc','auto','신문 ⑦과 ⑧을 함께 볼 때 미디어에 대한 결론으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X36','SO6-1-u2-X37','SO6-1-u2-X33']::text[],false,'{"seq":23,"concept":"SO6-1-u2-C17","difficulty":4,"kind":"mc","stem":"신문 ⑦과 ⑧을 함께 볼 때 미디어에 대한 결론으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"미디어는 사회문제를 알리고 생각을 모으지만, 사실과 다른 정보도 있어 따져 보고 이용해야 한다","correct":true},{"t":"미디어는 모두 거짓이니 쓰지 말아야 한다","mis":"SO6-1-u2-X36"},{"t":"미디어에 실린 것은 모두 사실이다","mis":"SO6-1-u2-X37"},{"t":"미디어는 민주주의와 관계없다","mis":"SO6-1-u2-X33"}],"explanation":["⑦은 미디어의 역할이에요.","⑧은 사실과 다른 정보예요.","따져 보고 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#24','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C8',4,'essay','teacher','신문 ④를 보고 법이 만들어지는 과정을 차례대로 쓰고, 국회가 하는 다른 일 한 가지를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u2-C8","difficulty":4,"kind":"essay","stem":"신문 ④를 보고 법이 만들어지는 과정을 차례대로 쓰고, 국회가 하는 다른 일 한 가지를 쓰세요.","answer_guide":{"answer":"예: 국민의 요구가 늘어나면 국회의원이 법률안을 국회에 낸다. 국회에서 국회의원들이 법률안을 심의하고 투표하여 결정하면, 대통령이 서명하여 새 법률을 널리 알리고 시행한다. 국회는 이 밖에도 한 해 나라 살림에 쓸 돈의 계획인 예산안을 살펴 정하는 일을 한다.","scoring_points":["법이 만들어지는 차례를 썼는가","국회와 대통령의 자리를 구분했는가","국회가 하는 다른 일을 썼는가"]},"explanation":["요구가 출발이에요.","심의하고 서명해요.","다른 일도 써요."],"asset":{"type":"passage","lines":["국회의원들이 법률안을 심의하는 회의장을 보았다.","국민의 요구로 낸 법률안이 심의와 투표를 거쳐 정해진다고 들었다.","나라 살림에 쓸 돈의 계획을 살피는 일도 한다고 했다."],"title":"신문 ④ — 국회 견학 다녀왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_c#25','soc',6,1,'u2','','g6_1_soc_u2_review_c','unit_review','SO6-1-u2-C16',4,'essay','teacher','신문 ⑦에서 미디어의 역할 세 가지를 찾아 쓰고, 소식지가 주민들의 결정에 어떤 영향을 주었는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u2-C16","difficulty":4,"kind":"essay","stem":"신문 ⑦에서 미디어의 역할 세 가지를 찾아 쓰고, 소식지가 주민들의 결정에 어떤 영향을 주었는지 쓰세요.","answer_guide":{"answer":"예: 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓은 것은 사회문제를 지목하고 해결 방안을 제시하는 역할이다. 이웃을 배려하는 말을 쓰자는 글은 가치나 규범을 보여 주는 역할이고, 분리배출 날짜를 알린 것은 새로운 사실을 신속하게 전하는 역할이다. 소식지를 읽은 주민들은 모여 의견을 나누었고, 이렇게 모인 생각이 하천 문제를 어떻게 해결할지 정하는 데 영향을 주었다.","scoring_points":["미디어의 역할 세 가지를 찾았는가","신문의 장면과 바르게 이었는가","주민들의 결정에 준 영향을 썼는가"]},"explanation":["세 장면을 찾아요.","역할을 붙여요.","결정과 이어요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#1','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C3',1,'blank','auto','국민 주권이란 나라의 중요한 일을 결정하는 최고의 권력인 주권이 (    )에게 있다는 뜻이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO6-1-u2-X07']::text[],false,'{"seq":1,"concept":"SO6-1-u2-C3","difficulty":1,"kind":"blank","stem":"국민 주권이란 나라의 중요한 일을 결정하는 최고의 권력인 주권이 (    )에게 있다는 뜻이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"국민","correct":true},{"t":"대통령","mis":"SO6-1-u2-X07"},{"t":"국회의원","mis":"SO6-1-u2-X07"},{"t":"공무원","mis":"SO6-1-u2-X07"}],"explanation":["나라의 주인이에요.","모든 사람이에요.","국민이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#2','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C4',1,'ox','auto','선거인 명부는 투표할 수 있는 사람들의 명단이에요.',ARRAY['SO6-1-u2-X10']::text[],false,'{"seq":2,"concept":"SO6-1-u2-C4","difficulty":1,"kind":"ox","stem":"선거인 명부는 투표할 수 있는 사람들의 명단이에요.","answer":"O","reason_options":[{"t":"선거 관리 위원회가 투표할 수 있는 사람을 정리해 만들기 때문에","correct":true},{"t":"후보자들의 이름만 모아 놓은 것이기 때문에","mis":"SO6-1-u2-X10"}],"mis":"SO6-1-u2-X10","explanation":["투표할 사람의 명단이에요.","선거 관리 위원회가 만들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#3','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C6',1,'mc','auto','투표할 때 지켜야 할 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X16']::text[],false,'{"seq":3,"concept":"SO6-1-u2-C6","difficulty":1,"kind":"mc","stem":"투표할 때 지켜야 할 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 후보자에게만 표시한다","correct":true},{"t":"마음에 드는 후보자 모두에게 표시한다","mis":"SO6-1-u2-X16"},{"t":"친구와 같은 후보자를 고른다","mis":"SO6-1-u2-X16"},{"t":"투표한 뒤 누구를 뽑았는지 크게 말한다","mis":"SO6-1-u2-X16"}],"explanation":["여럿이면 무효예요.","한 사람만이에요.","한 후보자에게만이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#4','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C9',1,'mc','auto','국회가 일을 맡을 사람의 능력을 살펴보는 자리는 무엇인가요?',ARRAY['SO6-1-u2-X21','SO6-1-u2-X23']::text[],false,'{"seq":4,"concept":"SO6-1-u2-C9","difficulty":1,"kind":"mc","stem":"국회가 일을 맡을 사람의 능력을 살펴보는 자리는 무엇인가요?","options":[{"t":"인사 청문회","correct":true},{"t":"국정 감사","mis":"SO6-1-u2-X21"},{"t":"국무 회의","mis":"SO6-1-u2-X23"},{"t":"예산안 심의","mis":"SO6-1-u2-X21"}],"explanation":["사람을 살펴요.","능력을 봐요.","인사 청문회예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#5','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C11',1,'mc','auto','나라의 중요한 정책을 대통령과 국무 위원들이 함께 의논하는 자리는 어디인가요?',ARRAY['SO6-1-u2-X23','SO6-1-u2-X21','SO6-1-u2-X18']::text[],false,'{"seq":5,"concept":"SO6-1-u2-C11","difficulty":1,"kind":"mc","stem":"나라의 중요한 정책을 대통령과 국무 위원들이 함께 의논하는 자리는 어디인가요?","options":[{"t":"국무 회의","correct":true},{"t":"국정 감사","mis":"SO6-1-u2-X23"},{"t":"인사 청문회","mis":"SO6-1-u2-X21"},{"t":"재판","mis":"SO6-1-u2-X18"}],"explanation":["함께 의논해요.","국무 위원이 모여요.","국무 회의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#6','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C12',1,'mc','auto','법원이 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":6,"concept":"SO6-1-u2-C12","difficulty":1,"kind":"mc","stem":"법원이 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"법을 어긴 사람을 처벌하여 사회 질서를 유지한다","correct":true},{"t":"법률안을 심의하고 투표한다","mis":"SO6-1-u2-X18"},{"t":"행정 각부를 관리한다","mis":"SO6-1-u2-X18"},{"t":"나라 살림의 계획을 정한다","mis":"SO6-1-u2-X18"}],"explanation":["재판을 해요.","질서를 지켜요.","처벌해 질서를 유지해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#7','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C16',1,'mc','auto','민주주의에서 미디어의 역할로 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33']::text[],false,'{"seq":7,"concept":"SO6-1-u2-C16","difficulty":1,"kind":"mc","stem":"민주주의에서 미디어의 역할로 알맞은 것은 어느 것인가요?","options":[{"t":"사회문제를 지목하고 해결 방안을 제시한다","correct":true},{"t":"정보를 감추어 결정을 막는다","mis":"SO6-1-u2-X33"},{"t":"한 사람에게만 정보를 준다","mis":"SO6-1-u2-X33"},{"t":"사람들이 생각을 나누지 못하게 한다","mis":"SO6-1-u2-X33"}],"explanation":["문제를 짚어요.","해결 방법을 내요.","사회문제를 다뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#8','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C17',1,'mc','auto','사실과 다른 내용을 진짜처럼 꾸며 전달하는 정보를 가리키는 말은 무엇인가요?',ARRAY['SO6-1-u2-X34']::text[],false,'{"seq":8,"concept":"SO6-1-u2-C17","difficulty":1,"kind":"mc","stem":"사실과 다른 내용을 진짜처럼 꾸며 전달하는 정보를 가리키는 말은 무엇인가요?","options":[{"t":"허위 조작 정보","correct":true},{"t":"여론","mis":"SO6-1-u2-X34"},{"t":"관점","mis":"SO6-1-u2-X34"},{"t":"출처","mis":"SO6-1-u2-X34"}],"explanation":["꾸민 정보예요.","사실과 달라요.","허위 조작 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#9','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C2',2,'mc','auto','신문 ①을 읽고 전교 회장으로 뽑을 사람을 고를 때의 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X05','SO6-1-u2-X04']::text[],false,'{"seq":9,"concept":"SO6-1-u2-C2","difficulty":2,"kind":"mc","stem":"신문 ①을 읽고 전교 회장으로 뽑을 사람을 고를 때의 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"학생들을 위해 열심히 일하고 공정한 사람을 고른다","correct":true},{"t":"가장 유명한 사람을 고른다","mis":"SO6-1-u2-X05"},{"t":"나와 가장 친한 사람을 고른다","mis":"SO6-1-u2-X05"},{"t":"누구를 뽑든 같으니 아무나 고른다","mis":"SO6-1-u2-X04"}],"explanation":["대표가 일을 정해요.","모두를 위해 일해요.","공정한 사람이에요."],"asset":{"type":"passage","lines":["전교생이 날마다 한자리에 모여 회의할 수는 없어 전교 회장을 뽑기로 했다.","지난 선거에서는 두 후보의 표가 같아 다시 세어 보았지만 결과는 그대로였다.","늦게 투표한 한 학생의 표로 결과가 갈렸다."],"title":"신문 ① — 전교 어린이 회장 선거가 다가왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#10','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C4',2,'mc','auto','신문 ②의 학교 선거가 차례를 정해 두고 치러지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X11','SO6-1-u2-X09']::text[],false,'{"seq":10,"concept":"SO6-1-u2-C4","difficulty":2,"kind":"mc","stem":"신문 ②의 학교 선거가 차례를 정해 두고 치러지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"누구에게나 같은 조건으로 공정하게 선거를 치르려고","correct":true},{"t":"선거를 빨리 끝내려고","mis":"SO6-1-u2-X11"},{"t":"후보가 차례를 마음대로 바꾸게 하려고","mis":"SO6-1-u2-X11"},{"t":"개표를 투표보다 먼저 하려고","mis":"SO6-1-u2-X09"}],"explanation":["차례가 정해져 있어요.","모두에게 같아요.","공정하게 치르려고요."],"asset":{"type":"passage","lines":["선거 관리 위원 학생들이 먼저 투표할 학생 명단을 만들었다.","후보 등록 → 선거 운동 → 투표 → 개표 → 당선자 발표 차례로 진행한다.","몸이 불편한 학생은 교실에서 투표할 수 있게 했다.","기표소에서 혼자 투표하고, 누구를 뽑았는지는 말하지 않는다."],"title":"신문 ② — 우리 학교 선거는 이렇게 치러요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#11','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C6',2,'mc','auto','신문 ③을 읽은 유권자의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X15','SO6-1-u2-X16']::text[],false,'{"seq":11,"concept":"SO6-1-u2-C6","difficulty":2,"kind":"mc","stem":"신문 ③을 읽은 유권자의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"세 공약을 잣대로 따져 보고 스스로 한 후보를 고른다","correct":true},{"t":"간식을 준다니 무조건 기호 3을 고른다","mis":"SO6-1-u2-X15"},{"t":"친구들이 고르는 후보를 따라 고른다","mis":"SO6-1-u2-X16"},{"t":"두 후보에게 함께 표시한다","mis":"SO6-1-u2-X16"}],"explanation":["잣대로 따져요.","스스로 골라요.","한 후보예요."],"asset":{"type":"passage","lines":["기호 1 — 쉬는 시간 놀이 기구를 학년별로 나누어 빌려주겠습니다.","기호 2 — 학교를 더 좋게 만들겠습니다.","기호 3 — 모든 학생에게 날마다 간식을 주겠습니다."],"title":"신문 ③ — 후보 공약 살펴보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#12','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C8',2,'mc','auto','신문 ④에서 견학한 곳이 국민을 대표하는 기관이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":12,"concept":"SO6-1-u2-C8","difficulty":2,"kind":"mc","stem":"신문 ④에서 견학한 곳이 국민을 대표하는 기관이라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국민이 뽑은 국회의원들이 국민을 대신해 법을 만들기 때문에","correct":true},{"t":"국회의원은 나라에서 정해 주기 때문에","mis":"SO6-1-u2-X18"},{"t":"국회는 재판을 하기 때문에","mis":"SO6-1-u2-X18"},{"t":"국회는 나라 살림을 직접 맡기 때문에","mis":"SO6-1-u2-X18"}],"explanation":["국민이 뽑았어요.","국민을 대신해요.","법을 만들어요."],"asset":{"type":"passage","lines":["국회의원들이 법률안을 심의하는 회의장을 보았다.","국민의 요구로 낸 법률안이 심의와 투표를 거쳐 정해진다고 들었다.","나라 살림에 쓸 돈의 계획을 살피는 일도 한다고 했다."],"title":"신문 ④ — 국회 견학 다녀왔어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#13','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C12',2,'mc','auto','신문 ⑤를 읽고 행정부와 법원을 바르게 견준 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18']::text[],false,'{"seq":13,"concept":"SO6-1-u2-C12","difficulty":2,"kind":"mc","stem":"신문 ⑤를 읽고 행정부와 법원을 바르게 견준 것은 어느 것인가요?","options":[{"t":"행정부는 법에 따라 나라 살림을 맡고, 법원은 법에 따라 옳고 그름을 가린다","correct":true},{"t":"행정부는 판결하고 법원은 살림을 맡는다","mis":"SO6-1-u2-X18"},{"t":"두 기관은 하는 일이 같다","mis":"SO6-1-u2-X18"},{"t":"법원은 법을 만들고 행정부는 서명만 한다","mis":"SO6-1-u2-X18"}],"explanation":["살림을 맡아요.","옳고 그름을 가려요.","하는 일이 달라요."],"asset":{"type":"passage","lines":["행정 각부가 만든 카드 뉴스로 교육·환경 소식을 알게 되었다.","대통령이 자리를 비운 사이 국무총리가 그 일을 대신 맡는다는 것도 배웠다.","법원 누리집에서 재판의 과정과 결과를 공개한다는 안내를 보았다."],"title":"신문 ⑤ — 나랏일을 나눠 맡는 곳들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#14','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C14',2,'mc','auto','신문 ⑥의 넷째 컷에서 「서로 살핀다」의 예로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X28']::text[],false,'{"seq":14,"concept":"SO6-1-u2-C14","difficulty":2,"kind":"mc","stem":"신문 ⑥의 넷째 컷에서 「서로 살핀다」의 예로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국회가 국정 감사로 행정부가 일을 잘 하는지 확인한다","correct":true},{"t":"법원이 법을 만든다","mis":"SO6-1-u2-X28"},{"t":"행정부가 판결을 내린다","mis":"SO6-1-u2-X28"},{"t":"국회가 재판을 한다","mis":"SO6-1-u2-X28"}],"explanation":["살피는 모습이에요.","국회가 행정부를 봐요.","국정 감사예요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#15','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C15',2,'mc','auto','신문 ⑦의 마을 소식지를 미디어라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X30']::text[],false,'{"seq":15,"concept":"SO6-1-u2-C15","difficulty":2,"kind":"mc","stem":"신문 ⑦의 마을 소식지를 미디어라고 할 수 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"주민들이 정보를 주고받으며 의사소통하는 수단이기 때문에","correct":true},{"t":"종이로 만들었기 때문에","mis":"SO6-1-u2-X30"},{"t":"마을에서 만들었기 때문에","mis":"SO6-1-u2-X30"},{"t":"새것이기 때문에","mis":"SO6-1-u2-X30"}],"explanation":["겉모습이 아니에요.","정보를 주고받아요.","의사소통 수단이에요."],"asset":{"type":"passage","lines":["마을 하천에 쓰레기가 쌓인 문제를 알리고 해결 방법을 내놓았다.","이웃을 배려하는 말을 쓰자는 글도 실었다.","새로 정해진 분리배출 날짜를 신속하게 알렸다.","소식지를 읽은 주민들이 모여 의견을 나누었다."],"title":"신문 ⑦ — 솔빛 마을 소식지가 한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#16','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C18',2,'mc','auto','신문 ⑧에서 사실이 아님을 알아낸 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X37','SO6-1-u2-X34','SO6-1-u2-X38']::text[],false,'{"seq":16,"concept":"SO6-1-u2-C18","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 사실이 아님을 알아낸 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"믿을 만한 다른 자료인 학교 누리집으로 확인했다","correct":true},{"t":"글쓴이의 이름을 믿었다","mis":"SO6-1-u2-X37"},{"t":"대화방 글을 다시 퍼뜨렸다","mis":"SO6-1-u2-X34"},{"t":"믿고 싶지 않아 거짓이라고 정했다","mis":"SO6-1-u2-X38"}],"explanation":["다른 자료를 봤어요.","학교 누리집이에요.","확인했어요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#17','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C2',3,'mc','auto','좋은 대표를 뽑는 일이 민주주의를 지키는 일이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X04','SO6-1-u2-X05','SO6-1-u2-X03']::text[],false,'{"seq":17,"concept":"SO6-1-u2-C2","difficulty":3,"kind":"mc","stem":"좋은 대표를 뽑는 일이 민주주의를 지키는 일이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"대표를 잘못 뽑으면 국민의 삶이 어려워지고 민주주의가 위기를 맞을 수 있기 때문에","correct":true},{"t":"대표는 국민과 관계없이 일하기 때문에","mis":"SO6-1-u2-X04"},{"t":"대표는 인기만 있으면 되기 때문에","mis":"SO6-1-u2-X05"},{"t":"선거는 민주주의와 관계없기 때문에","mis":"SO6-1-u2-X03"}],"explanation":["대표가 중요한 일을 정해요.","잘못 뽑으면 어려워요.","민주주의가 위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#18','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C6',3,'mc','auto','모의 선거에서 공약 평가 걸음이 투표보다 먼저 있는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X09','SO6-1-u2-X15','SO6-1-u2-X11']::text[],false,'{"seq":18,"concept":"SO6-1-u2-C6","difficulty":3,"kind":"mc","stem":"모의 선거에서 공약 평가 걸음이 투표보다 먼저 있는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"공약을 따져 본 뒤 그것을 바탕으로 투표하기 위해서","correct":true},{"t":"투표 뒤에는 공약을 볼 수 없기 때문에","mis":"SO6-1-u2-X09"},{"t":"공약 평가로 당선자를 정하기 때문에","mis":"SO6-1-u2-X15"},{"t":"투표를 빨리 끝내기 위해서","mis":"SO6-1-u2-X11"}],"explanation":["먼저 따져요.","그다음 골라요.","바탕이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#19','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C12',3,'mc','auto','세 국가기관이 하는 일을 견주어 바르게 설명한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X18','SO6-1-u2-X17']::text[],false,'{"seq":19,"concept":"SO6-1-u2-C12","difficulty":3,"kind":"mc","stem":"세 국가기관이 하는 일을 견주어 바르게 설명한 것은 어느 것인가요?","options":[{"t":"국회는 법을 만들고, 행정부는 법에 따라 살림을 맡고, 법원은 법에 따라 판결한다","correct":true},{"t":"국회는 판결하고, 법원은 법을 만든다","mis":"SO6-1-u2-X18"},{"t":"행정부가 법을 만들고 판결도 한다","mis":"SO6-1-u2-X18"},{"t":"세 기관은 법과 관계없이 일한다","mis":"SO6-1-u2-X17"}],"explanation":["법을 만들어요.","살림을 맡아요.","판결해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#20','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C14',3,'mc','auto','권력 분립과 국민의 자유·권리의 관계를 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X27','SO6-1-u2-X29']::text[],false,'{"seq":20,"concept":"SO6-1-u2-C14","difficulty":3,"kind":"mc","stem":"권력 분립과 국민의 자유·권리의 관계를 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"권력이 나뉘어 서로 견제할수록 국민의 자유와 권리가 침해받을 가능성이 줄어든다","correct":true},{"t":"권력이 한곳에 모일수록 국민의 권리가 커진다","mis":"SO6-1-u2-X27"},{"t":"권력 분립은 국민의 권리와 관계없다","mis":"SO6-1-u2-X29"},{"t":"권력을 나누면 국민의 권리가 줄어든다","mis":"SO6-1-u2-X29"}],"explanation":["나뉘면 마음대로 못 해요.","침해가 줄어요.","자유와 권리를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#21','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C16',3,'mc','auto','미디어가 민주주의에서 「안내소」에 빗대어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO6-1-u2-X33','SO6-1-u2-X32']::text[],false,'{"seq":21,"concept":"SO6-1-u2-C16","difficulty":3,"kind":"mc","stem":"미디어가 민주주의에서 「안내소」에 빗대어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람들이 함께 결정하는 데 필요한 정보를 얻도록 길을 알려 주기 때문에","correct":true},{"t":"사람들이 정보를 얻지 못하게 막기 때문에","mis":"SO6-1-u2-X33"},{"t":"한 사람의 생각만 전하기 때문에","mis":"SO6-1-u2-X33"},{"t":"옛날 일만 알려 주기 때문에","mis":"SO6-1-u2-X32"}],"explanation":["안내소는 길을 알려 줘요.","필요한 정보를 줘요.","결정을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#22','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C19',3,'mc','auto','같은 사건을 다룬 두 친구의 기사가 서로 다를 때 가장 알맞은 태도는 어느 것인가요?',ARRAY['SO6-1-u2-X39','SO6-1-u2-X36','SO6-1-u2-X38']::text[],false,'{"seq":22,"concept":"SO6-1-u2-C19","difficulty":3,"kind":"mc","stem":"같은 사건을 다룬 두 친구의 기사가 서로 다를 때 가장 알맞은 태도는 어느 것인가요?","options":[{"t":"무엇을 실었는지 견주고 사실·과장·출처를 기준에 따라 살펴본다","correct":true},{"t":"먼저 쓴 기사가 옳다고 정한다","mis":"SO6-1-u2-X39"},{"t":"둘 다 거짓이라고 정한다","mis":"SO6-1-u2-X36"},{"t":"내 생각과 같은 기사만 믿는다","mis":"SO6-1-u2-X38"}],"explanation":["실은 것이 달라요.","기준으로 살펴요.","견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#23','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C1',4,'mc','auto','「민주주의와 시민 참여」 단원을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO6-1-u2-X01','SO6-1-u2-X27','SO6-1-u2-X37']::text[],false,'{"seq":23,"concept":"SO6-1-u2-C1","difficulty":4,"kind":"mc","stem":"「민주주의와 시민 참여」 단원을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"국민은 선거로 대표를 뽑고, 권력이 나뉜 국가기관을 지켜보며, 미디어를 비판적으로 이용해 민주주의에 참여한다","correct":true},{"t":"국민은 대표를 뽑은 뒤 나랏일에서 손을 뗀다","mis":"SO6-1-u2-X01"},{"t":"국가기관 하나가 모든 권력을 갖는 것이 좋다","mis":"SO6-1-u2-X27"},{"t":"미디어의 정보는 그대로 믿으면 된다","mis":"SO6-1-u2-X37"}],"explanation":["선거예요.","국가기관과 권력 분립이에요.","미디어예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#24','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C14',4,'essay','teacher','신문 ⑥의 네 컷을 보고 권력이 한곳에 모일 때의 문제와 권력을 나누어 얻는 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO6-1-u2-C14","difficulty":4,"kind":"essay","stem":"신문 ⑥의 네 컷을 보고 권력이 한곳에 모일 때의 문제와 권력을 나누어 얻는 점을 쓰세요.","answer_guide":{"answer":"예: 첫째·둘째 컷처럼 한 사람이 법도 만들고 살림도 맡고 판결도 내리면 아무도 막지 못해 권력을 마음대로 쓰고 잘못된 결정을 내려도 바로잡기 어렵다. 셋째·넷째 컷처럼 힘을 국회·행정부·법원이 나눠 맡으면 서로 견제하고 균형을 이루어 국민의 자유와 권리를 지킬 수 있다.","scoring_points":["권력 집중의 문제를 썼는가","세 곳이 나눠 맡음을 썼는가","견제와 균형·자유와 권리를 이어 썼는가"]},"explanation":["둘째 컷이 문제예요.","넷째 컷이 해결이에요.","얻는 점을 써요."],"asset":{"type":"passage","lines":["첫째 컷 — 한 사람이 법도 만들고 살림도 맡고 판결도 내린다.","둘째 컷 — 아무도 그 사람을 막지 못한다.","셋째 컷 — 힘을 세 곳이 나눠 맡는다.","넷째 컷 — 세 곳이 서로 살피며 균형을 이룬다."],"title":"신문 ⑥ — 네 컷 만화 「힘이 한곳에 모이면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_soc_u2_review_d#25','soc',6,1,'u2','','g6_1_soc_u2_review_d','unit_review','SO6-1-u2-C18',4,'essay','teacher','신문 ⑧처럼 확인되지 않은 소식을 받았을 때 살펴볼 기준 두 가지와 내가 할 행동을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO6-1-u2-C18","difficulty":4,"kind":"essay","stem":"신문 ⑧처럼 확인되지 않은 소식을 받았을 때 살펴볼 기준 두 가지와 내가 할 행동을 쓰세요.","answer_guide":{"answer":"예: 먼저 「속보」처럼 뉴스 형식을 흉내 내고 있는지 살피고, 믿을 만한 출처에서 얻은 정보인지 확인하겠다. 신문 ⑧의 글은 두 기준에 모두 걸리므로 그대로 믿거나 다른 사람에게 보내지 않고, 학교 누리집 같은 믿을 만한 다른 자료로 사실인지 확인하겠다.","scoring_points":["살펴볼 기준 두 가지를 썼는가","신문 ⑧의 글에 기준을 적용했는가","공유하지 않고 확인하는 행동을 썼는가"]},"explanation":["기준을 떠올려요.","⑧에 적용해요.","할 행동을 써요."],"asset":{"type":"passage","lines":["「속보 — 다음 주부터 운동장 사용 금지」라는 글이 대화방에 퍼졌다.","글쓴이와 날짜는 적혀 있었지만 출처는 「들은 이야기」뿐이었다.","학교 누리집에서 확인해 보니 사실이 아니었다.","솔빛반 기자단은 출처를 밝혀 바로잡는 기사를 썼다."],"title":"신문 ⑧ — 소문, 그대로 믿어도 될까?"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
